window.__D("text/torat-shmuel/c047",{"p":[[2000480164,"בכנס\"י צ\"ל כמארז\"ל ע\"פ אשר אנכי מצוך היום<sup data-n=\"990\">62</sup> בכי\"ו יהיו בעיניך כחדשים<sup data-n=\"991\">63</sup>, וכמ\"ש עיני האדם לא תשבענה<sup data-n=\"992\">64</sup> מלאסתכלא ביקרא דמלכא<sup data-n=\"993\">60</sup>, ולכאו' צ\"ל איך יכול להיות שיהי' בכי\"ו כחדשים ממש, ויובן בהקדם ענין ממכ\"ע וסוכ\"ע<sup data-n=\"994\">65</sup> בקצרה, שבחי' ממכ\"ע הוא בחי' כח הפועל בנפעל, שהאור מתלבש בהעולמות ומחי' אותם כו', ובחי' התלבשות זו ז\"ע גילוי ההשפעה, וכמ\"ש בסש\"ב פמ\"ח שההשפעה שהוא בבחי' גילוי בעולמות נק' בשם הלבשה שמתלבש בעולמות כי הם מלבישים ומשיגים ההשפעה שמקבלים כו' ע\"ש, והוא עד\"מ כמו המדות אהוי\"ר שמקבלי' השפעה מחב\"ד שלפי בחי' ההתבוננות כך הוא האהבה או היראה, והרי שכל זה המוליד המדה הוא מלובש בתוך המדה, שמפני מה הוא אוהב ד\"ז או ירא מד\"ז מפני טעם ושכל זה כו', ועד\"ז יובן ענין החיות המתלבש בעולמות ולכן אותו החיות שהוא מקור להתלבשות זו נק' עלמא דאתגליא<sup data-n=\"995\">66</sup> וממכ\"ע<sup data-n=\"996\">67</sup>, וע' בסש\"ב פנ\"ב גבי ומקור זה הוא הנק' עלמא דאתגליא כו'.\n<b>והנה</b> בבחי' האור והחיות המאיר בבחי' ממכ\"ע ומתלבש בעולמות יש כמוכ\"מ<sup data-n=\"997\">68</sup> מדריגות שונות שבנשמות מאיר יותר, ואח\"כ במלאכים וכן ג\"ע והיכלות ורקיעים אשר בכ\"א יש התגלות יותר מבחברו כו', ואמנם בחי' סוכ\"ע הוא בחי' אוא\"ס שבלי גבול ולכן א\"י לבוא ולהתלבש האור בכלי ולבוא לידי גילוי והלבשה, שאין העולמות יכולי' להשיג כלל בחי' אוא\"ס ממש, ואין ההארה וההשפעה באה ממנו בבחי' גילוי אלא בבחי' הסתר והעלם, ולכן נק' סוכ\"ע שמקיף לכל העולמות בשוה דקמי' כחשיכה כאורה שוין בשני כפין כמ\"ש בלק\"ת בד\"ה מצה זו<sup data-n=\"998\">69</sup>, וכולא קמי' כלא ממש חשיבא<sup data-n=\"999\">70</sup>, וא\"א להמשיך שום התגלות בעולמות מבחי' אור הסוכ\"ע, כ\"א ע\"י עשיית המצות יוכל להמשיך התגלות האור מסוכ\"ע ממש, ולכן אומרים בברכת המצות בא\"י אמ\"ה אקב\"ו פי' מלך העולם הוא בחי' ממכ\"ע, והברכה הוא שיהי' המשכה מסוכ\"ע להיות מאיר בממכ\"ע, והיינו ע\"י אק\"ב, קדש לשון מובדל<sup data-n=\"1000\">71</sup> מה שאינו מאיר ומתלבש בעולמות כלל, ומשם נמשכים המצות כי המצות הם\n&lt;63&gt;\nּרצה\"ע ב\"ה שהוא מה שלמעלה מהחכ' והשכל כו' וכענין שתוק כך עלה במח'<sup data-n=\"1001\">72</sup>",[["990","62","<b>אשר אנכי מצוך היום</b>: ואתחנן ו, ו."],["991","63","<b>בכי\"ו יהיו בעיניך כחדשים</b>: ראה לקח טוב ואתחנן שם. מאמרי אדה\"א דברים ח\"א ע' רסו ואילך. וש\"נ. הנחות תקע\"ז ע' שו ואילך וע' שיט."],["992","64","<b>עיני האדם לא תשבענה</b>: משלי כז, כ [ושם: ועיני<sup data-n=\"e113\">ו</sup>]. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381267\" data-slug=\"likkutei-torah\" data-id=\"4001381267\">לקו\"ת שה\"ש לד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381272\" data-slug=\"likkutei-torah\" data-id=\"4001381272\">לה, ד</a>. סהמ\"צ להצ\"צ ע' קפח. פלח הרמון שה\"ש ע' 124 ואילך."],["993","60","<b>ואמנם. . דמלכא</b>: לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640313\" data-slug=\"or-hatorah-hb\" data-id=\"8316640313\">אוה\"ת שה\"ש ח\"א ע' שיג</a> (בשינויים והוספות)."],["994","65","<b>ממכ\"ע וסוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["995","66","<b>עלמא דאתגליא</b>: ראה זהר בראשית יח, א. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 651."],["996","67","<b>עלמא דאתגליא וממכ\"ע</b>: ראה גם סה\"מ תרל\"ח ע' שצא ובהערה 8."],["997","68","<b>כמוכ\"מ</b>: כמה וכמה."],["998","69","<b>כחשיכה כאורה. . בלק\"ת בד\"ה מצה זו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380124\" data-slug=\"likkutei-torah\" data-id=\"4001380124\">לקו\"ת צו יב, א</a>. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1175."],["999","70","<b>וכולא קמי' כלא ממש חשיבא</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1000","71","<b>קדש לשון מובדל</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ\"ו (סו, א</a>). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540089\" data-slug=\"torat-chaim\" data-id=\"2300540089\">תו\"ח וארא ח\"א נא, ד</a> ובהערה 10."],["1001","72","<b>שתוק כך עלה במחשבה</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 62.\n\n<b>ו</b>  אבל ראה גם לעיל מאמר ד\"ה סוכה שחמתה מרובה מצלתה על יד הערה 65."]]],[2000480165,"שהענין שכך הוא הרצון שלמעלה מהשכל, ולא שאין לזה טעם כלל, כ\"א שגבהו דרכיו למעלה מהחכ' והדעת שהם מע\"ס שנק' בשם ממכ\"ע, אבל בחי' המצות הוא סוכ\"ע בלי גבול וע\"כ אינו מושג, וכמו עד\"מ שאין העין הגשמי משיג מהות השכל הרוחני, כך עד\"ז אפי' ח\"ע לית מח' (מח' ויובלא כמ\"ש בזהר<sup data-n=\"1002\">74</sup> ) תפיסא בי' כלל<sup data-n=\"1003\">73</sup> בבחי' אוא\"ס ב\"ה ממש, וזהו כצינה רצון תעטרנו<sup data-n=\"1004\">75</sup> שהרצ\"ע נק' בשם צינה שהוא מקיף, ולכן כתיב היום לעשותם<sup data-n=\"1005\">76</sup> דוקא, ויפה שע\"א<sup data-n=\"1006\">77</sup> בתשומע\"ט בעוה\"ז מכל כו' כי בג\"ע שהוא קיבול שכר נהנין מזיו<sup data-n=\"1007\">78</sup> כו' זהו רק מבחי' ממכ\"ע, וכמארז\"ל ביו\"ד נבה\"ע הבא<sup data-n=\"1008\">79</sup> וע' באגה\"ק סי' י\"ז ד\"ה נודע דבאתעדל\"ת, ולכן שם לא מהני התשובה<sup data-n=\"1009\">80</sup>, כ\"א צ\"ל בגיהנם תחלה, כי צריך לילך מדרגא לדרגא וא\"א לדלג מדריגות כו', ואפי' מי שהוא בג\"ע כשעולים למעלה ומדריגה גבוה יותר צריך לטבול בנהר דינור וכמ\"ש במ\"א בד\"ה מראיהם ומעשיהם<sup data-n=\"1010\">81</sup>, משא\"כ בעוה\"ז היום דוקא לעשותם מועיל התשובה, ולכן המקדש כו' ע\"מ שהוא צ\"ג כו' מקודשת<sup data-n=\"1011\">82</sup> שמא הרהר תשובה כו', ופ\"י מלאים מצות כרימון<sup data-n=\"1012\">83</sup> שבעוה\"ז דוקא יוכל לבוא למדריגה גבוה כזו כי ע\"י המצות ממשיך התגלות מסוכ\"ע המקיף את כולם בשוה כו', ועפי\"ז יובן ענין בכי\"ו יהי' בעיניך כחדשים היינו התגלות האור מסוכ\"ע שהוא אור חדש ממש, דהיינו מה שלא האיר עדיין בסדר השתלשלות עילה ועלול<sup data-n=\"1013\">84</sup>, ומשם היינו מבחי' שלמעלה מהשתלשלות נמשך ומאיר או\"ח בבחי' ממכ\"ע, וע\"י התבוננות זו עצמה יהי' עשיית המצות בעיניך כחדשים ממש כי היום בעוה\"ז דוקא אנו יכולים להמשיך בחי' או\"ח זה כו', וזהו אין כל חדש תחת השמש<sup data-n=\"1014\">85</sup>, תחת השמש הוא בחי' ממכ\"ע, ע' זח\"ג ר\"פ חקת<sup data-n=\"1015\">86</sup> בפי' תחת השמש, משא\"כ עמלא דאורייתא לעילא מן שמשא<sup data-n=\"1016\">87</sup> שממשיך מבחי' סוכ\"ע ממש כו'.",[["1002","74","<b>מח' ויובלא כמ\"ש בזהר</b>: ראה שם ח\"ש קכג, א. ראה גם מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' כו. סה\"מ תרכ\"ז ע' תלא. תרל\"ב ח\"ב ס\"ע שסב. תרל\"ג ח\"א ע' פ וע' פה."],["1003","73","<b>לית מח'. . תפיסא בי' כלל</b>: ת\"ז בהקדמה יז, א."],["1004","75","<b>כצינה רצון תעטרנו</b>: תהלים ה, יג. ראה גם ש\"א נז, א ובהערה 3."],["1005","76","<b>היום לעשותם</b>: ואתחנן ז, יא."],["1006","77","<b>ויפה שע\"א</b>: אבות פ\"ד, מי\"ז. ראה גם המשך וככה תרל\"ז רפ\"ט."],["1007","78","<b>נהנין מזיו</b>: ראה ברכות יז, א."],["1008","79","<b>ביו\"ד נבה\"ע הבא</b>: ראה מנחות כט, ב."],["1009","80","<b>שם לא מהני התשובה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380621\" data-slug=\"likkutei-torah\" data-id=\"4001380621\">לקו\"ת פינחס עה, סע\"ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380627\" data-slug=\"likkutei-torah\" data-id=\"4001380627\">עו, סע\"ד</a>. סידור שחרית לב, ב. לה סע\"ד ואילך. סה\"מ תרל\"ה ח\"ב ע' שעב ואילך. אעת\"ר ע' קמד ואילך. פלח הרמון בחוקותי ע' תסא ואילך ובהערה 34."],["1010","81","<b>בג\"ע כשעולים. . לטבול בנהר דינור. . בד\"ה מראיהם ומעשיהם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370310\" data-slug=\"torah-or\" data-id=\"3901370310\">תו\"א יתרו סט, ג</a> ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670027\" data-slug=\"torat-chaim\" data-id=\"2300670027\">תו\"ח בראשית לג, ד</a> ובהערה 10. שמות ח\"א ה, ד ובהערה 263. סה\"מ תרכ\"ט ע' צח. וש\"נ."],["1011","82","<b>המקדש. . מקודשת</b>: ראה קדושין מט, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380715\" data-slug=\"likkutei-torah\" data-id=\"4001380715\">לקו\"ת דברים א, ב</a>. סה\"מ תרל\"ח ע' תקי. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091343\" data-slug=\"likkutei-sichot\" data-id=\"1300091343\">לקו\"ש אלול כרך ט ע' 316</a>. אחרי כרך יז ע' 186. אגה\"ת כרך יט ע' 394. תצא כרך לד ע' 290."],["1012","83","<b>ופ\"י מלאים מצות כרימון</b>: ערובין יט, א."],["1013","84","<b>עילה ועלול</b>: ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a> (הנזכר בספרים). שה\"ש א, ב (כמ\"ש בספרים)."],["1014","85","<b>אין כל חדש תחת השמש</b>: קהלת א, ט [ושם: ואין]."],["1015","86","<b>ע' זח\"ג ר\"פ חקת</b>: קפא, סע\"א ואילך."],["1016","87","<b>עמלא דאורייתא לעילא מן שמשא</b>: זהר ויחי רכג, ב."]]],[2000480166,"<b>והנה</b> נת' במ\"א שכמו בבינה<sup data-n=\"1017\">88</sup> יש חמשי' שע\"ב<sup data-n=\"1018\">89</sup> ועכ\"ז לא נתגלו רק מ\"ט שערי', כן בחכ' הגם שיש ל\"ב נת\"ח כמ\"ש בס\"י<sup data-n=\"1019\">90</sup> בל\"ב נתי' פליאות חכ' כו', עכ\"ז גם ליעקב לא נתגלה כ\"א ל\"א נתי'<sup data-n=\"1020\">91</sup>, וזהו מ\"ש נתי' לא ידעו עיט<sup data-n=\"1021\">92</sup> ולא שזפתו עין אי', וכמ\"ש בזהר ע\"פ זה, ולכן ביעקב נא' ויקרא אל אלוקי ישראל<sup data-n=\"1022\">93</sup>, ל\"א נתיבות, ועי' בד\"ה ויכל אלקים, רכ\"ב<sup data-n=\"1023\">94</sup> ובד\"ה את שבתותי תשמרו שלא נדפס ובהגהות לשם<sup data-n=\"1024\">95</sup>, ועל בחי' נתי' זה הוא משנ\"ת במ\"א שפנימי' אבא<sup data-n=\"1025\">96</sup> חשיב כמו פנימי' ע\"י<sup data-n=\"1026\">97</sup>, ובשעת מ\"ת שארז\"ל במ\"ת נדמה להם כזקן<sup data-n=\"1027\">98</sup> לכאו' הלא ארז\"ל ומי איכא זיקנה קמי' קוב\"ה<sup data-n=\"1028\">99</sup>, אלא שנדמה להם כזקן ז\"ע גילוי בחי' עת\"י, ולכן זכו אז כ\"י לבחי' לאסתכלא ביקרא דמלכא כמשנ\"ת לעיל שזהו בחי' ראי' שנת' לעיל<sup data-n=\"1029\">100</sup>.",[["1017","88","<b>שכמו בבינה. . כן בחכמה</b>: ראה גם לקמן מאמר ד\"ה והוא כחתן על יד הערה 29. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 26. המשך והחרים תרל\"א ע' עה. סה\"מ תרל\"ב ח\"א ע' לח. תרל\"ד ע' כח. מים רבים תרל\"ו פקנ\"ד."],["1018","89","<b>חמשי' שע\"ב</b>: ר\"ה כא, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם פ\"ב ובהערה 17."],["1019","90","<b>ל\"ב נת\"ח כמ\"ש בס\"י</b>: פ\"א, מ\"א. ראה גם הנסמן במאמרי אדה\"א בראשית ע' ג."],["1020","91","<b>ליעקב. . ל\"א נתי'</b>: ראה גם לקמן מאמר ד\"ה והוא כחתן על יד הערה 31. ובהנחה שם. המשך והחרים ומים רבים שם. סה\"מ תרל\"ב ח\"א ע' לח. ע' קנט. תרל\"ח ע' קצד ואילך. וש\"נ. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' סג."],["1021","92","<b>נתי' לא ידעו עיט</b>: איוב כח, ז<sup data-n=\"e114\">ז</sup>. ראה ת\"ז ת\"ל עג, ב. לקמן מאמר ד\"ה והוא כחתן על יד הערה 34. ובהנחה שם על יד הערה 28. סה\"מ תרל\"ד ע' כח. וש\"נ. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' סב."],["1022","93","<b>ויקרא אל אלוקי ישראל</b>: וישלח לג, כ [בדילוג]."],["1023","94","<b>בד\"ה ויכל אלקים רכ\"ב</b>: לע\"ע אינו תח\"י<sup data-n=\"e115\">ח</sup>. ויש להוסיף מאמר זה לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר הצ\"צ."],["1024","95","<b>ובד\"ה את שבתותי תשמרו. . ובהגהות לשם</b>: כ\"ה גם במאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' סא. לע\"ע אינו תח\"י<sup data-n=\"e116\">ט</sup>. ראה גם אוה\"ת בהר כרך ד ע' א'קמד<sup data-n=\"e117\">י</sup>."],["1025","96","<b>נתיב זה. . שפנימי' אבא</b>: ראה גם לקמן מאמר ד\"ה והוא כחתן על יד הערה 36. ובהנחה שם על יד הערה 35. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380456\" data-slug=\"likkutei-torah\" data-id=\"4001380456\">לקו\"ת בהעלותך לו, ג</a>. אוה\"ת מיכה ע' תצב. לך כרך ד ע' 1414. בהעלותך ס\"ע תיט. פלח הרמון בהר ע' שפז."],["1026","97","<b>שפנימי' אבא. . פנימי' ע\"י</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541072\" data-slug=\"torat-chaim\" data-id=\"2300541072\">תו\"ח שמות ח\"א כג, א</a> הערה 951."],["1027","98","<b>במ\"ת נדמה להם כזקן</b>: ראה מכילתא בשלח טו, ג. יתרו כ, ב."],["1028","99","<b>ומי איכא זיקנה קמי' קוב\"ה</b>: ראה יבמות טז, ב. מאמרי אדה\"א קונטרסים ע' צב ד\"ה והנה. שעה\"י קפו, ג. שע\"ת כט, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680260\" data-slug=\"torat-chaim\" data-id=\"2300680260\">תו\"ח תולדות קנג, א</a> הערה 9. לקמן מאמר ד\"ה רני ושמחי על יד הערה 20. ובהנחת כ\"ק אדמו\"ר מהורש\"ב שם על יד הערה 25."],["1029","100","<b>לעיל</b>: עד כאן נמצא בגוף כתי\"ק.\n\n<b>ז</b>  במאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' סא: איוב ך\"ח וא\"ו. ואולי צ\"ל כבפנים.\n\n<b>ח</b>  ראה גם לקמן מאמר ד\"ה והוא כחתן על יד הערה 28 [ושם: ובד\"ה ויכל אלקים ביום השביעי].\n\n<b>ט</b>  ראה גם לקמן ד\"ה והוא כחתן שם על יד הערה 27 [ושם: ביאור שבתותי]. סה\"מ תרל\"ב ח\"ב ע' תקנב [ושם: בד\"ה את שבתותי דתפילין].\n\n<b>י</b>  ובמהדורת תשנ\"ג <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940200\" data-slug=\"or-hatorah-hb\" data-id=\"8159940200\">אוה\"ת בהר כרך ב ע' תרט\"ז</a>."]]],[2000480167,"<h3>להבין שרש ענין מקיפים דבינה</h3>\n<b></b>ה\"פ [קירוב וריחוק מקום חלון נקב פרסא]\nלהבין שרש ענין מקיפים דבינה<sup data-n=\"1030\">1</sup> שנמשכים ע\"י הסוכה<sup data-n=\"1031\">2</sup>, צריך להבין תחלה ענין המבואר בע\"ח שמ\"א פ\"א<sup data-n=\"1032\">3</sup> שאוא\"ס מאיר בכתר ובחכ' בקירוב מקום, ובבינה בריחוק מקום, ובז\"א ע\"י חלון ובמל' ע\"י נקב, שלכן נק' המל'<sup data-n=\"1033\">4</sup> נקיבה<sup data-n=\"1034\">5</sup> שהוא בחי' נקב ה', ומאצי' לבי\"ע ע\"י פרסא<sup data-n=\"1035\">6</sup>, וצ\"ל הלא גם באצי' יש כמה פרסות<sup data-n=\"1036\">7</sup>, כנודע מענין רקיע שע\"ג חיון עילאין<sup data-n=\"1037\">8</sup> הם בחי' המדות עליונות<sup data-n=\"1038\">9</sup> שזהו מ\"ש ועל ראשי החי' רקיע<sup data-n=\"1039\">10</sup> כעין הקרח הנורא נטוי על ראשיהם שז\"ע הפרסא שבין בינה לז\"א<sup data-n=\"1040\">11</sup>, וכמ\"ש בזהר<sup data-n=\"1041\">12</sup>, וע' מזה בסידור<sup data-n=\"1042\">13</sup> ע\"פ הנותן שלג כצמר, שזהו מ\"ש מבטן מי יצא הקרח<sup data-n=\"1043\">14</sup> שהוא בחי' רקיע כעין הקרח, והיינו כי באצי' עצמו יש אבי\"ע<sup data-n=\"1044\">15</sup>, והמדות הם בחי' יצי' שבאצי', ובינה נק' בריאה שבאצי' ולכן יש בחי' פרסא המפסקת בין בריאה",[["1030","1","<b>להבין שרש ענין מקיפים דבינה</b>: אודות מאמר זה<sup data-n=\"e118\">א</sup> נרשם בספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e119\">ב</sup>: קירוב וריחוק מקום חלון נקב פרסא — ה\"פ.\nמאמר זה מיוסד על מאמרי אדה\"ז ענינים<sup data-n=\"e120\">ג</sup> ע' לג ואילך<sup data-n=\"e121\">ד</sup>. אמרי בינה שער הק\"ש לז, סע\"ד ואילך. אוה\"ת ענינים ע' קעט ואילך. סידור ע' שנז ואילך. ראה סה\"מ תרכ\"ז ע' שמז ואילך. וש\"נ. מאמר ד\"ה קרוב ה' ב' דחה\"ש תשח\"י. ד\"ה ובחמשה עשר יום (ב' דסוכות) וד\"ה לה\"ע שמח\"ת תש\"ל.\nדרוש זה הובא לקמן במאמר ד\"ה ולהבין וכו' מזבח הפנימי על יד הערה 19.\nמאמר זה נדפס גם בסה\"מ תרכ\"ט ע' שסט ואילך<sup data-n=\"e122\">ה</sup>."],["1031","2","<b>מקיפים דבינה. . הסוכה</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 85."],["1032","3","<b>בע\"ח שמ\"א, פ\"א</b>: בדפוס שקלאב תק\"ס. ובדפוסים אחרים: שער דרושי אבי\"ע שמ\"ב, פי\"ג. ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 118. הנסמן בסה\"מ תר\"ן ע' רפב. אוה\"ת ענינים וסידור שבהערה 1. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' מד. וש\"נ."],["1033","4","<b>המל' נקיבה. . נקב ה'</b>: ראה ע\"ח שער הכללים פ\"י. שער תיקון הנוקבא של\"ד, פ\"ב כלל ט. (שער הירח של\"ב, פ\"א). שער מ\"ן ומ\"ד של\"ט, דרוש יג."],["1034","5","<b>נקיבה</b>: בסה\"מ תרכ\"ז ותרכ\"ט: נקבה."],["1035","6","<b>ומאצי' לבי\"ע ע\"י פרסא</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא. לקמן פ\"ג ופ\"ד."],["1036","7","<b>באצי' יש כמה פרסות</b>: ראה בסמוך בפנים."],["1037","8","<b>רקיע שע\"ג חיון עילאין</b>: נסמן בהערה הבאה."],["1038","9","<b>חיון עילאין. . המדות עליונות</b>: ראה זהר ויקהל ריא, א. ריג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כב, ד</a>. סידור שחרית סד, א."],["1039","10","<b>ועל ראשי החי' רקיע</b>: יחזקאל א, כב [ושם: ודמות על ראשי החי' — ראה גם לקמן מאמר ד\"ה ושאבתם מים על יד הערה 38. ו(בחלק ההנחות) בהנחה שם על יד הערה 45. סה\"מ תרל\"ח ע' קסג. וש\"נ]."],["1040","11","<b>הפרסא שבין בינה לז\"א</b>: ראה לעיל הערה 9. אוה\"ת על ענינים כאן ע' קפ."],["1041","12","<b>וכמ\"ש בזהר</b>: ראה בהערה שלפנ\"ז."],["1042","13","<b>בסידור</b>: שחרית סד, א."],["1043","14","<b>מבטן מי יצא הקרח</b>: איוב לח, כט."],["1044","15","<b>באצי' עצמו יש אבי\"ע</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"א ובהערה 1002.\n\n<b>א</b>  מאמר זה לא נדפס בהמשך יונתי הנדפס.\n\n<b>ב</b>  ברשימת מאמרי שנה זו (במהדורת תש\"ז כאן ע' 53) מציין כ\"ק אדמו\"ר רק מספר הפרקים, ובהערה 4 שם מציין: הוא הדרוש דשנת תר\"ל. ושם — בשנת תר\"ל — ע' 31 כותב: קירוב מקום — ה\"פ, ובהערה 1 שם מציין: דרוש קרוב ה' דשנת תרכ\"ז. ושם ע' 27 — בדרושי תרכ\"ז — נרשם הלשון שהועתק כאן בפנים ההערה.\n\n<b>ג</b>  נדפס בחלקו גם במאמרי אדה\"ז תקס\"ז ע' צה ואילך.\n\n<b>ד</b>  ראה גם שם ע' מ ואילך.\n\n<b>ה</b>  ושם (ס\"ע שעד ואילך) נרשם קטע נוסף."]]],[2000480168,"ליצי' שבאצי' גופא, ובזח\"א פ' נח<sup data-n=\"1045\">16</sup> איתא שגם בין כתר לחכ' יש ג\"כ בחי' פרסא כו', ונמצא כי יש באצי' עצמו כמה פרסות, וכנודע מענין י\"ג פרוכת היו במקדש<sup data-n=\"1046\">17</sup> כמ\"ש מזה בת\"א בד\"ה והבדילה הפרוכת<sup data-n=\"1047\">18</sup>, אך הענין הוא דהפרסות שבאצי' הם ע\"ד משארז\"ל במד\"ר בראשית פך\"א בענין איש לבוש הבדים<sup data-n=\"1048\">20</sup> כהדין קמצא<sup data-n=\"1049\">19</sup> דלבושי' מיני' ובי', ולהבין כ\"ז צ\"ל מה שייך למעלה ענין קירוב מקום וריחוק מקום הרי כתיב הנה מקום אתי<sup data-n=\"1050\">21</sup>, והוא מקומו של עולם כו'<sup data-n=\"1051\">22</sup>, אך הענין הוא",[["1045","16","<b>ובזח\"א פ' נח</b>: סה, א. ראה אוה\"ת על ענינים שם. בראשית כרך ג ע' תפ. ואתחנן ע' ריח ואילך."],["1046","17","<b>י\"ג פרוכת היו במקדש</b>: ראה יומא נד, א. כתובות קו, א."],["1047","18","<b>בת\"א בד\"ה והבדילה הפרוכת</b>: לך יב, ג ואילך."],["1048","20","<b>איש לבוש הבדים</b>: ראה דניאל י, ה."],["1049","19","<b>במד\"ר בראשית פך\"א. . כהדין קמצא</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה אחת הא' הערה 107."],["1050","21","<b>הנה מקום אתי</b>: תשא לג, כא. ראה גם לעיל מאמר ד\"ה סוכה שחמתה מרובה מצלתה."],["1051","22","<b>והוא מקומו של עולם</b>: ב\"ר פס\"ח, ט. ראה מאמרי אדה\"א דברים ח\"א ע' רצא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670491\" data-slug=\"torat-chaim\" data-id=\"2300670491\">תו\"ח בראשית מג, א</a> הערה 2. סה\"מ תרכ\"ט ע' קסט. וש\"נ."]]],[2000480169,"דהנה פי' מקום הוא רק במעלה ומדרגה<sup data-n=\"1052\">23</sup> בחי' מעלה ומטה, והנה פי' מעלה ומטה אינו פי' במקום גשמי רק הפי' מעלה ומטה הוא במעלה ומדרגה גבוה, דהיינו מה שיש לו יתרון מעלה על זה נק' מעלה כמו למשל שכל ומדות, השכל נק' מעלה לגבי מדות לפי שיש לו יתרון מעלה על המדות, וכן אדם שהוא חכם גדול ויש לו יתרון בשכלו על זולתו נק' אדם גדול, והיינו לפי שיש לו יתרון ע\"ג חבירו נק' מעלה כו', ועפ\"ז יובן ג\"כ למעלה פי' קירוב מקום או ריחוק מקום, דהיינו מה שמאיר אוא\"ס יותר נק' בחי' קירוב מקום כו', ולהבין פי' קירוב וריחוק כו' יובן זה ממה שאנו רואים למטה כשצריך להשפיל את השכל בדבור, הנה מתחלה מתלבש השכל במחשבה ואח\"כ ממח' למדות שבכדי שיפעול דבריו לזולתו צ\"ל שיהי' יוצאי' מן הלב כנודע שדברים שיוצאי' מן הלב<sup data-n=\"1053\">24</sup> נכנסי' ללב שומע, וממדות לדבור הנה השכל מאיר בדבור בריחוק מקום לפי שצריך השכל להשתלשל ממדרגה למדרגה עד שיתלבש בבחי' דבור כו', אבל התלבשות השכל במח' הוא בבחי' קירוב שא\"א להשיג השכל בלתי אותיות המח' ואינו צריך להשתלשל ולירד ממדריגה למדריגה כ\"א המח' הוא לבוש הראשון להשכל, וזהו בחי' קירוב, ובזה יובן ג\"כ למעלה מה שאוא\"ס מאיר בכתר וחכ' בבחי' קירוב, שהם ראשית המדרגות אשר בם יתגלה אוא\"ס.\nב) <b>אך</b> עדיין צ\"ל איך שייך לומר שאוא\"ס מאיר בכו\"ח בבחי' קירוב שהרי ע\"ס הוא רק הארה בעלמא ושרש התהוות הע\"ס הוא מבחי' קו וחוט, אבל עצמות אוא\"ס הוא למעלה מבחי' ע\"ס וכמאמר לאו מכל אינון מדות<sup data-n=\"1054\">25</sup> איהו כלל, וא\"כ אינו מובן איך יתכן לומר שאוא\"ס מאיר בהם בבחי' קירוב כו', אך הענין הוא דהנה נודע שכתר הוא ממוצע<sup data-n=\"1055\">26</sup> בין המאציל לנאצלים, ולהבין איך הוא ממוצע, והענין הוא דהנה כתר הוא בחי' רצון<sup data-n=\"1056\">27</sup>, והנה אנו רואים למטה שהרצון הוא בחי' ממוצע בין עצמות הנפש לכחות הנפש<sup data-n=\"1057\">28</sup>, שהרי אנו רואים שהכל תלוי ברצון שהרצון מושל ושולט על כל האברים, כמו למשל שאם אדם רוצה ומתמיד בטבעו ללמוד<sup data-n=\"1058\">29</sup> אזי יוכל להשיג אע\"פ שאינו בר שכל גדול, אבל אם אינו רוצה ללמוד אזי אע\"פ שהוא בר שכל גדול לא ישיג כלום וכמו שארז\"ל יגעתי ומצאתי תאמין<sup data-n=\"1059\">30</sup> לא יגעתי ומצאתי אל תאמין כו', וע\"כ הזהיר הכתוב מאד על אהבה כו', שעיקר אהבה הוא מלשון אבה<sup data-n=\"1060\">31</sup> והיינו בחי' רצון, וכן ארז\"ל עשה רצונו כרצונך<sup data-n=\"1061\">32</sup> כו', ובזה יובן ג\"כ למעלה שכתר הוא ממוצע בין עצמות המאציל לנאצלים כו', דהנה אוא\"ס הוא למעלה מגדר עולמות, וכדי שיתהוה עולמות כו' הוא רק ע\"י מה שעלה ברצונו כו' וכמ\"ש בזהר כד סלק ברעותי'<sup data-n=\"1062\">33</sup> למברי עלמא, רק באמת אין המשל דומה לנמשל כו' לפי שלמטה לא יתהוה כלום מהרצון כו' רק שהרצון פועל באברים ומושל ושליט עליהם, אבל למעלה כיון שעלה ברצונו שיתהוה עולמות תומ\"י נתהוה<sup data-n=\"1063\">34</sup>, וכמ\"ש כל אשר חפץ ה' עשה<sup data-n=\"1064\">35</sup> כו', וזהו מ\"ש בע\"ח שאוא\"ס מאיר בכתר בבחי' קירוב כו', והנה בבחי' חכ' מאיר ג\"כ בבחי' קירוב לפי שחכמה הוא כח מה<sup data-n=\"1065\">36</sup> בחי' ביטול ואין אוא\"ס שורה אלא בבחי' ביטול<sup data-n=\"1066\">37</sup> לפי שבחי' אוא\"ס הוא בחי' איך דכולא קמי' כלא חשיב<sup data-n=\"1067\">38</sup>, אשר הכלי לגילוי זה הוא בחי' החכ' שנק' אחד האמת כמ\"ש בסש\"ב פל\"ה בהג\"ה, והיינו שבחכ' מושג איך דכולא קמי' כלא חשיב, אבל בבחי' בינה אינו מאיר אלא בריחוק לפי שבינה היא בחי' השגה, וכיון שהיא בחי' השגה, ובאוא\"ס אמרו דלית מח' תפיסא בי' כלל<sup data-n=\"1068\">39</sup> ע\"כ שאינו מאיר שם בקירוב וכמו שאנו רואים באותיות החותם שע\"ג אבן טוב שמחמת בהירות האבן טוב אינם יכולים",[["1052","23","<b>מקום. . במעלה ומדרגה</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו. מו\"נ ח\"א, פ\"ח. ספר החקירה ע' 148 ואילך. אוה\"ת על ענינים ע' קפ. סידור ע' שנח. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה משה קבל ובהערה 8. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' מד."],["1053","24","<b>שדברים שיוצאי' מן הלב</b>: ספר הישר לר\"ת שי\"ג. הובא בשל\"ה שער האותיות אות כ (סט, א)."],["1054","25","<b>לאו מכל אינון מדות</b>: ת\"ז בהקדמה יז, ב."],["1055","26","<b>שכתר הוא ממוצע</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תס. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540828\" data-slug=\"torat-chaim\" data-id=\"2300540828\">תו\"ח שמות ח\"א יא, ג</a>. וש\"נ."],["1056","27","<b>כתר הוא בחי' רצון</b>: ראה פרדס שער עצמות וכלים שער ד, פ\"ח. שער הצחצחות שי\"א, פ\"ה. פ\"ו. אגה\"ק סכ\"ט. מאמרי אדה\"א הנחות תקע\"ז ע' עב. וש\"נ. אוה\"ת על ענינים כאן ס\"ע קפא ואילך."],["1057","28","<b>רצון. . עצמות הנפש לכחות הנפש</b>: ראה ביאוה\"ז שמות לו, ד ואילך."],["1058","29","<b>שאם אדם רוצה. . ללמוד</b>: ראה ע\"ז יט, א."],["1059","30","<b>יגעתי ומצאתי תאמין</b>: מגילה ו, ב."],["1060","31","<b>אהבה הוא מלשון אבה</b>: ראה שרש ישע שרש אבה הובא בס' החקירה להצ\"צ מערכת אהב (צב, רע\"א — ובמהדורת תשס\"ג ע' צד). לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 8."],["1061","32","<b>עשה רצונו כרצונך</b>: אבות פ\"ב, מ\"ד."],["1062","33","<b>כד סלק<sup data-n=\"e123\">ו</sup> ברעותי'</b>: ראה זהר לך פו, סע\"ב."],["1063","34","<b>כיון שעלה. . תומ\"י נתהוה</b>: ראה פרדס שער הצחצחות שי\"א, פ\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת שה\"ש יז, ג</a> ואילך (הועתק לעיל ח\"א (בחלק המאמרים) המשך מצה זו פי\"ב)."],["1064","35","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["1065","36","<b>שחכמה הוא כח מה</b>: זהר רע\"מ צו כח, א. לד, א. ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 840."],["1066","37","<b>ואין אוא\"ס שורה אלא בבחי' ביטול</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ\"ו</a>."],["1067","38","<b>דכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1068","39","<b>דלית מח' תפיסא בי' כלל</b>: ת\"ז בהקדמה יז, א.\n\n<b>ו</b>  בסה\"מ תרכ\"ט כאן ע' שעא: סליק."]]],[2000480170,"לקרוא את האותיות, אלא כשחותמים בהחותם ע\"ג שעוה כו' שהאותיות מתרחקים מהאבן טוב אז הם יכולים לקרות אותם, וכך לפי שבחכ' מאיר אוא\"ס בקירוב לכן שם הוא ביטול ההשגה כו' וכמ\"ש מה פשפשת<sup data-n=\"1069\">40</sup> כו', רק בבינה שאינו מאיר בקירוב כ\"א בריחוק אז יוכל להיות שם השגה באוא\"ס כנ\"ל ולכן החכ' נק' ראי' ובינה נק' בחי' שמיעה<sup data-n=\"1070\">41</sup>, והחילוק שבין ראי' לשמיעה כי ראי' הוא בבחי' קירוב ושמיעה הוא מרחוק, וע\"כ אמרו אינו דומה שמיעה לראי'<sup data-n=\"1071\">42</sup> כי אע\"פ ששומע את הדבר ומאמין שהוא כן אעפ\"כ אינו דומה לראי' לפי שהוא מקרוב כו' ולכך בינה מקננא בכורסייא<sup data-n=\"1072\">43</sup>, לפי שבבינה מאיר בבחי' ריחוק ע\"כ הוא יכול להיות מקור לעולמות בי\"ע שהוא בריאה יש מאין בחי' נפרד כו', אבל חכ' שמאיר שם אוא\"ס בבחי' קירוב ע\"כ מקננא באצי'<sup data-n=\"1073\">44</sup> כי לשון אצילות הוא לשון ויאצל מן הרוח<sup data-n=\"1074\">46</sup>, ומלשון אצל וסמוך<sup data-n=\"1075\">45</sup> כו' שמאיר שם בבחי' קירוב וע\"כ כתר וחכ' נרמזים באות א' באות יו\"ד כי קוצו של יו\"ד הוא בחי' כתר<sup data-n=\"1076\">47</sup>, ויו\"ד עצמו הוא בחי' חכ'<sup data-n=\"1077\">48</sup> לפי שבכתר וחכ' מאיר אוא\"ס בבחי' קירוב כו', אבל בינה נרמז באות אחר באות ה'<sup data-n=\"1078\">49</sup> כנ\"ל<sup data-n=\"1079\">50</sup>, וגם אות ה' הוא בבחי' התפשטות אורך ורוחב בחי' השגה, אבל יו\"ד היא נקודה אחת בחי' ביטול.\nג) <b>ומעתה</b> י\"ל מ\"ש שמבינה לז\"א אינו מאיר רק דרך חלון, הנה אנו רואים למטה באור השמש כשמאיר על הארץ הוא מאיר בהתפשטות והתרחבות, אבל כשמאיר בבית אינו מאיר רק דרך חלון שנתצמצם האור כו' ואינו מאיר בכל חלקי צדדי הבית רק דרך חלון כו', ועוד יובן זה יותר ממה שאנו רואים כשאדם לומד איזה הלכה כמו אלו כשרות ואלו טריפות<sup data-n=\"1080\">51</sup> כו' יש בזה ההלכה התפשטות והתרחבות השגה מפני שבזה האופן הוא כשר ואם לאו היא טריפה, אבל אח\"כ כשצריך לפסוק את הדין אומר כשר כו' בלי שום טעם כלל ונתצמצם מכמו שהי' בשכלו שהי' בהתפשטות, וכך יובן למעלה מה שמבינה לז\"א אינו מאיר רק דרך",[["1069","40","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["1070","41","<b>החכ' נק' ראי' ובינה. . שמיעה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370070\" data-slug=\"torah-or\" data-id=\"3901370070\">תו\"א וירא טו, ד</a>. מקץ מ, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' רפז. תקס\"ט ע' פט. שער האמונה מג, ב. תו\"ח שמות ח\"א כז, ג הערות 15-16."],["1071","42","<b>אינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לק\"ט שלח יג, יח. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה פ\"א. וש\"נ."],["1072","43","<b>בינה מקננא בכורסייא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["1073","44","<b>חכ'. . מקננא באצי'</b>: ראה ת\"ז ת\"ו שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' רלה."],["1074","46","<b>ויאצל מן הרוח</b>: בהעלותך יא, כה."],["1075","45","<b>אצילות. . ויאצל. . אצל וסמוך</b>: ראה פרדס שער אבי\"ע שט\"ז, רפ\"א. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פנ\"ה. וש\"נ."],["1076","47","<b>קוצו של יו\"ד.. כתר</b>: ראה זהר ויקרא י, ב. פרדס שער שם בן ד' שי\"ט, פ\"ב. הנסמן במאמרי אדה\"א קונטרסים ע' תכז."],["1077","48","<b>ויו\"ד. . חכ'</b>: ראה זהר בראשית לא, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשסד ובהנסמן לשם."],["1078","49","<b>בינה. . ה'</b>: ראה פרדס שער האותיות שער כז, פ\"ח. הנסמן במאמרי אדה\"א בראשית ע' רלג."],["1079","50","<b>כנ\"ל</b>: כ\"ה גם בסה\"מ תרכ\"ז ותרכ\"ט כאן."],["1080","51","<b>אלו כשרות ואלו טריפות</b>: וכ\"ה בהנסמן בהערה שלפנ\"ז. מאמר ד\"ה ובחמשה עשר יום (שבהערה 1). ראה לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 76."]]],[2000480171,"חלון דהיינו שנתצמצם האור מכמו שהי' בבינה ולכך נק' זעיר אנפין<sup data-n=\"1081\">52</sup>, דהנה יש אתוון רברבין ואתוון זעירין<sup data-n=\"1082\">53</sup>, אתוון רברבין הוא בבינה<sup data-n=\"1083\">54</sup> וזהו ע' רבתי שכל מדה כלולה שם מעשר<sup data-n=\"1084\">55</sup> כו' וע\"כ נק' ע' רבתי שמאיר שם בבחי' התרחבות, אבל בבחי' ז\"א אינו מאיר רק בבחי' צמצום כו' וע\"כ נק' זעיר אנפין. ועתה צ\"ל מה שמז\"א למל' אינו מאיר רק דרך נקב דהיינו שצריך להתצמצם עוד יותר מז\"א למל', וכמו שאנו רואים למטה כשהוא בהתפעלות המדות אינו יכול לדבר<sup data-n=\"1085\">56</sup> ע\"פ שכלו אלא יכול לדבר דברי שטות כו', אא\"כ כשנתצמצמו המדות ואינם מאירים בתוקף אזי יכול לדבר בכיון, וזהו שמז\"א למל' אינו מאיר רק דרך נקב כנ\"ל. והנה ממל' לבי\"ע אינו מאיר רק דרך פרסא המפסיק בין אצי' לבריאה, דהנה החילוק שבין פרסא לנקב שבנקב אע\"פ שמאיר דרך צמצום, אעפ\"כ מאיר עצמות האור כו', אבל דרך פרסא אינו מאיר רק אור של תולדה<sup data-n=\"1086\">57</sup> ולא עצמות האור כמו שאנו רואים שאם תולין מסך מפסיק אזי אינו מאיר האור כמו שהוא רק אור של תולדה, וכך יובן למעלה שממל' לבי\"ע אינו מאיר רק דרך פרסא שכדי שיהיו עולמות בי\"ע שהם בחי' בריאה יש מאין יכולים לקבל את האור כו' ולא יבטלו במציאות צריך להיות מאיר ע\"י פרסא שהוא אור של תולדה. ולהבין יותר מהו בחי' פרסא למעלה יובן מענין המשלים שאנו רואים כשהשכל הוא עמוק מאד לערך המקבל מלבישין אותו במשל, שהמשל הוא ענין זר מהנמשל כמו משלי שלמה<sup data-n=\"1087\">58</sup> שהלביש חכמתו במשלים, וכמ\"ש וידבר שלשת אלפים משל<sup data-n=\"1088\">59</sup>, שהמשלים אלו מורים על חכמות עמוקות, ואעפ\"כ המשל הוא דבר זר כו', וכמו\"כ יובן למעלה שבין אצי' לבריאה אינו מאיר רק דרך פרסא שאינו מאיר האור כמו שהוא רק כמו ע\"י משל כנ\"ל.\nד) <b>ומעתה</b> י\"ל שהרי גם באצי' יש ג\"כ פרסא וכמ\"ש לעיל, והענין הוא שהחילוק הוא שבאצי' הפרסא הוא כמארז\"ל במד\"ר בראשית פך\"א על איש לבוש הבדים כהדין קמצא דלבושי' מיני' ובי', ולהבין זה מהו מיני' ובי', יובן זה ממה שאנו רואים באדם למטה שיש חצר הכבד<sup data-n=\"1089\">60</sup> המפסיק בין אברי הנשימה לאברי המזון, וכמ\"ש בזהר ע\"פ יהי רקיע ויהי מבדיל<sup data-n=\"1090\">62</sup> בין מים למים שזהו כדוגמת",[["1081","52","<b>ולכך נק' זעיר אנפין</b>: ראה לקו\"ת ואתחנן יב, סע\"ד. אוה\"ת על ענינים כאן ע' קפז."],["1082","53","<b>אתוון רברבין ואתוון זעירין</b>: ראה זהר בהקדמה ג, ב."],["1083","54","<b>אתוון רברבין הוא בבינה</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פכ\"א."],["1084","55","<b>ע' רבתי שכל מדה כלולה שם מעשר</b>: ראה זהר פינחס רלו, ב. לקו\"ת שם. סה\"מ תרכ\"ז ע' שג. וש\"נ."],["1085","56","<b>בהתפעלות המדות אינו יכול לדבר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380204\" data-slug=\"likkutei-torah\" data-id=\"4001380204\">לקו\"ת קדושים כט, סע\"ג</a> ואילך."],["1086","57","<b>אור של תולדה</b>: ראה ע\"ח שער דרושי (כללות) אבי\"ע שמ\"ב, פי\"ג. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שמט ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550363\" data-slug=\"torat-chaim\" data-id=\"2300550363\">תו\"ח ויקהל ח\"ב שפט, א</a>. וש\"נ. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 118."],["1087","58","<b>משלי שלמה</b>: משלי א, א."],["1088","59","<b>וידבר שלשת אלפים משל</b>: מלכים-א ה, יב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670143\" data-slug=\"torat-chaim\" data-id=\"2300670143\">תו\"ח לך פא, ד</a> ובהערה 31. וארא ח\"א פג, ב. וש\"נ. סה\"מ תרל\"ח ע' רכח. וש\"נ."],["1089","60","<b>חצר הכבד</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370019\" data-slug=\"torah-or\" data-id=\"3901370019\">תו\"א בראשית ה, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380403\" data-slug=\"likkutei-torah\" data-id=\"4001380403\">לקו\"ת נשא כג, ד</a>. ואתחנן יא, ב."],["1090","62","<b>יהי רקיע ויהי מבדיל</b>: בראשית א, ו [בדילוג]."]]],[2000480172,"הקרומא דפסיק במעוהי דבר נש<sup data-n=\"1091\">61</sup>, והנה אנו רואים שאע\"פ שהקרום מפסיק, אעפ\"כ אינו הפסק גמור, שהרי המח' שולט על הרגל שהוא למטה מן הפרסא כמו על היד שלמעלה מן הפרסא, ולכך כשיש לו כאב בראש מקיזין לו דם ברגל<sup data-n=\"1092\">63</sup> לפי שאינו הפסק גמור, וכך למעלה באצי' אעפ\"י שיש שם פרסא המפסיק מ\"מ אינו הפסק גמור אלא איהו וחיוהי וגרמוהי חד בהון<sup data-n=\"1093\">64</sup> כו', ולהבין איך איהו וחיוהי וגרמוהי חד בהון שהרי הכלים הם מגבילים את האור כמו שאנו רואים למטה כששואבין מים מן הנהר בכלי שהכלי מגביל את המים, שבנהר הם בלי הגבלה שהנהר נובע מן המעיין בלי הפסק, אבל כשממשיכין את המים בכלי הם נגבלין, וכך למעלה כיון שנק' בשם כלים א\"כ הם מגבילין את האור, ואוא\"ס הוא למעלה מגדר בחי' גבול כי הוא בלתי בע\"ג בתכלית, וא\"כ איך הוא איהו וחיוהי וגרמוהי חד כו', והענין הוא דבאמת באצי' אינם בבחי' גבול בעצם רק מה שנק' למעלה בשם כלים היינו הכח שיש באוא\"ס ג\"כ לעשות גבול<sup data-n=\"1094\">65</sup> כי כמו שהוא ית' הוא בלתי בע\"ג כמ\"כ יש בו כח לעשות גבול כו' כי אנת הוא שלימותא דכולא<sup data-n=\"1095\">66</sup>, ואם תאמר שהוא בבע\"ג ואין לו כח בגבול הרי אתה מחסר שלימותו<sup data-n=\"1096\">67</sup> כו', וזהו הכח שיש באוא\"ס על גבול זהו הנק' למעלה בשם כלים, וזהו שם שדי שאמר לעולמו די<sup data-n=\"1097\">68</sup>, ואעפ\"כ הוא שם קדש אלא ששם זה הוא רק כח על גבול וזהו ענין הכלים דאצי', וא\"כ איהו וגרמוהי חד בהון לפי שזהו ג\"כ כח אוא\"ס כמו האור שהוא בלתי בע\"ג, וזהו מ\"ש במדרש כהדין קמצא דלבושי' מיני' ובי' כו', ויובן זה עוד ממשל רוחני מזה שאנו רואים שהשכל הוא למעלה מהאותיות ואותיות המח' והדבור הם רק בחי' לבושים להשכל כו', ואעפ\"כ אינו לבוש מסתיר כנ\"ל ואדרבה עיקר הגילוי של השכל הוא ע\"י אותיות המח' והדבור כו', אבל כשמלבישים את השכל במשל הוא מסתיר על השכל כו', וזהו החילוק ג\"כ שבין פרסא שיש באצי' גופא לבחי' פרסא שבין אצי' לבריאה, שבאצי' זהו ע\"ד כמו שהאותיות מלבישים להשכל ומאצי' לבי\"ע זהו ע\"ד התלבשות השכל במשל כו'.\nה) <b>והנה</b> זהו בדרך כלל סדר השתלשלות כו', אבל ע\"י תו\"מ ממשיכים שיהי' מאיר אוא\"ס בכל הע\"ס בבחי' קירוב, ולהבין זה איך ע\"י תומ\"צ ממשיכי' בחי' קירוב<sup data-n=\"1098\">69</sup> כו', צ\"ל מקודם ענין הקרבנות שהיו מקריבין ע\"ג המזבח, דהנה פי' קרבן הוא מלשון קירוב<sup data-n=\"1099\">70</sup> דהיינו שע\"י שמקריבין בהמה ע\"ג מזבח ממשיכים שיהי'",[["1091","61","<b>בזהר. . הקרומא דפסיק במעוהי דבר נש</b>: ראה זהר בראשית לב, ב."],["1092","63","<b>כאב בראש מקיזין לו דם ברגל</b>: ראה גם שער האמונה סג, ב ובהערה 9. סה\"מ תרל\"ח ע' רל. וש\"נ."],["1093","64","<b>איהו וחיוהי וגרמוהי חד בהון</b>: ראה ת\"ז בהקדמה ג, ב."],["1094","65","<b>כלים היינו הכח. . לעשות גבול</b>: ראה שער היחוד פכ\"ט ובהערה 6. שערי אורה עח, ב ואילך (פע\"ו) ובהערה 1. סה\"מ תרכ\"ז ע' שנא. וש\"נ. וראה גם לקמן מאמר ד\"ה ויובן כו' הני ששה ועשרים הודו ובהערה 114. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה כמגדל דוד צוארך ובהערה 24."],["1095","66","<b>אנת הוא שלימותא דכולא</b>: ראה ת\"ז בהקדמה יז, ב."],["1096","67","<b>ואם תאמר. . ואין לו כח בגבול. . שלימותו</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו רפ\"ז. וש\"נ."],["1097","68","<b>שם שדי שאמר לעולמו די</b>: ראה חגיגה יב, א. ב\"ר פ\"ה, ח. פמ\"ו, ג. אוה\"ת וארא ע' קלה. סה\"מ תרכ\"ז ע' צא."],["1098","69","<b>ע\"י תו\"מ. . בחי' קירוב</b>: ראה אוה\"ת על ענינים כאן ע' קפד ואילך."],["1099","70","<b>קרבן הוא מלשון קירוב</b>: ראה אוה\"ת על מארז\"ל ס\"ע סה: ובזהר פ' ויקרא דף ד' [כנצ\"ל: ה'] ע\"א. סה\"מ מלוקט ב' ע' קכב. וש\"נ. זהר צו<sup data-n=\"e124\">ז</sup> לא, א. מאו\"א מערכת קרבן אות כא<sup data-n=\"e125\">ח</sup>. ע\"ח שער מ\"ן ומ\"ד של\"ט, פ\"א.\n\n<b>ז</b>  וכן צ\"ל ביאיר נתיב למאו\"א שהובא בפנים ההערה. נעתק באוה\"ת על מארז\"ל ע' סו.\n\n<b>ח</b>  נעתק בקיצור לשון באוה\"ת על מארז\"ל ע' סו. ענינים כאן ס\"ע קפד."]]],[2000480173,"מאיר אוא\"ס בבחי' קירוב, ולהבין זה איך ע\"י שמקריבין בהמה גשמי' על המזבח ממשיכים אוא\"ס כו', הענין הוא דהנה שרש הבהמה הוא מעולם התהו שלמעלה מעולם התיקון<sup data-n=\"1100\">71</sup>, שבתיקון הוא בבחי' מיעוט האור וע\"כ שייך שם בחי' קירוב וריחוק לפי שהוא בבחי' מיעוט, אבל בעולם התהו הי' ריבוי האור<sup data-n=\"1101\">72</sup> ע\"כ אינו שייך שם בחי' ריחוק אלא הכל בבחי' קירוב, לפי שמאיר שם בבחי' ריבוי וכיון ששרש הבהמה הוא מעולם התהו שהי' מאיר שם בבחי' קירוב רק שנפלה בשבירה, ע\"כ כשמבררין אותה ומקריבין אותה ע\"ג המזבח נתעלה לשרשה<sup data-n=\"1102\">73</sup> שמעולם התהו, ועי\"ז נעשה המשכת אוא\"ס למטה ג\"כ בבחי' קירוב דרוח אייתי רוח<sup data-n=\"1103\">74</sup> ואמשיך רוח כו', והנה עכשיו תפלה כנגד תמידין תקנו<sup data-n=\"1104\">75</sup>, וזהו ענין ק\"ש, דהנה איתא שהוי' אלקינו הוא יחוד חו\"ב<sup data-n=\"1105\">76</sup>, והנה פי' יחוד חו\"ב היינו שיהי' מאיר בבחי' בינה ג\"כ בקירוב כמו בחכ' שזהו בחי' יחוד, לפי שעפ\"י סדר השתלשלו' אינו מאיר בבינה כ\"א בבחי' ריחוק, אבל ע\"י ק\"ש נעשה יחוד חו\"ב דהיינו שמאיר גם בבינה בבחי' קירוב כנ\"ל כמו בחכ', וכך ע\"י כל המצות ממשיכי' בבחי' קירוב כו', להיות כי ע\"י המצות שעושים מדברים גשמיי' כמו סוכה מסכך גשמי וד' מינים שבלולב, וציצית מצמר גשמי ותפילין מקלף גשמי שהם ממה שנפל בשבה\"כ מעולם התהו ומעלים אותם לשרשם דתהו שלא יש שם קירוב וריחוק, ועי\"ז נמשך שגם בבחי' התיקון יהי' אוא\"ס בבחי' קירוב כו', וזהו שרש ענין המקיפי' דבינה שנמשכים ע\"י סכך הסוכה כי הסכך הוא ממה שנפל בשבה\"כ מבחי' התהו ששם הי' הכל בבחי' קירוב כנ\"ל מחמת ריבוי האור, ועי\"ז נעשה גם בבינה בבחי' קירוב עד שגם למטה מאיר הארה מבחי' מקיפים דבינה כו'.",[["1100","71","<b>התהו שלמעלה מעולם התיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. וש\"נ. ראה גם לקמן מאמר ד\"ה ביום השמיני עצרת הערה 51."],["1101","72","<b>שבתיקון. . מיעוט האור. . התהו הי' ריבוי האור</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a> ואילך. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' בסופה. וש\"נ."],["1102","73","<b>הבהמה. . נתעלה לשרשה</b>: ראה זהר פינחס רמ, ב. סה\"מ תרכ\"ז ע' קמה ואילך ובהנסמן שם. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמוכים לעד פ\"ב."],["1103","74","<b>דרוח אייתי רוח</b>: ראה זהר תרומה קסב, ריש ע\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדה\"א בראשית ע' רל. וש\"נ."],["1104","75","<b>תפלה כנגד תמידין תקנו</b>: ראה ברכות כו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380630\" data-slug=\"likkutei-torah\" data-id=\"4001380630\">לקו\"ת פינחס עז, ג</a>."],["1105","76","<b>שהוי' אלקינו. . חו\"ב</b>: ראה פע\"ח שער הק\"ש ש\"ח, פ\"ז. פי\"א."]]],[2000480174,"<h3>ולקחתם לכם</h3>\nולקחתם לכם<sup data-n=\"1106\">1</sup> ביום הראשון<sup data-n=\"1107\">2</sup> פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל, ונודע ממ\"ש בכהאריז\"ל<sup data-n=\"1108\">3</sup> ובמ\"ח בקצרה<sup data-n=\"1109\">4</sup> שענין הנענוע בד' מינים שבלולב הוא בחי' המשכת הדעת לנוק' דז\"א העומדת בחזה דז\"א, ולכאורה יפלא מדוע ע\"י אלו הצמחים גשמים<sup data-n=\"1110\">5</sup> דוקא בהם וע\"י יומשך הדעת ולמה לא יפעלו זה ע\"י הכוונה והתקשרות הדעת באלקות, ומדוע דוקא ע\"י העשייה גשמית דוקא ממשיכים המשכות גם אם לא יכוין הכוונות פרטית<sup data-n=\"1111\">6</sup> כ\"א בכלל מה שציוונו ה' אלקינו ליקח ד' מינים אלו, ולנענע בהם, רק שאם מכוין הכוונה פרטיות ה\"ז יותר משובח<sup data-n=\"1112\">7</sup>, כי מצוה בלא כוונה<sup data-n=\"1113\">8</sup> היא כגוף בלא נשמה, אבל מ\"מ אינו מעכב כלל, ובכוונה לבדה בלתי הלקיחה שלהם והנענוע גם אם יכוין כל היום לא יפעול מאומה כו', וגם צ\"ל מדוע ד' מינים אלו דוקא הם הם הממשיכים בחי' המשכת הדעת כו'. ויובן זה ע\"פ מה שפי' הה\"מ ז\"ל<sup data-n=\"1114\">9</sup> על מ\"ש בע' נפש דיעקב<sup data-n=\"1115\">10</sup> נפש ל' יחיד, ובעשו שהיו רק ששה נא' נפשות ל' רבים, כי זהו הכלל שבכ\"מ שהוא בחי' ריבוי ובחי' יש א\"א להיות מזה בחי' אחדות, אבל ע\"י בחי' ביטול בחי' אין נעשה אחדות, כמו שנא' עושה שלום במרומיו<sup data-n=\"1116\">11</sup> שר של מים ואש אין מכבין זא\"ז, אף שבאמת הם הפכים רק שע\"י הביטול מגילוי",[["1106","1","<b>ולקחתם לכם</b>: בספר התולדות מאדמו\"ר מהר\"ש ברשימת המאמרים נרשם אודות מאמר זה<sup data-n=\"e126\">א</sup>: ענין הנענוע כו' ד\"מ גשמיים.\nמאמר זה הוא הדרוש דליל ב' דסוכות שנת תרל\"ד נדפס בסה\"מ תרל\"ג ח\"ב (ע' תקלד ואילך. ראה בהנסמן שם).\nמאמר זה הוא מאמר ד\"ה שרשי הדברים הנ\"ל ביאור לד\"ה ביום השמע\"צ משנת תקע\"ב שנרשם בגוכתי\"ק הצ\"צ<sup data-n=\"e127\">ב</sup>. וכאן הוא בתוס' הגהות (ובהוספת התחלה וסיום).\nלפרקים א-ב ראה גם סידור שער הלולב רסא, ג-רסב, ג. רסד, ד-רסה, א<sup data-n=\"e128\">ג</sup>. מאמרי אדה\"א דברים ח\"ד ע' א'שט ואילך. סה\"מ תרל\"ו ח\"ב ע' שנח-שסא. המשך וככה תרל\"ז פרק פז. סה\"מ תרנ\"ב (ע' א) ס\"ע ב-ד.\nפ\"ג ואילך ראה בשינויים ובתוס' הגהות ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010252\" data-slug=\"or-hatorah-hb\" data-id=\"8159010252\">אוה\"ת</a> דרושים לשמע\"צ ע' א'תשעט ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'רפד ואילך. ע' א'רפג ואילך.\nמאמר זה לא נדפס בהמשך יונתי הנדפס."],["1107","2","<b>ולקחתם לכם ביום הראשון</b>: אמור כג, מ."],["1108","3","<b>בכהאריז\"ל</b>: בסידור שער הלולב רסב, ד: בפע\"ח שער הלולב — שכ\"ט, פ\"א-ג. ראה גם שער הכוונות ענין סוכות דרוש ה. בהערה הבאה."],["1109","4","<b>ובמ\"ח בקצרה</b>: מסכת ימי מצוה וסוכה פ\"ה, מ\"ג. ראה סידור שם רסג, ג ואילך. מאמרי אדה\"א דברים ח\"ג ע' א'שט ואילך. המשך וככה תרל\"ז פפ\"ד ואילך."],["1110","5","<b>גשמים</b>: בסה\"מ תרל\"ג כאן: גשמיים."],["1111","6","<b>פרטית</b>: שם: פרטיות."],["1112","7","<b>שאם מכוון. . משובח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א. שע\"ת יב, ב</a>. <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">עט\"ר נח, ב</a> ואילך. שער האמונה פי\"ד. מאמרי אדה\"א נ\"ך ע' א ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540653\" data-slug=\"torat-chaim\" data-id=\"2300540653\">תו\"ח בשלח ח\"א קנו, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540585\" data-slug=\"torat-chaim\" data-id=\"2300540585\">קסט, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550663\" data-slug=\"torat-chaim\" data-id=\"2300550663\">תצוה ח\"ב שלח, ג</a>. סה\"מ מלוקט ב' ע' נז. וראה גם לעיל המשך יונתי פכ\"א המאמר דר\"ה ד\"ה ויובן ענין הטוב."],["1113","8","<b>מצוה בלא כוונה</b>: ראה לקו\"ת להאריז\"ל עקב ח, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא פל\"ח (נ, א</a>. <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">נא, א</a>)."],["1114","9","<b>הה\"מ ז\"ל</b>: בבוך 1116 כאן: ששמע [אדה\"ז] ממנו בסוכות האחרון תקל\"ג."],["1115","10","<b>בע' נפש דיעקב</b>: ויגש מו, כז. ראה ויק\"ר פ\"ד, ו. רש\"י ויגש מו, כו. מאמרי אדה\"א דברים ח\"ד ע' א'שיא. סה\"מ תרל\"ג ח\"ב כאן ע' תקלד. וש\"נ. תרל\"ו ח\"ב ע' שנח. תרל\"ח ע' פג. וש\"נ."],["1116","11","<b>עושה שלום במרומיו</b>: איוב כה, ב. ראה במד\"ר פי\"ב, ח. וש\"נ. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"נ. וש\"נ.\n\n<b>א</b>  בס' התולדות שם (מהדורת תש\"ז ע' 53) ברשימת מאמרי שנה זו כתב כ\"ק אדמו\"ר אודות מאמר זה רק מספר הפרקים, ובהערה 5 שם רשם: הוא הדרוש דשנת תרל\"ד. בשנה הנ\"ל (בס' התולדות שם ע' 39) נרשם ע\"ד המאמר — הלשון שבפנים.\n\n<b>ב</b>  בוך 1116 ח, ב.\n\n<b>ג</b>  נדפס גם במאמרי אדה\"ז תקס\"ח ח\"א ע' תמז-ח."]]],[2000480175,"הארה<sup data-n=\"1117\">12</sup> שלמעלה מערכם והוא מ\"ש המשל ופחד עמו<sup data-n=\"1118\">13</sup> ועי\"ז הם בבחי' אין ולכן יכולים להתחבר יחד כי המים אינן מים והאש אינו אש עד\"מ עד שיהיו בלתי סובלי' זא\"ז אלא כולם כאחד ממש מחמת שהם בבחי' אין. וביאור הענין דהנה האין המהווה המים שהשר שלהם הוא מיכאל, והאין המהוה האש שהשר שלו הוא גבריאל<sup data-n=\"1119\">15</sup> הנה בהכרח לומר שיש הפרש ביניהם דאל\"כ מדוע בחי' אין זה מהוה מים ואין זה מהוה אש, ולמה לא יתחלפו הווייתן, ומ\"מ ה\"ה קרובים יותר מבחי' המים והאש המתהוים מהם, ולכן כשמאיר על השרים דמים ואש בחי' הגבוה יותר מערכם ה\"ה מתבטלים לאין שלהם ולכן מתייחדים אז כמו שהם אינם מנגדים כלל, וע\"ד שאנו רואים בכחות הנפש<sup data-n=\"1120\">16</sup> שבהיות הנפש מלובש בגוף הנה אנו רואים שהחסד הוא היפך הגבורה מכל וכל שהאיש החסד הנה מטבע הטוב להטיב<sup data-n=\"1121\">17</sup> גם למי שאינו ראוי, ובחי' הגבורה הוא להיפך ממש שגם שמים לא זכו בעיניו<sup data-n=\"1122\">18</sup> שגם להראוי יש ג\"כ מונעים ומעכבים, ונמצא כי הם הפכים, ומ\"מ בעת שהם בנפש קודם התלבשותם בגוף ה\"ה מתאחדים יחד, וכן גם בשמים שהוא בחי' אש ומים<sup data-n=\"1123\">19</sup>, ומ\"מ הם מתכללים כחדא, שזהו ע\"י בחי' רוחא עילאה כו' כמ\"ש בזהר ר\"פ לך לך<sup data-n=\"1124\">20</sup>, ועד\"ז יובן בענין מיכאל וגבריאל כו'<sup data-n=\"1125\">14</sup>, משא\"כ כשהוא בבחי' יש אזי הם כאו\"א בפ\"ע נפשות ל' רבים, אבל יעקב להיותו בריח התיכון<sup data-n=\"1126\">21</sup> שמבריח מן הקצה אל הקצה ומחבר אברהם ויצחק חו\"ג<sup data-n=\"1127\">22</sup> ע\"י המשכת א\"ס ב\"ה שלמעלה מעלה שע\"י בחי' אין אזי מתחברים יחד כנ\"ל וזהו ע' נפש ל' יחיד.\nב) <b>והנה</b> כמו\"כ כל הד' מינים שבלולב הם נמשכים מבחי' זו שהיא בחי' האין בחי' האחדות שמשם הושפל ההארה להיות כן בד' מינים גשמיים הללו, כי אתרוג הדר באילנו<sup data-n=\"1128\">23</sup> משנה לשנה קיץ וחורף קור וחום, ואף גם בא\"י יש שינוי ימות",[["1117","12","<b>הארה</b>: כ\"ה גם בבוך 1116 כאן. בסה\"מ תרל\"ג ח\"ב כאן ע' תקלה: ההארה."],["1118","13","<b>המשל ופחד עמו</b>: התחלת הכתוב עושה שלום במרומיו."],["1119","15","<b>המים. . מיכאל. . האש. . גבריאל</b>: ראה במד\"ר פי\"ב, ח. וש\"נ. לעיל ח\"א (בחלק המאמרים) המשך מצה זו שם. וש\"נ."],["1120","16","<b>וע\"ד שאנו רואים בכחות הנפש</b>: ראה סה\"מ תרנ\"ב כאן ע' ג: עמ\"ש בד\"ה ולקחתם בס' רל\"ג פ\"א בהמשל מכוחות הנפש, והוא כענין שנת' במ\"א בענין עקודים כו'."],["1121","17","<b>מטבע הטוב להטיב</b>: ראה עמק המלך שער שעשועי המלך בתחילתו. שומר אמונים ויכוח שני סי\"ד. שער היחוה\"א פ\"ד ובמ\"מ הגהות והע\"ק לשם. ולהעיר משו\"ת חכם צבי סי\"ח."],["1122","18","<b>שמים לא זכו בעיניו</b>: איוב טו, טו. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רנב ואילך."],["1123","19","<b>בשמים. . אש ומים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח."],["1124","20","<b>רוחא עילאה. . בזהר ר\"פ לך לך</b>: עז, א."],["1125","14","<b>וביאור. . כו'</b>: בסה\"מ תרל\"ג כאן ע' תקלד: (וביאור. . כו'). והוא הוספת כ\"ק אדמו\"ר מהר\"ש. ראה גם לעיל שם ע' תקד ואילך."],["1126","21","<b>יעקב להיותו בריח התיכון</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["1127","22","<b>יעקב. . ומחבר אברהם ויצחק חו\"ג</b>: ראה לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול בסופו. וש\"נ."],["1128","23","<b>אתרוג הדר באילנו</b>: סוכה לה, א. ראה סידור שער הלולב רסא, ג ואילך. רסד, סע\"ד ואילך. רסה, ד. מאמרי אדה\"א דברים ח\"ד ס\"ע א'שיא ואילך. המשך וככה תרל\"ז פרק צד. סה\"מ מלוקט א' ע' רנד."]]],[2000480176,"החמה וימות הגשמים, וכן עפ\"י אמת הוא ב' מדרגות חלוקות ניסן ותשרי<sup data-n=\"1129\">24</sup>, והאתרוג דר באילנו משנה לשנה שסובל ב' הפכים מצד בחי' אין שבו, וכן הלולב שכל ענפיו הם ביושר מדובקי'<sup data-n=\"1130\">25</sup> אלו לאלו לא ככל האילנות שענפיהן מתפרדין זה פונה לכאן וזה לכאן ואף אם אינן בקצוות רחוקים מ\"מ אינן קרובים אלו לאלו כבלולב שמדובקי' ממש ונק' כפות תמרים ל' כ‘פות<sup data-n=\"1131\">26</sup>, וכן ההדס עליו חופים את עצו<sup data-n=\"1132\">27</sup>, והערבה ארז\"ל שנק' אחוינא<sup data-n=\"1133\">28</sup> ע\"ש שגדילים באחוה דהיינו בדיבוק זל\"ז, והכל מפני בחי' אין שבהם ועי\"ז הוא שממשיכים מבחי' דעת שהוא מבחי' אין בחי' חכמה.\nג) <b>אך</b> מה שהצורך דוקא במינים גשמיי' ולא בבחי' דעת רוחני, הוא כי הגשמיות הוא בשרשו נעלה יותר שנמשך מבחי' סוכ\"ע<sup data-n=\"1134\">29</sup> כי מבחי' ממכ\"ע א\"א להיות אלא ההמשכה ברוחני' כמו נפשות הבהמות ונפש הבהמי' שבאדם מפני שור<sup data-n=\"1135\">30</sup> ונפש האלקי' מפני אדם<sup data-n=\"1136\">31</sup> כו' הכל ברוחני', אבל להיות התהוות מציאות גשמי' זה א\"א בשום פנים כלל להתהוות מן הרוחני'<sup data-n=\"1137\">32</sup> כמ\"ש הרמב\"ם שעילה ועלול הכל בערך א' מרוחני' לרוחני'<sup data-n=\"1138\">33</sup> אבל איך יתהוה מזה מציאת גשם זהו דבר שא\"א כלל, כ\"א מבחי' רצון עליון הכל יכול והוא למעלה מן החכ' שהיא בחי' ממכ\"ע שמשם ואילך הוא בחי' השתלשלו'<sup data-n=\"1139\">34</sup> יש מיש אבי\"ע, אבל כשצ\"ל התהוות גשמיות א\"א להיות ממנה כנ\"ל אלא מבחי' כתר רצון<sup data-n=\"1140\">35</sup> עליון אני ראשון ואני אחרון<sup data-n=\"1141\">36</sup> כו', וז\"ש כולם בחכ' עשית<sup data-n=\"1142\">37</sup> ולא נא' חכ' עשה רק שעם החכמה עשה הרצון כי מ\"מ ריבוי ההתחלקות הוא מחמת החכ' אבל גוף המעשה הוא ע\"י הרצון רק שהחכ' מתלבשת ברצון ואז עשית הוא הרצון כו' ולכן ארץ קדמה<sup data-n=\"1143\">38</sup> ששרש הגשמיות נעלה יותר כי הוא בחי'",[["1129","24","<b>ב' מדרגות חלוקות ניסן ותשרי</b>: ראה סה\"מ תרל\"ו ח\"ב ע' שס."],["1130","25","<b>הלולב שכל ענפיו הם ביושר מדובקי'</b>: ראה סידור שער הלולב רסב, ב."],["1131","26","<b>כפות תמרים ל' כפות</b>: ראה סוכה לב, א. סה\"מ מלוקט א' ע' רנג."],["1132","27","<b>הדס עליו חופים את עצו</b>: סוכה לב, ב. ראה סידור שם רסד, ד."],["1133","28","<b>והערבה. . אחוינא</b>: ראה שבת כ, א וברש\"י שם. סידור שם רסב, ג. רסד, סע\"ד. מאמרי אדה\"ז תקס\"ח ח\"א ע' שיז."],["1134","29","<b>הגשמיות. . שנמשך מבחי' סוכ\"ע</b>: ראה לעיל מאמר ד\"ה סוכה שחמתה מרובה מצלתה ובהערה 25."],["1135","30","<b>ונפש הבהמי'. . מפני שור</b>: ראה סידור שער האלול רל, א. ש\"א יז, א הערה 11. סה\"מ תרכ\"ט ע' קי וע' קכז. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויאמר ה' אל אברם לך לך על יד הערה 130."],["1136","31","<b>ונפש האלקי' מפני אדם</b>: ראה מאמרי אדה\"א בראשית ע' קנה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550049\" data-slug=\"torat-chaim\" data-id=\"2300550049\">תו\"ח משפטים ח\"ב רפא, סע\"ג</a> ואילך. סה\"מ תרכ\"ט ע' קי."],["1137","32","<b>התהוות מציאות גשמי. . מן הרוחני'</b>: ראה גם לעיל מאמר ד\"ה סוכה שחמתה מרובה מצלתה ובהערה 25. לקמן ד\"ה ויאמר כו' לך לך על יד הערה 35."],["1138","33","<b>כמ\"ש הרמב\"ם שעילה ועלול. . מרוחני' לרוחני'</b>: ראה מורה נבוכים ח\"ב פכ\"ב."],["1139","34","<b>החכ'. . בחי' השתלשלו'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381236\" data-slug=\"likkutei-torah\" data-id=\"4001381236\">לקו\"ת שה\"ש כו, ד</a>. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1248."],["1140","35","<b>כתר רצון</b>: ראה אגה\"ק סכ\"ט. לעיל מאמר ד\"ה להבין שרש ענין מקיפים דבינה הערה 27."],["1141","36","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["1142","37","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["1143","38","<b>ארץ קדמה</b>: חגיגה יב, א."]]],[2000480177,"החיצוני' דכתר משא\"כ בחי' שמים רוחני' שנמשך מחכמה ממכ\"ע בחי' פנימי' שלמטה במדריגה כידוע בענין הע\"ס דפעמים הכתר נמנה כשמונים י\"ס מבחי' חיצוני' ואז חיצוני' הכתר ראשון ואח\"כ חכ' ואז אין הדעת נמנה ופעמים אינו נמנה<sup data-n=\"1144\">39</sup> כשמונים בחי' פנימי' כי פנימי' הכתר אינו בערך הספי' כלל ואז ראשית היא חכ' דאצי' כו', והנה להיות כי בשבעת ימי הסוכות צריך להמשיך דעת מחדש כנ\"ל וכל המשכת אור חדש הוא ע\"י הכתר דוקא כי אף שההמשכה היא מחכ' אבל א\"א להיות המשכה אם לא ע\"י שמתחלה יומשך הארה מן המקור בחכמה כמשל הנהר כשרוצים להמשיכו אנה ואנה שמתחלה צריך לחפור בעומק יותר להרחיבו בעצמותו וכו', ובחי' ההמשכה מכתר הוא ע\"י בחי' עשי' דוקא ששרשם נלקח מבחי' כתר דוקא כנ\"ל, וכן בחי' סוכות בחי' פנימי' בינה תשו\"ע שביוכ\"פ שמזה נעשה בסוכות מקיף מלמעלה ולכן חמתה מרובה מצלתה פסולה כי הצל בחי' חשך נעלה יותר כמ\"ש בצל החכ'<sup data-n=\"1145\">40</sup> וכתיב ישת חשך סתרו<sup data-n=\"1146\">41</sup>, חשכת מים<sup data-n=\"1147\">42</sup>, כמראה החמה עמוקה מהצל<sup data-n=\"1148\">43</sup> כו'.\nד) <b>והנה</b> האדם מורכב מב' הבחי' נפשו הרוחני' מממלא וגופו הגשמי' שרשו מבחי' סוכ\"ע והתחברותם יחד ע\"י התורה שהיא כלולה מב' הבחי' אוריי' מחכ' נפקת<sup data-n=\"1149\">44</sup> אבל לא כחכמה שהיא חיות העולמות שהיא בחי' נובלות חכ' שע\"ז נא' כולם בחכ' עשית אבל התורה היא בחי' פנימי' חכ' שלכן נענש דוד על שקרא ד\"ת בשם זמירות<sup data-n=\"1150\">46</sup> כמ\"ש באגה\"ק בד\"ה דוד זמירות<sup data-n=\"1151\">47</sup> קרית להו<sup data-n=\"1152\">45</sup>, וכן המצות שהם רצון העליון יש בהם ג\"כ חפץ שהם חפץ ה' ית' ה' חפץ למען צדקו<sup data-n=\"1153\">48</sup> כו', וזהו דכתי' כל אשר חפץ ה' עשה<sup data-n=\"1154\">50</sup> בשמים ובארץ וארז\"ל במד\"ר וארא פי\"ב<sup data-n=\"1155\">51</sup> משל למלך שגזר שבני רומי לא ירדו לסוריא ובני סוריא לא יעלו לרומי, ואח\"כ ביטל הגזירה ואני הוא המתחיל, וכך כתי' השמים שמים לה'<sup data-n=\"1156\">52</sup> והארץ נתן לבני אדם, ואח\"כ ביטל הגזירה",[["1144","39","<b>דפעמים הכתר נמנה. . אינו נמנה</b>: ראה ביאוה\"ז להצ\"צ תשא כרך א ע' ערה ואילך. וש\"נ."],["1145","40","<b>בצל החכ'</b>: קהלת ז, יב."],["1146","41","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["1147","42","<b>חשכת מים</b>: תהלים שם."],["1148","43","<b>כמראה החמה עמוקה מהצל</b>: ראה תו\"כ תזריע יג, ג (הובא ברש\"י שם). ב\"ב פד, א. וש\"נ."],["1149","44","<b>אוריי' מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["1150","46","<b>נענש דוד. . זמירות</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380380\" data-slug=\"likkutei-torah\" data-id=\"4001380380\">לקו\"ת</a> דבסמוך מציין: במדרש רבה [במדבר פ\"ד, כ]. ובתנחומא [פינחס ח] ובגמרא פ\"ז דסוטה ל\"ה ע\"א<sup data-n=\"e129\">ד</sup>. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380380\" data-slug=\"likkutei-torah\" data-id=\"4001380380\">לקו\"ת במדבר יח, א</a> ואילך. יט, ג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450541\" data-slug=\"or-hatorah-hb\" data-id=\"8316450541\">אוה\"ת</a> תהלים כרך ב ע' תקמא. סה\"מ תרכ\"ז ס\"ע שצא ואילך. ע' תסג ואילך. תרכ\"ט ע' תה ואילך. תרל\"ג ח\"ב ע' תקנד ואילך ובהנסמן בהנ\"ל."],["1151","47","<b>באגה\"ק בד\"ה דוד זמירות</b>: תניא קס, א ואילך. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 541."],["1152","45","<b>שלכן. . להו</b>: בסה\"מ תרל\"ג כאן ע' תקלז: (שלכן. . להו). והוא הוספת כ\"ק אדמו\"ר מהר\"ש."],["1153","48","<b>ה' חפץ למען צדקו</b>: ישעי' מב, כא. ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה הנה אנכי כורת עמך ברית על יד הערה 54."],["1154","50","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["1155","51","<b>במד\"ר וארא פי\"ב</b>: אות ג — (בשינויים וכו'). וראה גם פלח הרמון אמור ע' רפ הערה 81."],["1156","52","<b>השמים שמים לה'</b>: תהלים קטו, טז.\n\n<b>ד</b>  ולכאורה כצ\"ל גם בסה\"מ תרכ\"ט שמובא בהמשך ההערה."]]],[2000480178,"דכתי' וירד ה' על ה\"ס<sup data-n=\"1157\">53</sup>, ומשה עלה אל האלקי'<sup data-n=\"1158\">54</sup>, הוי<sup data-n=\"1159\">55</sup> כל אשר חפץ ה' עשה בשוב\"א, והיינו כי שמים הוא בחי' רוחניות בחי' שמים קדמו<sup data-n=\"1160\">56</sup> בחי' ממכ\"ע וארץ גשמית שהתהוותן הוא מבחי' סוכ\"ע<sup data-n=\"1161\">57</sup> ומתחלה היו כ\"א בפ\"ע, וע\"י מ\"ת נתחברו שמים וארץ שע\"י חפץ הוי' הוא בחי' פנימיות הרצון שנק' חפץ<sup data-n=\"1162\">58</sup> וכן תורה היא ג\"כ בח' פנימיות אבא שהוא בחי' פנימיות עתיק<sup data-n=\"1163\">59</sup> עי\"ז מתחברין שמים וארץ שהתהוותם הוא מחיצוניות החכ' וחיצוניות הרצון כנ\"ל וע\"י הפנימיות מתחברים כו'<sup data-n=\"1164\">49</sup>, וע\"כ הם מחברים בחי' החיצוני' שהוא הרצון שממנו נלקח כל הדברים גשמיי' שכולם הם מבחי' רצון שהרי אין בהם חפץ<sup data-n=\"1165\">60</sup> וכן<sup data-n=\"1166\">61</sup> כל הדברים רוחניי' שהם מחיצוני' חכ' כנ\"ל, והענין שבכדי שיהי' המשכת רצונו ית' בדברים ושיהי'<sup data-n=\"1167\">62</sup> התלבשות החכ' בהם הוא מחמת החפץ שיש לו במצות שהוא המכריחם<sup data-n=\"1168\">63</sup>, אף גם כי יש כמה דברים בעולם שלא נעשו בהם מצוה מ\"מ כולם לא נבראו אלא לצוות לזה<sup data-n=\"1169\">64</sup> לחם לאכול ובגד ללבוש<sup data-n=\"1170\">65</sup> ועי\"ז יהי' כח<sup data-n=\"1171\">66</sup> לומר אחד ואהבת<sup data-n=\"1172\">67</sup> שבזה יש לו חפץ וחפץ זה מכריח וגורם התלבשות הרצון וחכ' בכל הדברים השייכי' לזה, וזהו ענין שלום בפמשמ\"ט, וכמו\"כ יש בחי' שלום בפמשמ\"ע להיות התחברות הרצון עליון הנק' סובב עם הי\"ס דאצי' הנק' ממלא הוא ע\"י פנימי' חכ' ובחי' חפץ הנ\"ל, ולכן העוסק בתורה<sup data-n=\"1173\">68</sup> דוקא משים שלום התחברות המאציל עם הנאצלים שזהו ע\"י בחי' רצון הנ\"ל.\nה) <b>והנה</b> יש ב' בחי' תורה, א' לצדיקים בשבועות<sup data-n=\"1174\">69</sup> ולכן הי' בפרהסיא בקולי קולות<sup data-n=\"1175\">70</sup> כי הצדיקים הרי כל מעשיהם באתגלי' כי אינן מתייראי' מכל דבר המזיק אחר ששלימים הם בעבודתם, משא\"כ בחי' מ\"ת הב' שביוכ\"פ<sup data-n=\"1176\">71</sup> שהוא",[["1157","53","<b>וירד ה' על ה\"ס</b>: יתרו יט, כ."],["1158","54","<b>ומשה עלה אל האלקי'</b>: יתרו יט, ג. כתוב זה הובא בילקו\"ש תהלים קטו, טז [רמז תתעג]."],["1159","55","<b>הוי</b>: בשמו\"ר כאן: הרי. אבל כ\"ה בילקו\"ש תהלים שם. תנחומא וארא טו."],["1160","56","<b>שמים קדמו</b>: חגיגה יב, א."],["1161","57","<b>שמים. . ממכ\"ע וארץ. . סוכ\"ע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380394\" data-slug=\"likkutei-torah\" data-id=\"4001380394\">לקו\"ת נשא כא, ג</a>. מאמרי אדה\"ז תקס\"ג ח\"א ע' קכו. שה\"א נח, א ובהערה 2. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540527\" data-slug=\"torat-chaim\" data-id=\"2300540527\">תו\"ח וארא ח\"א עז, א</a>."],["1162","58","<b>פנימיות הרצון שנק' חפץ</b>: ראה שו\"ת הצ\"צ אבהע\"ז ח\"ב סרס\"ג (ח, ג). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540822\" data-slug=\"torat-chaim\" data-id=\"2300540822\">תו\"ח בא ח\"א קכה, ד</a> ובהערה 597. סה\"מ ליקוט ב' ע' רעו."],["1163","59","<b>פנימיות אבא. . פנימיות עתיק</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541072\" data-slug=\"torat-chaim\" data-id=\"2300541072\">תו\"ח שמות ח\"א כג, א</a> הערה 951."],["1164","49","<b>וזהו. . כו'</b>: בסה\"מ תרל\"ג כאן: (וזהו. . כו'). והוא הוספת כ\"ק אדמו\"ר מהר\"ש."],["1165","60","<b>שכולם. . חפץ</b>: כ\"ה גם בבוך 1116 כאן. אבל בסה\"מ תרל\"ג כאן: (שכולם. . חפץ)."],["1166","61","<b>וכן</b>: בסה\"מ תרל\"ג כאן: עם. אבל בבוך 1116 כבפנים."],["1167","62","<b>בדברים ושיהי'</b>: כ\"ה גם בבוך 1116. בסה\"מ תרל\"ג כאן: בדברי' גשמיים ושיהי'."],["1168","63","<b>המכריחם</b>: בסה\"מ תרל\"ג כאן: המכריחו. בבוך 1116 כבפנים."],["1169","64","<b>כולם. . לצוות לזה</b>: ראה ברכות ו, ב."],["1170","65","<b>לחם לאכול ובגד ללבוש</b>: ויצא כח, כ."],["1171","66","<b>יהי' כח</b>: כ\"ה גם בבוך 1116. בסה\"מ תרל\"ג כאן: יהי' לו כח."],["1172","67","<b>אחד ואהבת</b>: ק\"ש — ואתחנן ו, ד. ה."],["1173","68","<b>שלום בפמשמ\"ט. . בפמשמ\"ע. . העוסק בתורה</b>: סנהדרין צט, ב. ראה גם לעיל ח\"א (בחלק המשך מצה זו הערה 939."],["1174","69","<b>תורה. . בשבועות</b>: ראה שבת פו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081021\" data-slug=\"likkutei-sichot\" data-id=\"1300081021\">לקו\"ש שבועות כרך ח ע' 21</a>."],["1175","70","<b>בפרהסיא בקולי קולות</b>: ראה יתרו פי\"ט-כ."],["1176","71","<b>מ\"ת הב' שביוכ\"פ</b>: ראה תענית ל, ב. רש\"י תשא לד, כט. הוספות לשו\"ע אדה\"ז — קה\"ת — חאו\"ח רסתקפ\"א."]]],[2000480179,"כנגד בחי' בע\"ת הוא בצנעא<sup data-n=\"1177\">72</sup> משום שבע\"ת הם הכל בסתר שהרי מתחלה מכסה פשעיו הוא וגם אחרי ששב לה' היינו ג\"כ בסתר, ואז ממעמקי' קראתיך הוי'<sup data-n=\"1178\">73</sup> ועי\"ז מתעלה בנעילה עליי' המל' עד דיקנא<sup data-n=\"1179\">74</sup> ואז מתמלאי' כל הפגמי' והחסרונות שנפגמו בשם הוי' ע\"י התו'<sup data-n=\"1180\">75</sup> וא\"כ הוא למעלה מבחי' מ\"ת דשבועות כנ\"ל<sup data-n=\"1181\">76</sup>, ואח\"כ בסוכות באה הארה זו ומתגלי' מלמעלה למטה בבחי' מקיף עד שאח\"כ ע\"י שבעת ימים אלו וע\"י הלולב ומיניו נמשכה ההארה זו בבחי' פנימי' בשמע\"צ ואז מקיפים עם התורה הגשמיות שכל הדקדוק באותיותיה ונגיעה פסולה<sup data-n=\"1182\">77</sup> שאין זה בשביל הקריאה בדבור שהרי יוכל לקרות האלף אף שיהי' בו נגיעה כו', אלא משום שצ\"ל שלימה באותיותי' הגשמיי' דוקא כי מקרא בעשי'<sup data-n=\"1183\">78</sup> שנשפל בבחי' עשי' וארץ קדמה שהתהוות הגשמיות הוא ממקום יותר עליון כנ\"ל ולכן מקיפים בה על מקום שקוראי' בו כל השנה באותיות הדבור הרוחניי' כו', ואז עצרת תהי' לכם פי' עצרת מלשון עוצר, שההמשכה מתעכבת ונקלטת שלא תהא פולטת ח\"ו וכך ממש הוא למעלה בנשמות ישראל דפעמים נק' אחיי וריעיי<sup data-n=\"1184\">79</sup> ופעמים אם כבנים<sup data-n=\"1185\">80</sup> ואם כעבדים, כי העבד היינו כשהוא בחי' נפרד לגמרי ובן אף שהוא חלק מהאב מ\"מ הוא בחי' שחוץ ממנו שהרי נא' בן יכבד אב<sup data-n=\"1186\">81</sup> א\"כ שייך הכיבוד מן הבן לאב להיותו דבר נמוך ממנו, משא\"כ אחיי וריעיי היינו שהם בערך והשוואה א', כמו\"כ יובן למעלה שהנשמות מתחלה בבחי' אצי' הם אחים וריעים<sup data-n=\"1187\">82</sup> להקב\"ה ואח\"כ נמשכת הטפה בבטן הנוק' ונק' בנים וכשיורדים בבי\"ע אז אם כבנים אם כעבדים, שאפשר שמתגשמי' ביותר עד שנעשים בבחי' פירוד לגמרי להיות כיש ונפרד ממש, והנה בזש\"פ הוא הלידה<sup data-n=\"1188\">83</sup> אבל הקלטת הטפה הוא בשמע\"צ שמתעכבת ברחם הנוק'<sup data-n=\"1189\">84</sup>, וזהו ולקחתם לכם ביום הראשון, ביום הראשון בגימ' כתר<sup data-n=\"1190\">85</sup> וכדי שיומשך בחי' חיבור חיצוני' הכתר עם ע\"ס ושיומשך לכם זהו ע\"י ד' מינים אלו שהם אין כו' ונצטוינו בהם שזהו מפנימי' וחפץ ה' כו'.",[["1177","72","<b>מ\"ת. . שביוכ\"פ. . בצנעה</b>: ראה תשא לד, ג וברש\"י שם. תנחומא תשא לא."],["1178","73","<b>ממעמקי' קראתיך הוי'</b>: תהלים קל, א."],["1179","74","<b>בנעילה עליי' המל' עד דיקנא</b>: ראה פע\"ח שער יוה\"כ פ\"א בסופו. פ\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380699\" data-slug=\"likkutei-torah\" data-id=\"4001380699\">לקו\"ת מסעי צג, ד</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600722\" data-slug=\"or-hatorah-hb\" data-id=\"8316600722\">אוה\"ת פ' ראה ע' תשכב</a>."],["1180","75","<b>התו'</b>: בבוך 1116: התורה. בסה\"מ תרל\"ג כאן: התשובה."],["1181","76","<b>כנ\"ל</b>: ראה גם בהמאמר."],["1182","77","<b>ונגיעה פסולה</b>: ראה שו\"ע יו\"ד סעד\"ר, ס\"ד. שו\"ע אדה\"ז הל' תפילין סל\"ב, ס\"ה. ראה גם לקמן מאמר ד\"ה ושאבתם מים פ\"ד. ו(בחלק ההנחות) בהנחה שם על יד הערה 105."],["1183","78","<b>דמקרא בעשי'</b>: ראה פע\"ח שער הנהגת הלימוד שי\"ז. תניא פ\"מ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380094\" data-slug=\"likkutei-torah\" data-id=\"4001380094\">לקו\"ת ויקרא ה, סע\"א</a> ואילך. מאמרי אדה\"א נ\"ך ע' קלט. וש\"נ."],["1184","79","<b>אחיי וריעיי</b>: תהלים קכב, ח."],["1185","80","<b>אם כבנים</b>: נוסח היום הרת עולם — מוסף לר\"ה."],["1186","81","<b>בן יכבד אב</b>: מלאכי א, ו."],["1187","82","<b>שהנשמות. . אחים וריעים</b>: ראה זהר משפטים קכב, רע\"א. ביאוה\"ז פינחס קיד, ד — קטו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380141\" data-slug=\"likkutei-torah\" data-id=\"4001380141\">לקו\"ת צו טז, סע\"ב</a> ואילך. סה\"מ תרל\"ח ע' קה הערה 241."],["1188","83","<b>בזש\"פ הוא הלידה</b>: ראה פע\"ח שער הלולב שכ\"ט, ספ\"ח. מאמרי אדה\"א ויקרא ח\"א ע' שפז. וש\"נ."],["1189","84","<b>הנוק'</b>: בבוך 1116 ישנו המשך נוסף — הגהת הצ\"צ ונעתק בסה\"מ תרל\"ג ח\"ב כאן ע' תקלח בשולי היריעה."],["1190","85","<b>ביום הראשון בגימ' כתר</b>: ראה לקו\"ת שמע\"צ פה, ד בשם מ\"ע."]]],[2000480180,"<h3>ושאבתם מים</h3>\n<b></b><b>בס\"ד שבת חומ\"ס שנת תרמ\"א ליובאוויץ</b>\n<b></b>ה\"פ [ענין הנסכים כו' נסוך היין בחול ביו\"ט נסוך המים כו' רק ברמז]\nשבת חומ\"ס\n<b>ושאבתם</b> מים<sup data-n=\"1191\">1</sup> בששון ממעייני הישועה (בישעי' סי' י\"ב<sup data-n=\"1192\">2</sup> ), שז\"ע ניסוך המים שהי' בחגה\"ס<sup data-n=\"1193\">3</sup> ובכל השנה הי' רק ניסוך היין לבד<sup data-n=\"1194\">4</sup> ובחגה\"ס ניתוסף גם ניסוך המים, וצ\"ל מפני מה ניסוך היין נאמר בפירוש כמה פעמים בתורה בפ' נסכים<sup data-n=\"1195\">5</sup> ונשנית כמ\"פ, וניסוך המים לא נא' בפירוש בתושב\"כ כלל רק הל\"מ<sup data-n=\"1196\">6</sup> ורבנן סמכוהו אקרא<sup data-n=\"1197\">7</sup> ברמז שביום השני כתי' ונסכיהם שניתוסף מ\"ם לבסוף וביום הששי נא' ונסכיה ניתוסף יו\"ד וביום השביעי נא' כמשפטם<sup data-n=\"1198\">8</sup> ניתוסף ג\"כ מ\"ם (שזהו רק בדרך רמז ולולי הל\"מ אפשר לא היו למדים מזה כלל ניסוך המים רק מאחר שנא' הל\"מ לכן סמכוהו אקרא, הגם) שנא' בדרך רמז בג' ימים, ולכאו' הנה מה שנא' ונשנית בתושב\"כ כמ\"פ בפירוש הנה זהו גדול יותר א\"כ ניסוך היין היא בחי' יותר עליונה, אמנם באמת הנה כתי' ושאבתם מים בששון משא\"כ ביין, וגם ארז\"ל במשנה כל מי שלא ראה שמחת בית השואבה לא ראה שמחה מימיו<sup data-n=\"1199\">9</sup>, וא\"כ גדלה מעלת ניסוך המים על היין כו'. אך הענין הוא דבאמת שניהם אמת, ויובן בהקדם ענין",[["1191","1","<b>ושאבתם מים</b>: אודות מאמר זה<sup data-n=\"e130\">א</sup> נרשם בספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e131\">ב</sup>: ענין הנסכים כו' נסוך היין בחול ביו\"ט נסוך נסוך המים כו' רק ברמז.\nמאמר זה הוא אותו הדרוש דשנת תרל\"ד שנדפס בסה\"מ תרל\"ג ח\"ב ע' תקלט ואילך.\nהמאמר (עד קרוב לסוף פ\"ד) הוא הנחת כ\"ק אדמו\"ר מהר\"ש מדרוש הצ\"צ מ”ש' חוהמ\"ס ך\"א\" עם תיקונים והוספות בשנת תרל\"ג (כנרשם בסה\"מ תרל\"ג כאן).\nלכללות המאמר ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381043\" data-slug=\"likkutei-torah\" data-id=\"4001381043\">לקו\"ת סוכות עט, ד</a> פרקים א-ב (וקיצורים וכו' באוה\"ת סוכות כרך ה ע' ב'קמז ואילך). סידור שער הסוכות רסח, א ואילך. ובשינויים במאמרי אדה\"ז נביאים ע' עט ואילך.\nהמאמר נדפס גם בסה\"מ תרמ\"ד ע' רסו ואילך (בתוס' הגהות). תרנ\"ד ע' יט ואילך (בשינויים קלים). תרע\"ח ע' לח (ושם: ”קיצור ורשומי דברים\" בס\"ד שחה\"ס, רע\"ח, תר\"מ\"<sup data-n=\"e132\">ג</sup>). תרח\"ץ ע' נה ואילך. וראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"ז ואילך.\nהמאמר נדפס גם בקונט' בפ\"ע ע\"ש כ\"ק אדמו\"ר הצ\"צ — קה\"ת תש\"נ.\nלקמן (בחלק ההנחות) נדפסה הנחה ממאמר זה [ומשם נעתקה הכותרת שמופיעה בריש המאמר כאן].\nחלוקת פ\"א לקטעים נעשתה ע\"י המו\"ל (ע\"ד סה\"מ תרל\"ג)."],["1192","2","<b>ושאבתם מים בששון. . בישעי' סי' י\"ב</b>: פסוק ג."],["1193","3","<b>ניסוך המים שהי' בחגה\"ס</b>: סוכה מב, ב. מח, א-ב. רמב\"ם הל' תמידין ומוספין פ\"י, ה\"ו."],["1194","4","<b>ובכל השנה. . היין לבד</b>: ראה רמב\"ם הל' מעשה הקרבנות פ\"ב. הל' תמידין ומוספין פ\"ו, ה\"ו. בסמוך בפנים."],["1195","5","<b>בפ' נסכים</b>: שלח פט\"ו."],["1196","6","<b>וניסוך המים. . הל\"מ</b>: בלקו\"ת כאן מציין: ”סוכה ל\"ד א' זבחים ק\"י ע\"ב\". ראה גם רמב\"ם שבהערה 3."],["1197","7","<b>ורבנן אסמכוהו אקרא</b>: שבת קג, סע\"ב. תענית ב, סע\"ב."],["1198","8","<b>ונסכיהם. . ונסכיה. . כמשפטם</b>: פינחס כט, יט. לא. לג."],["1199","9","<b>כל מי שלא ראה. . מימיו</b>: סוכה נא, א (במשנה).\n\n<b>א</b>  לא נדפס בהמשך יונתי הנדפס.\n\n<b>ב</b>  בס' התולדות שם (מהדורת תש\"ז ע' 53) כתב כ\"ק אדמו\"ר אודות מאמר זה (בשנת תרמ\"א) רק מספר הפרקים, ובהערה 6 שם נרשם: הוא הדרוש דשנת תרל\"ד. בשנה הנ\"ל (בס' התולדות שם ע' 39) נרשם ע\"ד המאמר — כבפנים.\n\n<b>ג</b>  כנראה הכוונה שנמצא בבוך תר\"מ, והוא משנת תרמ\"א."]]],[2000480181,"הנסכים מהו, הנה ארז\"ל כל הקורא ק\"ש בלא תפילין<sup data-n=\"1200\">10</sup> כאלו הקריב עולה בלא מנחה וזבח בלא נסכים, והענין דבד\"כ נסכים הם בחי' המשכה<sup data-n=\"1201\">11</sup> למטה והם היו מג' מינים שמן יין וסולת<sup data-n=\"1202\">12</sup> שרומזי' לג' בחי' חב\"ד, שמן בחי' חכ'<sup data-n=\"1203\">13</sup> ויין הוא בחי' בינה<sup data-n=\"1204\">14</sup> כנודע וסולת הוא בחי' דעת וכמשארז\"ל אין התינוק יודע לקרות אבא<sup data-n=\"1205\">15</sup> עד שיטעום טעם דגן כו', ולכן הקורא ק\"ש כו', דהנה העולה היא בחי' העלאה<sup data-n=\"1206\">16</sup> מלמטלמ\"ע (שהיא כולה כליל<sup data-n=\"1207\">17</sup> ) ועי\"ז נמשך בחי' מנחה שהיא בחי' המשכה כנודע וע' בת\"א בד\"ה ויקח מן הבא בידו מנחה בענין מ\"ן ח' ה'<sup data-n=\"1208\">18</sup>, וזבח הוא קרבן שהוא בחי' העלאה מלמטלמ\"ע, ועי\"ז נמשך נסכים שהם בחי' המשכה מלמעלמ\"ט, ולכן דימה הקורא ק\"ש בלא תפילין כאלו הקריב עולה בלא מנחה כו', כי ק\"ש הוא בחי' העלאה מלמטלמ\"ע שז\"ע ואהבת כו' בכל מאדך<sup data-n=\"1209\">19</sup> בבחי' רצוא ליכלל וליבטל באה\"ע ואה\"ר, ועי\"ז נמשך ההמשכה ע\"י התפילין, והקורא ק\"ש בלא תפילין הוא דומה ממש למקריב עולה בלא מנחה וזבח בלא נסכים כו'. היוצא מזה שנסכים הם בחי' המשכה מלמעלמ\"ט, אכן באופן ושרש המשכתה יש שני בחי' הא' הוא בחי' ניסוך היין והב' הוא בחי' ניסוך המים, ולהבין שרש ההפרש שביניהם, דהנה ביין כתי' החדלתי את תירושי המשמח אלקי' ואנשים (בשופטים ט'<sup data-n=\"1210\">20</sup> ) וארז\"ל אם אנשים משמח אלקי' במה משמח מכאן שאין אומרים שירה אלא על היין<sup data-n=\"1211\">21</sup>, וא\"כ צ\"ל שזה שאומרים שירה על היין עי\"ז הוא משמח את שם אלקי', וצ\"ל ענין ופי' שמשמח ש' אלקי'.\n<b>והענין</b> הוא, דהנה בריאת העולמות הוא מבחי' מדות<sup data-n=\"1212\">22</sup> וכמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"1213\">23</sup> שעולמות הוא מבחי' חסד ועד\"ז מכל המדות (רק שאפ\"ל שמפני שהחסד הוא יומא דאזיל עם כולהו יומין<sup data-n=\"1214\">24</sup> לכן כתי' חסד יבנה, וגם כי עיקר הבנין הוא",[["1200","10","<b>כל הקורא ק\"ש בלא תפילין</b>: ברכות יד, סע\"ב. ראה (ולהבא בסמוך בפנים) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380480\" data-slug=\"likkutei-torah\" data-id=\"4001380480\">לקו\"ת שלח מב, א</a>. מאמרי אדה\"א במדבר ח\"ג ס\"ע א'רא ואילך. אוה\"ת על מארז\"ל ע' יא. סה\"מ תרל\"ח ע' מ ואילך."],["1201","11","<b>נסכים. . המשכה</b>: ראה בהערה שלפנ\"ז."],["1202","12","<b>נסכים. . שמן יין וסולת</b>: שלח פט\"ו."],["1203","13","<b>שמן. . בחי' חכ'</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ט ובהערה 159."],["1204","14","<b>ויין. . בינה</b>: ראה זהר נשא קכז, א. מאמרי אדה\"א ויקרא ח\"א ע' לג. וש\"נ. בראשית ע' תקעא."],["1205","15","<b>אין התינוק יודע לקרות אבא</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540734\" data-slug=\"torat-chaim\" data-id=\"2300540734\">תו\"ח בא ח\"א צה, ב</a>. וש\"נ."],["1206","16","<b>העולה. . העלאה. . וזבח. . העלאה</b>: ראה סה\"מ תרמ\"ד ע' רסז."],["1207","17","<b>העולה. . כולה כליל</b>: ויקרא א, ט. רמב\"ם הל' מעשה הקרבנות רפ\"ו."],["1208","18","<b>בת\"א. . מנחה. . מ\"ן ח' ה'</b>: וישלח כה, ד. וראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' ע (הנחת הר\"מ — נוסח א). ע' עא (הנחת כ\"ק אדה\"א — נוסח ב). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680202\" data-slug=\"torat-chaim\" data-id=\"2300680202\">תו\"ח וישלח קצ, ד</a>."],["1209","19","<b>ואהבת כו' בכל מאדך</b>: ע\"פ ואתחנן ו, ה."],["1210","20","<b>החדלתי את תירושי. . בשופטים ט'</b>: פסוק יג."],["1211","21","<b>אם אנשים משמח. . שירה אלא על היין</b>: ברכות לה, א."],["1212","22","<b>בריאת העולמות הוא מבחי' מדות</b>: לפיסקא זו ראה גם אוה\"ת שה\"ש כרך ב ע' תקנ וע' תקנה. המשך וככה תרל\"ז פכ\"ח. הנסמן בסה\"מ תרל\"ג ח\"ב כאן ע' תקמ. תרל\"ח ע' יד. ולסיום הפיסקא ראה גם לעיל מאמר ד\"ה להבין שרש ענין מקיפים דבינה בתחילתו."],["1213","23","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["1214","24","<b>יומא דאזיל עם כולהו יומין</b>: לעיל ח\"א (בחלק המאמרים) בסוף מאמר ד\"ה ואעשך לגוי גדול מציין: זח\"ג אמור קג, ע\"ב. ראה גם הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'לה."]]],[2000480182,"מהחסד היינו בחי' שיתוף מדה\"ר<sup data-n=\"1215\">25</sup> ותחלת<sup data-n=\"1216\">26</sup> בריאת העולמות הוא ג\"כ מצד כי חפץ חסד<sup data-n=\"1217\">27</sup> הוא<sup data-n=\"1218\">28</sup> כמ\"ש במ\"א) וכמ\"ש זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"1219\">29</sup>, הגם שפי' הפשוט בפי' כי מעולם המה הוא שהם מכבר<sup data-n=\"1220\">30</sup> (ופי' מעולם בל\"א<sup data-n=\"1221\">32</sup> פון אויביק אן<sup data-n=\"1222\">31</sup> ), אך ג\"ז אמת בפי' הפסוק<sup data-n=\"1223\">33</sup> זכור רחמיך כו' שבחי' הרחמים והחסדי' הם שייכים לבחי' עולם דוקא דהיינו שלאחר שנבה\"ע אז שייך בחי' רחמים וחסדים, דהנה בחי' החכ' שייך גם לעצמו שיכול לישב ולהשכיל השכלות, אבל בחי' הרחמים והחסדים אינם שייכים כ\"א על זולתו ולא שייך לומר שישפיע בחי' הרחמים והחסדים שלו על עצמו כו'. וזהו פי' הפסוק זכור רחמיך וחסדיך הם המדות כי מעולם המה שבחי' מדות שייכים לעולמות<sup data-n=\"1224\">34</sup>, ושרש בריאת העולמות נמשכי' מבחי' המדות אלו כו', והנה מצד זה נמשך עולם ל' העלם<sup data-n=\"1225\">35</sup> כו', אבל יש בחי' עליונה יותר שהוא מובדל מבחי' המדות הנמשכים בעולמות והוא בחי' בינה הנק' עלמא דאתכסי'<sup data-n=\"1226\">36</sup> שמכוסה ונעלם כו', ויש רקיע המפסיק בין ז\"א לבינה<sup data-n=\"1227\">37</sup> שז\"ע מ\"ש ועל ראשי החיות רקיע<sup data-n=\"1228\">38</sup> כעין הקרח שהוא הרקיע שע\"ג חיון עילאין<sup data-n=\"1229\">39</sup> כמ\"ש בזהר, וכמ\"ש מבטן מי יצא הקרח<sup data-n=\"1230\">40</sup> היינו בחי' בינה, כי יש פרסא המפסקת ומבדלת בין ז\"א לבינה<sup data-n=\"1231\">41</sup> אשר לכן ז\"א הוא המקור לעלמין דאתגליי' והבינה שלמעלה מהפרסא הוא בחי' עלמא דאתכסי' שמכוסה מן העולמות.",[["1215","25","<b>שיתוף מדה\"ר</b>: ראה פסיקתא רבתי פ' החודש השביעי. ב\"ר פי\"ב, טו. רש\"י בראשית א, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תכ."],["1216","26","<b>ותחלת</b>: בסה\"מ תרל\"ג כאן: ותחילת. אבל בהקונטרס שבהערה 1 כבפנים."],["1217","27","<b>ותחלת בריאת העולמות. . כי חפץ חסד</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, ספ\"ו. סידור שער התפלה יט, רע\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380186\" data-slug=\"likkutei-torah\" data-id=\"4001380186\">לקו\"ת אחרי כה, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">נצבים מז, ב</a>. שעה\"י פי\"א. ש\"א ל, א הערה 15. סה\"מ תרל\"ח ס\"ע מז ואילך ובהנסמן שם."],["1218","28","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["1219","29","<b>זכור רחמיך. . המה</b>: תהלים כה, ו [בדילוג השם]."],["1220","30","<b>שפי' הפשוט. . שהם מכבר</b>: ראה רש\"י לתהלים שם."],["1221","32","<b>בל\"א</b>: בלשון אידיש. ראה שיחת ליל הושע\"ר תשנ\"ב אות ג (שיחות קודש ע' 165 ואילך). ליל שמח\"ת קודם הקפות תשנ\"ב — סה\"ש תשנ\"ב ח\"א ע' 38 בשולי הגליון להערה 20. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211457\" data-slug=\"likkutei-sichot\" data-id=\"1300211457\">לקו\"ש משפטים כרך כא ע' 448</a> הערה 15."],["1222","31","<b>ופי' מעולם בל\"א פון אויביק אן</b>: וכ\"ה בקונטרס הנ\"ל. ועד\"ז בסה\"מ תרמ\"ד כאן ע' רסח. בסה\"מ תרנ\"ד ע' כ: ופי'. . פין אויביג אהן. בסה\"מ תרח\"ץ ע' נח: פון אייביג אן<sup data-n=\"e133\">ד</sup>."],["1223","33","<b>אך. . הפסוק</b>: בקונטרס הנ\"ל ס\"ע 3: אך ע\"ד החסידות פי' הפסוק."],["1224","34","<b>החכ'. . לעצמו. . מדות שייכים לעולמות</b>: ראה גם הנסמן לעיל הערה 22. לעיל המשך יונתי ובהערה 261."],["1225","35","<b>עולם ל' העלם</b>: ראה ספר הבהיר ס\"י. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541025\" data-slug=\"torat-chaim\" data-id=\"2300541025\">תו\"ח שמות ח\"א יח, ד</a> הערה 783."],["1226","36","<b>בינה הנק' עלמא דאתכסי'</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"ח הערה 1185."],["1227","37","<b>רקיע המפסיק בין ז\"א לבינה</b>: ראה בסמוך הערה 39."],["1228","38","<b>ועל ראשי החיות רקיע</b>: נסמן בהערה הבאה."],["1229","39","<b>הרקיע שע\"ג חיון עילאין</b>: ראה לעיל מאמר ד\"ה להבין שרש ענין מקיפים דבינה בתחילתו. וש\"נ."],["1230","40","<b>מבטן מי יצא הקרח</b>: איוב לח, כט. ראה גם סידור שחרית סד, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600692\" data-slug=\"or-hatorah-hb\" data-id=\"8316600692\">אוה\"ת איוב כרך א ע' תרצב</a>."],["1231","41","<b>פרסא. . בין ז\"א לבינה</b>: ראה לעיל הערה 39.\n\n<b>ד</b>  לקמן (בחלק ההנחות) בהנחה כאן ד\"ה ושאבתם מים על יד הערה 37: פון אייביק אן."]]],[2000480183,"<b>ופי'</b> יין המשמח אלקי' כי השמחה הוא בבינה וכמ\"ש אם הבנים שמחה<sup data-n=\"1232\">42</sup> והיינו מפני כי בינה היא בחי' ההשגה וההבנה וכמו עד\"מ באדם שכאשר משיג איזה שכל הנה כשלא יבין עדיין את השכל לא יהי' בשמחה ובתענוג מהשכל כ\"א כאשר ישיג השכל בהבנה היטב אז יתמלא שמחה ותענוג מהשכל כו', כך עד\"ז יובן למעלה שמפני זה בחי' בינה דוקא היא<sup data-n=\"1233\">43</sup> אם הבנים היא שמחה דוקא כי בבחי' בינה הוא ההשגה וההבנה באלקות באורך ורוחב ולכן שם הוא בחי' השמחה דוקא כו', ויין המשמח אלקים היינו שממשיך השמחה שיומשך גם בש' אלקי' מקור התהוות העולמות שגם השם אלקי' יהי' בשמחה היינו שלא יהי' בבחי' צמצום<sup data-n=\"1234\">44</sup> והעלם כ\"א בשמחה וגילוי כו', וזהו ע\"י היין דוקא כמארז\"ל נכנס יין יצא סוד<sup data-n=\"1235\">45</sup> הוא בחי' סוד הוי'<sup data-n=\"1236\">46</sup> כו'. וביאור הענין הנה היין אנו רואים פעולתו<sup data-n=\"1237\">47</sup> בגשמיות אצל האדם שמשמחו ומוציא פנימיותו מהעלם אל הגילוי והיינו מפני כי היין הוא ג\"כ כנוס תחלה בענביו<sup data-n=\"1238\">48</sup> בהעלם וע\"י הדריכה בגת יוצא מהעלם אל הגילוי כו', לכן פעולתו שמוציא באדם ג\"כ מהעלם אל הגילוי וז\"ע שמשמח אנשים כו', ועד\"ז יובן ענין המשמח אלקים שממשיך השמחה מהבינה לבחי' ש' אלקי' שז\"ע השמחה בש' אלקי', וז\"ע נכנס יין יצא סוד דהיינו בחי' בינה עלמא דאתכסי' שמכוסה תחלה ואח\"כ יוצא מהעלם אל הגילוי לשמח אלקי', וכ\"ז הוא ע\"י הלוים שאו' שירה על היין<sup data-n=\"1239\">49</sup> שהשירה הוא בחי' ניגון בקול שהוא בחי' גילוי וע\"י השירה על היין מתגלה בחי' הבינה כנ\"ל וכנ\"ל<sup data-n=\"1240\">*50</sup> שהיין הוא בחי' בינה כו' כנודע, וזהו שרש ענין ניסוך היין שמנסכים היין בהשיתין<sup data-n=\"1241\">50</sup> שהשיתין הוא בחי' מ\"ת שנעשה מהרקיע המפסקת<sup data-n=\"1242\">51</sup> כנודע ממ\"ש במ\"א, והנה מ\"ת<sup data-n=\"1243\">52</sup> בוכים<sup data-n=\"1244\">53</sup> כו' לכן הי' ענין ניסוך היין בהשיתין לשמח את בחי' מ\"ת כו'.\nב) <b>אמנם</b> צ\"ל שרש ענין ההפרש בין ניסוך היין שביו\"ט ובין ניסוך היין שבחול שגם בחול היו מנסכי' היין מהו ההפרש ביניהם. הנה כתי' תחת אשר",[["1232","42","<b>השמחה. . אם הבנים שמחה</b>: תהלים קיג, ט. ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 208."],["1233","43","<b>היא</b>: וכ\"ה גם בקונטרס הנ\"ל ע' 4. בסה\"מ תרל\"ג ח\"ב כאן ע' תקמא: ליתא."],["1234","44","<b>אלקי'. . צמצום</b>: ראה שער היחוה\"א רפ\"ו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540695\" data-slug=\"torat-chaim\" data-id=\"2300540695\">תו\"ח שמות ח\"א לד, ד</a>. וש\"נ."],["1235","45","<b>נכנס יין יצא סוד</b>: ערובין סה, סע\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680053\" data-slug=\"torat-chaim\" data-id=\"2300680053\">תו\"ח ויחי רלו, ב</a>."],["1236","46","<b>סוד הוי'</b>: תהלים כה, יד."],["1237","47","<b>הנה היין. . פעולתו</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"ז. סה\"מ תרכ\"ט ס\"ע שפג ואילך. וש\"נ."],["1238","48","<b>היין. . כנוס תחלה בענביו</b>: ראה פסחים לג, ב. סה\"מ תרכ\"ט ע' שפד."],["1239","49","<b>הלוים שאו' שירה על היין</b>: ראה ערכין יא, א. רמב\"ם הל' כלי המקדש פ\"ג, ה\"ב."],["1240","*50","<b>כנ\"ל וכנ\"ל</b>: כ\"ה גם בהקונט' שבהערה 1. בסה\"מ תרל\"ג כאן: וכנ\"ל."],["1241","50","<b>שמנסכים היין בהשיתין</b>: ראה רמב\"ם הל' מעשה הקרבנות פ\"ב, ה\"א. הל' תמידין ומוספין פ\"י, ה\"ז. אוה\"ת על מארז\"ל ס\"ע ג ואילך."],["1242","51","<b>שהשיתין. . מ\"ת שנעשה מהרקיע המפסקת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380481\" data-slug=\"likkutei-torah\" data-id=\"4001380481\">לקו\"ת שלח מב, ב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010096\" data-slug=\"or-hatorah-hb\" data-id=\"8159010096\">אוה\"ת</a> על מארז\"ל ע' ט ואילך. מאמרי אדה\"א במדבר ח\"ג ע' א'רה ואילך."],["1243","52","<b>מ\"ת</b>: וכ\"ה גם בקונטרס הנ\"ל ע' 4. בסה\"מ תרל\"ג ח\"ב כאן ע' תקמב: מים תחתונים."],["1244","53","<b>מ\"ת בוכים</b>: ראה ת\"ז ת\"ה (יט, ב). לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ט. וש\"נ."]]],[2000480184,"לא עבדת<sup data-n=\"1245\">54</sup> את ה' אלקיך בשמחה שצ\"ל עבודה בשמחה, וכתי' שמחו צדיקים<sup data-n=\"1246\">55</sup> בהוי'<sup data-n=\"1247\">56</sup> נאמר צדיקים דוקא. אך הענין הוא דהנה יש ב' אופנים בענין השמחה כמו שאנו רואים עד\"מ באדם שהגם שהוא שמח עכ\"ז השמחה היא מכוסה ונעלמת ואינה בהתגלות כ\"כ, אבל יש בחי' שמחה שהיא בגילוי כ\"כ שיוצא מהכלי כו', וכך עד\"ז יובן שלהיות<sup data-n=\"1248\">57</sup> שצ\"ל עבודה בשמחה עכ\"ז צ\"ל השמחה מכוסת בהעבודה והעיקר היא העבודה דהיינו שלזולתו יהי' רק גילוי העבודה ורק בפנימיותו צ\"ל בשמחה. והשמחה היא מהתבוננות שכאשר יתבונן שמקיים רצון המלך ממה\"מ הקב\"ה<sup data-n=\"1249\">58</sup>, והרי בגשמיות אינו דומה עבד הטבח לעבד השר שעבד השר עם כי הוא ג\"כ עבד כו', עכ\"ז הוא עבד השר כו' (הדבק<sup data-n=\"1250\">59</sup> לשחרר<sup data-n=\"1251\">60</sup> וישתחוו לך ). וכך עד\"ז יובן שכאשר יתבונן בעשותו א' ממצות ה' הרי הוא עובד את הקב\"ה והרי הוא עבד ה' (ועבד מלך מלך<sup data-n=\"1252\">61</sup> ) לכן מצד זה הוא בשמחה גדולה מאד, אך אעפ\"כ צ\"ל השמחה מכוסה בהעבודה דהיינו שנראה לזולתו רק העבודה שעושה דהיינו שמתעטף בציצית או מניח תפילין והשמחה ש\"מ צ\"ל מכוסה בעבודת עבד שבהמצוה<sup data-n=\"1253\">62</sup>, וז\"ע תחת אשר לא עבדת בשמחה כו' שבחי' שמחה שמכוסה בהעבודה צ\"ל אצל כל אדם כו', אך יש בחי' שמחו צדיקים בהוי' שענין השמחה הוא בא\"א ואינו עד\"ז כלל כ\"א שעיקר הגילוי הוא השמחה והשמחה היא בהוי', וזהו שמחו צדיקים בהוי' שהשמחה בש' הוי' עצמו ולא מצד שהוא עבד ה' כו', ששמחה גדולה ונפלאה יותר עד אין קץ מבחי' העבודה<sup data-n=\"1254\">64</sup> בשמחה הנ\"ל<sup data-n=\"1255\">63</sup>. ועד\"ז יובן שרש ענין ההפרש בין ניסוך היין שבכל השנה לניסוך היין שביו\"ט ובפרט בחגה\"ס שהוא זמן שמחתינו<sup data-n=\"1256\">65</sup>, שניסוך היין שבכל השנה עם כי פעולת היין שמוציא מהעלם אל הגילוי עכ\"ז יש הפרש בזה בין רב למעט, שבכל השנה הגם שמנסכין את היין בכלי שיר<sup data-n=\"1257\">66</sup> עכ\"ז מפני כי בחול אינו זמן הגילוי להיות גילוי השמחה מבחי' בינה לא נמשך השמחה בגילוי כ\"כ כ\"א רק ע\"ד העבודה בשמחה, רק מועדי' לשמחה<sup data-n=\"1258\">68</sup> שהוא זמן שאז מתגלה ההעלם והכיסוי",[["1245","54","<b>תחת אשר לא עבדת</b>: תבוא כח, מז."],["1246","55","<b>תחת. . שמחו צדיקים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380887\" data-slug=\"likkutei-torah\" data-id=\"4001380887\">לקו\"ת תבוא מב, סע\"ג</a> [ובהנסמן במ\"מ לשם]. סה\"מ תר\"ל ע' קיד. עטר\"ת ע' רעז ואילך. מאמר ד\"ה כי תשא תשי\"ז."],["1247","56","<b>שמחו צדיקים בהוי'</b>: תהלים צז, יב. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא</a> ספ\"י. אגה\"ק סי\"ח (הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380889\" data-slug=\"likkutei-torah\" data-id=\"4001380889\">לקו\"ת תבוא מג, א</a>)."],["1248","57","<b>שלהיות</b>: וכ\"ה בקונטרס הנ\"ל ע' 5. בסה\"מ תרל\"ג ח\"ב כאן ע' תקמב: שעם היות."],["1249","58","<b>ממה\"מ הקב\"ה</b>: ברכות כח, ב."],["1250","59","<b>הדבק לשחוור וישתחוו לך</b>: ספרי דברים א, ז. הובא ברש\"י שם ובפ' לך טו, יח."],["1251","60","<b>לשחרר</b>: וכ\"ה (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 80. בקונטרס הנ\"ל: לשחרור. בסה\"מ תרל\"ג: לשחוור."],["1252","61","<b>ועבד מלך מלך</b>: ב\"ר פט\"ז, ג. רש\"י בהעלותך יב, ח. לעיל הערה 59."],["1253","62","<b>והשמחה ש\"מ. . עבד שבהמצוה</b>: ראה סה\"מ תרמ\"ד ע' רסט."],["1254","64","<b>ששמחה. . העבודה</b>: בסה\"מ תרל\"ג ח\"ב כאן ע' תקמג: שהיא שמחה. . עבודה. בקונטרס הנ\"ל כבפנים."],["1255","63","<b>וז\"ע תחת אשר לא עבדת. . הנ\"ל</b>: ראה סה\"מ תרמ\"ד שם."],["1256","65","<b>זמן שמחתינו</b>: נוסח תפלת העמידה וקידוש ליו\"ט. ראה גם לקו\"ת שמ\"ע פט, א."],["1257","66","<b>שמנסכין את היין בכלי שיר</b>: ראה רמב\"ם הל' כלי המקדש פ\"ג, ה\"ג."],["1258","68","<b>מועדי' לשמחה</b>: נוסח תפלת העמידה וקידוש ליו\"ט. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380137\" data-slug=\"likkutei-torah\" data-id=\"4001380137\">לקו\"ת צו טו, ב</a>."]]],[2000480185,"דבחי' בינה עלמא דאתכסי' שמכוסה כל השנה<sup data-n=\"1259\">67</sup>, וגם כשממשיכי' ע\"י ניסוך היין היא ג\"כ מכוסה בהעבודה כו', אבל ביו\"ט הוא מועדים לשמחה שהוא המועד והזמן שמתגלה בחי' השמחה<sup data-n=\"1260\">69</sup> דבינה בהתגלות רב ע\"י ניסוך היין שביו\"ט כו', וזהו שרש ענין ההפרש בין ניסוך היין שבכל השנה לניסוך היין שביו\"ט, שבכל השנה הגם שע\"י הניסוך נמשך ג\"כ השמחה דבינה אכן עדיין היא ג\"כ מכוסה בהעבודה רק עכ\"פ כמו בלא הניסוך היא בחי' עלמא דאתכסי' לגמרי וע\"י ניסוך היין נמשך השמחה להיות עבודה בשמחה, והיינו מפני כי רק מועדים לשמחה כו', אמנם ביו\"ט שהוא בחי' מועדים לשמחה אז השמחה הוא בהתגלות רב כו' שהוא בא\"א כו' וע' בלק\"ת<sup data-n=\"1261\">70</sup> בד\"ה תחת אשר לא עבדת בהג\"ה מסש\"ב<sup data-n=\"1262\">71</sup>.\nג) <b>ומעתה</b> צ\"ל ענין מה שניתוסף בחגה\"ס בחי' ניסוך המים, ושרש ההפרש בין ניסוך היין לניסוך המים, בהיות ידוע כי המים רומזים לבחי'<sup data-n=\"1263\">72</sup> החכ'<sup data-n=\"1264\">73</sup> שלכן המים אין להם גוון<sup data-n=\"1265\">74</sup> ומשתנים לפי גוון הכלי כמ\"ש מזה במ\"א באורך, וע' בד\"ה האזינו השמים<sup data-n=\"1266\">75</sup> כו', והיין רומז לבחי' הבינה כנ\"ל. ושרש ההפרש שביניהם, הנה מההפרש שבין כהנים ללוים יובן ההפרש בין ניסוך היין לניסוך המים, שעבודת ניסוך היין הי' ע\"י שיר הלוים, והנה בלוים כתי' ועבד הלוי הוא<sup data-n=\"1267\">76</sup> פי' הוא, הוא בחי' בינה<sup data-n=\"1268\">77</sup> כמ\"ש בזהר ועבודת הלוי הי' להמשיך מבחי' בינה בחי' הוא כנ\"ל, וזהו ע\"י השיר שהוא בחי' לארמא קלא<sup data-n=\"1269\">78</sup> כו', משא\"כ עבודת הכהנים הי' בחשאי<sup data-n=\"1270\">79</sup>, והיינו באופן הביטול יש ב' אופנים הא' ע\"ד עבודת הלוים שהיא לארמא קלא בחי' ניסוך היין, והב' בחי' הביטול וההשתחווא' דכהנים שעבודתם בחשאי אינון כו'<sup data-n=\"1271\">80</sup>, והענין הוא כי יש בחי' רזין ויש בחי' רזא דרזין<sup data-n=\"1272\">81</sup>, וזהו שרש ההפרש בין כהנים ללוים שהלוים ממשיכים בחי' רזין היינו מה שהי' סתום תחלה ונעלם דהיינו בחי' הבינה והלוים ממשיכים להיות בחי' זו בגילוי, אבל יש בחי' סדכ\"ס<sup data-n=\"1273\">82</sup> שהוא בחי' רזא דרזין שהוא סוד גם מבחי' הסוד ובחי' זו נמשך ע\"י הכהנים שז\"ע ניסוך המים שבחג, ולכן בלוים נא' ל' טהרה ובכהנים נא' קדושה<sup data-n=\"1274\">83</sup> שגדלה מעלת",[["1259","67","<b>רק מועדי'. . השנה</b>: בסה\"מ תרל\"ג: (רק במועדים. . השנה). בקונטרס שם כבפנים."],["1260","69","<b>ביו\"ט הוא מועדים לשמחה. . שמתגלה בחי' השמחה</b>: ראה לקו\"ת שמ\"ע פח, ד."],["1261","70","<b>בלק\"ת</b>: תבוא מג, רע\"א."],["1262","71","<b>מסש\"ב</b>: ח\"א, פ\"י."],["1263","72","<b>המים רומזים לבחי' החכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a> ובמ\"מ הגהות והע\"ק שם. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ספמ\"ב. וש\"נ."],["1264","73","<b>המים. . החכ'</b>: ראה סה\"מ תרמ\"ד ע' ער: י\"ל הכוונה לבחי' אור החכמה."],["1265","74","<b>המים אין להם גוון</b>: ראה פרדס שער עצמות וכלים שער ד, פ\"ד. הנסמן בסה\"מ תרל\"ג כאן. תרל\"ח ע' קמה. וש\"נ."],["1266","75","<b>בד\"ה האזינו השמים</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381016\" data-slug=\"likkutei-torah\" data-id=\"4001381016\">לקו\"ת האזינו עג, ב</a>."],["1267","76","<b>ועבד הלוי הוא</b>: קרח יח, כג."],["1268","77","<b>הוא. . בינה</b>: ראה ביאוה\"ז בלק — להצ\"צ כרך א — ע' תקכ ואילך. וש\"נ. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"ח. וש\"נ."],["1269","78","<b>הלוי. . לארמא קלא</b>: ראה זהר שמיני לט, א. קרח קעז, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פט\"ל. וש\"נ."],["1270","79","<b>עבודת הכהנים הי' בחשאי</b>: ראה לעיל המשך מצה זו שם. וש\"נ."],["1271","80","<b>בחשאי אינון כו'</b>: ראה סה\"מ תרמ\"ד ע' ער."],["1272","81","<b>רזא דרזין</b>: לשון הזהר בכ\"מ. ראה זהר בראשית מה, ב."],["1273","82","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["1274","83","<b>בלוים נא' ל' טהרה ובכהנים נא' קדושה</b>: בהעלותך ח, ז. אמור כא, ח. ראה לקו\"ת יו\"כ סט, א. סה\"מ תרח\"ץ כאן ע' סג. וש\"נ."]]],[2000480186,"הקדושה על הטהרה כו'<sup data-n=\"1275\">84</sup>. וביאור הענין הנה כתי' אנכי אנכי הוא מוחה פשעיך<sup data-n=\"1276\">85</sup>, פי' אנכי ב\"פ כי כדי שיהי' בחי' הוא היינו בחי' ועבד הלוי הוא (בחי' בינה) זהו ע\"י אנכי אנכי שיש ב\"פ אנכי כדי להיות בחי' הוא, והיינו כי אנכי הא' (למפרע) הוא בחי' סוכ\"ע ואנכי הב' הוא בחי' שלמעלה מבחי' סובב כו', וכדי להמשיך ב' בחי' אנכי אלו זהו ע\"י ניסוך היין וניסוך המים, דהנה יש ב' בחי' אלו בעבודה בנפש האדם ג\"כ, וז\"ע ממעמקי' קראתיך<sup data-n=\"1277\">86</sup> שיש ב' בחי' עומקים והיינו כי יש בחי' עומק הלב והפי' הוא כי בינה ליבא<sup data-n=\"1278\">87</sup> ועומק הלב זהו בחי' פנימיות הבינה<sup data-n=\"1279\">88</sup> בעבודה, ולכן ע\"י העבודה בבחי' עומק הלב ממשיכים מבחי' אנכי בחי' סוכ\"ע בבחי' בינה אם הבנים<sup data-n=\"1280\">89</sup> בחי' הוא כנ\"ל, אכן יש בחי' תעלומות לב<sup data-n=\"1281\">90</sup> והוא בחי' היותר נעלה מבחי' עומק הלב והיינו כי לב הוא ל\"ב נ\"ח<sup data-n=\"1282\">91</sup> ותעלומות לב הוא בחי' פנימיות החכ' והיינו בחי' פנימיות החכ' שבעבודה שבלב, ועי\"ז ממשיכים בחי' אנכי הוא בחי' שלמעלה מבחי' סוכ\"ע בבחי' הוא, וז\"ס ענין ניסוך המים בעבודה כו'<sup data-n=\"1283\">92</sup>. ומכ\"ז יובן שרש ענין ההפרש בין ניסוך היין לניסוך המים כו' הן בעבודה והן בההמשכה שנעשה ע\"י ב' בחי' הנ\"ל כו'.\nד) <b>אך</b> עדיין צ\"ל מפני מה לא נא' ניסוך המים בתושב\"כ הלא לפמש\"נ ניסוך המים גבוה יותר מניסוך היין ומפני מה ניסוך היין נא' בתושב\"כ כמ\"פ וניסוך המים נא' רק בדרך רמז ועיקרה הוא בתושבע\"פ כו'. הנה תושב\"כ הוא בחי' אותיות שהעיקר הוא האותיות ולכן כאשר חסר אות א' ואפי' רק נגיעה<sup data-n=\"1284\">95</sup> פוסלת<sup data-n=\"1285\">94</sup> וכל אות צ\"ל בדמותו ובצלמו<sup data-n=\"1286\">96</sup> וכל אותיותיה מנויות<sup data-n=\"1287\">97</sup> לבל יחסר ולבל יעדיף כו', אבל בתושבע\"פ העיקר הוא בחי' השכל שבהאותיות<sup data-n=\"1288\">93</sup> ולכן זה אומר",[["1275","84","<b>שגדלה מעלת הקדושה על הטהרה כו'</b>: ראה סה\"מ תרמ\"ד ס\"ע ער ואילך."],["1276","85","<b>אנכי אנכי הוא מוחה פשעיך</b>: ישעי מג, כה. ראה גם להבא להלן <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380902\" data-slug=\"likkutei-torah\" data-id=\"4001380902\">לקו\"ת נצבים מה, ד</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתפ-תתפא."],["1277","86","<b>ממעמקי' קראתיך</b>: תהלים קל, א."],["1278","87","<b>בינה ליבא</b>: ת\"ז בהקדמה יז, א."],["1279","88","<b>בינה. . פנימיות הבינה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381039\" data-slug=\"likkutei-torah\" data-id=\"4001381039\">לקו\"ת סוכות עח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381042\" data-slug=\"likkutei-torah\" data-id=\"4001381042\">עט, ג</a>."],["1280","89","<b>בינה אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אם הבנים. לקו\"ת שמ\"ע פח, ד. שעה\"י קי, ב ובהערה 19."],["1281","90","<b>תעלומות לב</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380902\" data-slug=\"likkutei-torah\" data-id=\"4001380902\">לקו\"ת נצבים מה, ד</a> מציין לתהלים מד [כב] לקו\"ת שמ\"ע פו, ד. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שצב. וש\"נ. שע\"ת ז, א ובהערה 3. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540793\" data-slug=\"torat-chaim\" data-id=\"2300540793\">תו\"ח בא ח\"א קו, ב</a>. וש\"נ. סה\"מ תרל\"ח ע' תעא. לקמן מאמר ד\"ה עטרת תפארת שיבה על יד הערה 4. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 6. (בחלק ההנחות) בהנחה כאן על יד הערה 102."],["1282","91","<b>לב הוא ל\"ב נ\"ח</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תמב ואילך. וש\"נ."],["1283","92","<b>ניסוך המים בעבודה כו'</b>: ראה סה\"מ תרמ\"ד ע' ערא."],["1284","95","<b>נגיעה פוסלת</b>: ראה שו\"ע יו\"ד סעד\"ר, ס\"ד. שו\"ע אדה\"ז הל' תפילין סל\"ב, ס\"ה. ראה גם לעיל מאמר ד\"ה ולקחתם לכם פ\"ה. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 105."],["1285","94","<b>חסר אות א'. . פוסלת</b>: ראה שו\"ע יו\"ד סער\"ה, ס\"ו ובבאר הגולה שם. סה\"מ תרל\"ח ע' תס. וש\"נ."],["1286","96","<b>וכל אות צ\"ל בדמותו ובצלמו</b>: ראה שו\"ע יו\"ד סעד\"ר, ס\"ה. שו\"ע אדה\"ז שם."],["1287","97","<b>וכל אותיותיה מנויות</b>: ראה קדושין ל, א."],["1288","93","<b>תושב\"כ. . אותיות. . בתושבע\"פ. . השכל שבהאותיות</b>: ראה גם (בנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540171\" data-slug=\"torat-chaim\" data-id=\"2300540171\">תו\"ח וארא ח\"א ע, א</a> ואילך ובהנסמן שם ובריש המאמר שם."]]],[2000480187,"באותיות אלו וזה אומר באותיות אלו ואין מדקדקי' בזה כלל, כי העיקר הוא השכל שבהאותיות והאותיות אינם מעלים ואינם מורידים<sup data-n=\"1289\">98</sup> כו'. ולהבין זה הנה איתא בס\"י בשלשה ספרים<sup data-n=\"1290\">99</sup> ברא הקב\"ה את עולמו בספר ובסופר ובסיפור, ורז\"ל אמרו בשלשה דברים ברא הקב\"ה<sup data-n=\"1291\">100</sup> את עולמו בחכ' ובתבונה ובדעת שנא' ה' בחכ' יסד ארץ כונן שמים בתבונה<sup data-n=\"1292\">101</sup> בדעתו תהומות<sup data-n=\"1293\">102</sup> כו', ולכאו' צ\"ל מפני מה בס\"י נא' בספר כו' ורז\"ל אמרו בחכ' כו', אך הענין דבאמת אמרו שניהם דבר א', כי הנה ספר הוא בחי' בינה<sup data-n=\"1294\">104</sup> ותבונה כנודע מענין ספר תורה<sup data-n=\"1295\">105</sup> כו', וסופר בוא\"ו הוא בחי' חכ'<sup data-n=\"1296\">106</sup> כי הסופר הוא שכותב את הספר כו', וסיפור הוא בחי' הדבור הוא בחי'<sup data-n=\"1297\">107</sup> הדעת<sup data-n=\"1298\">103</sup> כמ\"ש מפיו דעת<sup data-n=\"1299\">108</sup>. והנה<sup data-n=\"1300\">109</sup> ארז\"ל עריבים עלי ד\"ס<sup data-n=\"1301\">110</sup> יותר מיינה ש\"ת, והיינו כי ד\"ס הם הם<sup data-n=\"1302\">111</sup> הדברים שנמשכי' מבחי' סופר שלמעלה מבחי' ספר שהוא הכותב הספר, ולכן ניסוך המים להיות כי גדלה מעלתן כ\"כ עד שהם<sup data-n=\"1303\">112</sup> נצטוינו מפי הסופר הכותב הספר, ובספר תורה נמצא רק בדרך רמז לבד, וכנודע שענין הרמז מורה על היותר נעלה, וכאמרם די לחכימא ברמיזא<sup data-n=\"1304\">113</sup>, וכמו קוש\"י לגבי יו\"ד<sup data-n=\"1305\">114</sup> כן ערך הרמז לגבי דבר המפורש בפירוש.",[["1289","98","<b>והאותיות אינם מעלים ואינם מורידים</b>: ראה סה\"מ תרח\"ץ כאן ע' סד."],["1290","99","<b>בשלשה ספרים</b>: ראה ס\"י פ\"א, מ\"א."],["1291","100","<b>בשלשה דברים ברא הקב\"ה</b>: ראה תנחומא ויקהל ה. שמו\"ר פמ\"ח, ד."],["1292","101","<b>ה' בחכ'. . בתבונה</b>: משלי ג, יט."],["1293","102","<b>בדעתו תהומות</b>: משלי שם, כ."],["1294","104","<b>ספר. . בינה</b>: ראה גם זהר יתרו ע, א ובמק\"מ שם. מאו\"א מערכת ספר אות כא. ביאוה\"ז בלק צח, ד. פינחס קיג, ד. מאמרי אדה\"א דברים ח\"ד ע' א'רב. וש\"נ. בהערה שלפנ\"ז."],["1295","105","<b>ספר. . בינה. . ספר תורה</b>: בלקו\"ת כאן פ, א בזהר ויקהל דף רי\"ש, א. ביאוה\"ז בלק צח, ד בשם זהר תרומה."],["1296","106","<b>וסופר. . בחי' חכ'</b>: ראה גם ביאוה\"ז בלק שם. פינחס קיג, סע\"ג ואילך. לעיל הערה 103."],["1297","107","<b>וסיפור. . בחי' הדעת</b>: ראה גם מק\"מ תרומה קלו, ב. קלז, ב. לעיל הערה 103."],["1298","103","<b>ספר. . בחי' בינה. . וסופר. . חכ'. . וסיפור. . הדעת</b>: ראה (בנוסף להערה 1) לקוטי הש\"ס להאריז\"ל לר\"ה טז, ב. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 111. סידור שחרית לשבת קעט, א. סה\"מ תרל\"ד ע' נה. תרל\"ח ע' רצג<sup data-n=\"e134\">ה</sup>. תרנ\"ג ע' רפא<sup data-n=\"e135\">ו</sup>. תש\"ח ע' 273 ובהערות לשם. פלח הרמון בחוקותי ע' תקכ. בהערות הבאות."],["1299","108","<b>מפיו דעת</b>: משלי ב, ו."],["1300","109","<b>והנה</b>: ע\"כ הוא הנחת כ\"ק אדמו\"ר מהר\"ש מדרוש הצ\"צ מ”ש' חוהמ\"ס ך\"א\". ומכאן ועד סיום המאמר ניתוסף בסמיכות לאמירת המאמר — ראה סה\"מ תרל\"ג כאן ע' תקמה בשולי היריעה. וכן נדפס שם קיצור מהבא להלן."],["1301","110","<b>עריבים עלי ד\"ס</b>: ראה ע\"ז לה, א וברש\"י שם. סה\"מ תרח\"ץ כאן ע' סד הערה 74."],["1302","111","<b>הם הם</b>: בסה\"מ תרל\"ג: הם. בקונטרס (שבהערה 1 ע' 7)־ סה\"מ תרמ\"ד־ תרנ\"ג כבפנים."],["1303","112","<b>שהם</b>: בסה\"מ תרל\"ג: שבהם. בקונטרס שם־ סה\"מ תרמ\"ד־ תרנ\"ג כבפנים."],["1304","113","<b>די לחכימא. . ברמיזא</b>: ראה רשב\"ם ח\"ש כג, טז. מדרש משלי כב, טו. זהר בראשית כו, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנב."],["1305","114","<b>קוש\"י לגבי יו\"ד</b>: ראה גם אגה\"ת פ\"ד. סה\"מ תרח\"ץ כאן ע' סד הערה 76.\n\n<b>ה</b>  ראה גם שם ע' סה בשם הפרדס באו\"א.\n\n<b>ו</b>  נדפס גם בקונטרס בר מצוה תרנ\"ג (קה\"ת תש\"ס) ע' ל."]]],[2000480188,"ה) <b>אמנם</b> עדיין צ\"ל מדוע כתיב בס\"ת מצות שהם מבחי' אנכי כמו מצות התשובה<sup data-n=\"1306\">115</sup> דכתי' בה כי המצוה הזאת<sup data-n=\"1307\">116</sup> אשר אנכי מצוך<sup data-n=\"1308\">117</sup> שפי' שמצוה זו דתשובה נמשכת מבחי' אנכי<sup data-n=\"1309\">118</sup> שלמעלה משאר מצות שנק' מצות הוי'<sup data-n=\"1310\">119</sup>, וכן מצות פרה אדומה נא' ג\"כ בפירוש בתורה<sup data-n=\"1311\">120</sup>. אך הענין הוא דהמצות שמבחי' אנכי הם למעלה מן הצמצום לגמרי ורק שהם הם הממשיכים מבעל הרצון להיות נמשך צנור הרצון כמ\"ש בד\"ה והתהלכתי בתוככם<sup data-n=\"1312\">121</sup>, וכן פרה אדומה הגם שעליה אמר שלמה אחכמה והיא רחוקה ממני<sup data-n=\"1313\">122</sup> ומ\"מ נאמרה בפירוש מפני שנא' בה חוקה<sup data-n=\"1314\">123</sup>, וגם אינה דומה לניסוך המים שניסוך המים הוא בחי' יחודים<sup data-n=\"1315\">124</sup>, ולכן לא נא' בתורה רק בדרך רמז לבד, ועיקר הוא הלמ\"מ. ומ\"מ צ\"ל ושאבתם מים בששון חיבור ב' הבחי' דסופר וספר שהו\"ע חיבור חו\"ב<sup data-n=\"1316\">125</sup>, והגם כי או\"א זיווגייהו תדיר<sup data-n=\"1317\">126</sup> לצורך קיום העולמות, זהו בחי' חיצוניות חו\"ב<sup data-n=\"1318\">127</sup>, אבל בחי' פנימיות חו\"ב זה מעוררים ע\"י העלאת מ\"ן ממעשה התחתונים שז\"ע ושאבתם מים בששון, ומצד בחי' יחוד פנימי הלזה נמשך להיות ששון שהוא למעלה משמחה<sup data-n=\"1319\">128</sup> שאם הבנים הוא בחי' בינה היא שמחה כ\"א בחי' ששון. והתחלת התעוררות בחי' ששון זה הוא ע\"י מה שאומרים בר\"ה<sup data-n=\"1320\">129</sup> שש אנכי על אמרתיך<sup data-n=\"1321\">130</sup>, עי\"ז נמשך להיות בחה\"ס בחי' ושאבתם מים בששון, ממעייני הישועה ב' מעיינות<sup data-n=\"1322\">131</sup>, והיינו שהמעיין הוא שמוצאים אותו כשחופרים ומגלים את עפר הארץ מתגלה גיד המעיין הנובע מתחת לארץ, ויש ב' בחי' עפר, א' הוא בחי' ונפשי כעפר לכל תהי'<sup data-n=\"1323\">132</sup>, וצריכים לחפור בעומק העפר",[["1306","115","<b>מצות התשובה</b>: ראה הנסמן לעיל בהמשך יונתי רפ\"כ."],["1307","116","<b>מצות התשובה. . כי המצוה הזאת</b>: ראה רמב\"ן נצבים ל, יא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו\"ת נצבים מה, ג</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141124\" data-slug=\"likkutei-sichot\" data-id=\"1300141124\">לקו\"ש נצבים כרך יד ע' 112</a> הערה 24."],["1308","117","<b>כי המצוה. . אנכי מצוך</b>: נצבים ל, יא."],["1309","118","<b>דתשובה נמשכת מבחי' אנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו\"ת נצבים מה, ג</a>-ד. סה\"מ תרל\"ג ח\"ב ע' תקיט ואילך."],["1310","119","<b>מצות שנק' מצות הוי'</b>: ויקרא ד, ב. יג. כד. ועוד. ראה הערה שלפנ\"ז."],["1311","120","<b>מצות פרה אדומה. . בפירוש בתורה</b>: ראה לקו\"ת ר\"פ חוקת."],["1312","121","<b>בד\"ה והתהלכתי בתוככם</b>: ראה מאמרי אדה\"ז תקס\"ט ע' קלד. הנחות הר\"פ ע' קנז. סה\"מ תרכ\"ט ע' קצו ואילך (ובהנסמן שם ע' קצד)."],["1313","122","<b>אחכמה והיא רחוקה ממני</b>: קהלת ז, כג. ראה זהר רע\"מ פינחס רכג, א."],["1314","123","<b>שנא' בה חוקה</b>: חוקת יט, ב. י."],["1315","124","<b>ניסוך המים. . יחודים</b>: ראה סה\"מ תרע\"ח כאן ס\"ע לח: והגם שנא' מצות תשובה, באמת זהו להיות הרצון דמצות, אבל הוא ציווי אבל נסכים יחוד היינו גילוי."],["1316","125","<b>ושאבתם. . חיבור חו\"ב</b>: ראה לקו\"ת כאן."],["1317","126","<b>או\"א זיווגייהו תדיר</b>: ראה זהר אד\"ז האזינו רצ, ב. ע\"ח שער הכללים פי\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381210\" data-slug=\"likkutei-torah\" data-id=\"4001381210\">לקו\"ת שה\"ש כ, ב</a> ואילך. סה\"מ תרל\"ח ע' פח. וש\"נ."],["1318","127","<b>או\"א זיווגייהו. . חיצוניות חו\"ב</b>: ראה ע\"ח שער הכללים ספ\"ה. פי\"ג. שער הזיווגים שט\"ו, פ\"א. שער הנסירה שכ\"ט, רפ\"ב. פרדס שער מהות והנהגה ש\"ח, פי\"ד. סה\"מ תרל\"ח ע' פח ואילך. וש\"נ."],["1319","128","<b>ששון שהוא למעלה משמחה</b>: ראה גם אוה\"ת מג\"א ע' קנב. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקפז."],["1320","129","<b>שאומרים בר\"ה</b>: לפני תקיעת שופר."],["1321","130","<b>שש אנכי על אמרתיך</b>: תהלים קיט, קסב."],["1322","131","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381042\" data-slug=\"likkutei-torah\" data-id=\"4001381042\">ממעייני הישועה ב</a>' מעיינות</b>: להבא להלן ראה לקו\"ת סוכות עט, סע\"ג-ד."],["1323","132","<b>ונפשי כעפר לכל תהי'</b>: נסמן להלן בהערה 134."]]],[2000480189,"הלזה אם זהו באמת לאמיתו כו', הב' הוא בחי' תורה שנתלבשה בדברים גשמי' שנמשלו לעפר, וע' בד\"ה מי מנה עפר יעקב<sup data-n=\"1324\">133</sup> שבחי' העפר אינו בגדר מספר כו', וזהו ונפשי כעפר לכל תהי' ועי\"ז נמשך להיות פתח לבי בתורתיך<sup data-n=\"1325\">134</sup> שהם ב' מעיינות, ושרש ב' מעיינות אלו הם מב' מזלות דונוצר<sup data-n=\"1326\">135</sup> ונקה כו'.\n<b>",[["1324","133","<b>בד\"ה מי מנה עפר יעקב</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380591\" data-slug=\"likkutei-torah\" data-id=\"4001380591\">לקו\"ת בלק סח, ב</a>."],["1325","134","<b>ונפשי כעפר. . בתורתיך</b>: ברכות יז, א. סיום תפלת העמידה (אלקי נצור). ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קכח. מאמרי אדה\"א קונטרסים ע' שפא. וש\"נ. שערי אורה ע' לו ובהערה 3. לקמן מאמר ד\"ה ויובן כו' הני ששה ועשרים הודו על יד הערה 130. (בחלק ההנחות) בהנחה כאן בסופה."],["1326","135","<b>ושרש ב' מעיינות אלו. . דונוצר ונקה</b>: בלקו\"ת שבהערה 131 מציין: וע' במ\"ח דכ\"א א' ב'."]]],[2000480190,"<h3>ביום</b> השמע\"צ כו' וביאור ענין מ\"ש בפדר\"א שאפר אילו ש\"י כו'</h3>\n- ריח ניחוח כו' רבוי האור דתהו כו'\nג' טעמים שנק' ריח - ב' קיצורים\n<b>שמע\"צ</b>\nשמע\"צ\n<b>ביום</b> השמיני עצרת<sup data-n=\"1327\">1</sup> תהי' לכם<sup data-n=\"1328\">2</sup> כו' פר אחד איל אחד<sup data-n=\"1329\">3</sup>, וארז\"ל במד\"ר במקומו<sup data-n=\"1330\">4</sup> משל למלך שעשה סעודה ז' ימים וזימן לכל בני המדינה כו' כיון שעבר ז' ימי המשתה אמר לאוהבו כבר יצאנו ידינו לכל בני המדינה, נגלגל אני ואתה במה שתמצא ליטרא בשר או דג או ירק, כך אמר הקב\"ה לישראל בהשע\"צ תהי' לכם גלגלו במה שאתם מוצאי' פר אחד איל אחד, והיינו בחה\"ס ביום ראשון הקריבו י\"ג פרים<sup data-n=\"1331\">5</sup> עד שבז' ימי החג הקריבו ע' פרים על עא\"ו<sup data-n=\"1332\">6</sup>, ובשמע\"צ שהוא לכם הוא רק פר אחד איל אחד כו'. ולהבין זה צ\"ל שרש ענין הקרבנות.",[["1327","1","<b>ביום השמיני עצרת</b>: בס' התולדות כ\"ק אדמו\"ר מהר\"ש (מהדורת קה\"ת תש\"ז ע' 53) נרשם אודות מאמר זה: ענין הקרבן כו' ענין הזווגים כו' — ריח ניחוח כו' רבוי האור דתהו כו' ג' טעמים שנק' ריח. ב' קיצורים.\nהנחה ממאמר זה נדפסה לקמן בחלק ההנחות.\nהפתיחה עד לקמן פיסקא וביאור ענין, הנה בהמשך יונתי הנדפס ליתא. בבוך זה מופיע זה בצד השמאלי של העמוד ונכתב מלמעלה למטה.\nמאמר זה צויין אליו לקמן במאמר ד\"ה וכל שיח השדה על יד הערה 35 ושם: וכמבואר בד\"ה ביום השמע\"צ שבד\"ה יונתי בחגוי הסלע. ו(בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 34.\nמאמר זה צויין אליו בסה\"מ תרמ\"ג ע' נג (ומעתיק חלק מתוכנו) ושם מציינו בשם: ע' בד\"ה להבין ענין אפרה ש\"י, מ\"א. והוא שייך ליונתי מ\"ם.\nמאמר זה הובא בסה\"מ מלוקט ב' ע' קכה ובהערה 64.\nבהכותרת כאן נרשם: שמע\"צ. וכ\"ה בהמשך יונתי הנדפס. אבל (לקמן בחלק ההנחות) בהנחה כאן נרשם: ש\"ת."],["1328","2","<b>ביום השמיני עצרת תהי' לכם</b>: פינחס כט, לה."],["1329","3","<b>פר אחד איל אחד</b>: שם כט, לו."],["1330","4","<b>במד\"ר במקומו</b>: במד\"ר פכ\"א, כד בשינויים."],["1331","5","<b>ביום הראשון הקריבו י\"ג פרים</b>: פינחס כט, יג."],["1332","6","<b>עא\"ו</b>: ע' אומות."]]],[2000480191,"<b>וביאור</b> ענין מ\"ש בפדר\"א שאפר של אילו דיצחק<sup data-n=\"1333\">7</sup> זהו יסוד של מזבח הפנימי, שלכאו' אינו מובן מה שייך אפר דאיל שיהי' יסוד מזה\"פ, ויובן בהקדם ענין בחי' הקרבנות שמקריבים פרים ואילים וכבשי'<sup data-n=\"1334\">8</sup> ע\"ג המזבח, ומהם נעשה ריח ניחוח לה'<sup data-n=\"1335\">9</sup>, שלכאו' מה\"ע שע\"י הקרבת הבהמה<sup data-n=\"1336\">*10</sup> ע\"ג המזבח יהי' נמשך ריח ניחוח כו' ומה גם לבחי' ש' הוי' שאם<sup data-n=\"1337\">10</sup> היות ש' הוי' לשון מהוה<sup data-n=\"1338\">11</sup> מ\"מ הוא בדרך ממילא ומאליו ולא &lt;46&gt;\nּ בבחי' כה\"פ בנפעל, שזהו מבחי' ש' אלקי'<sup data-n=\"1339\">13</sup> כמ\"ש בראשית ברא אלקי'<sup data-n=\"1340\">14</sup>, ול\"ב פעמים אלקי' נא' במע\"ב<sup data-n=\"1341\">15</sup>, וש' הוי' הוא רק מהוה מאליו וממילא כמ\"ש יהללו כו' הוי' כי הוא צוה ונבראו, ולא ברא<sup data-n=\"1342\">16</sup> כ\"א נבראו מאליו כו' כמ\"ש בלק\"ת שה\"ש ד\"ה קול דודי<sup data-n=\"1343\">12</sup> ע\"ש, ומ\"מ הקרבנות שהם נבראי' מש' אלקי' יהי' מהם ריח ניחוח להוי' ולש' אלקי' אינו מועיל הקרבן<sup data-n=\"1344\">17</sup> כמ\"ש בזהר כו', וגם צ\"ל ענין שם קרבן איתא בספרים שהוא לשון קירוב<sup data-n=\"1345\">18</sup>, והיינו קירוב הכחות והשמות<sup data-n=\"1346\">19</sup>, שלכאו' יפלא איך ע\"י הקרבת הבהמה גשמיות יתקרבו הכחות והשמות שלמעלה, שלכאורה א\"ז בערך כלל, אך הענין יובן ע\"פ מה שארז\"ל במד\"ר מלמד שהי' הקב\"ה בורא",[["1333","7","<b>בפדר\"א שאפר של אילו דיצחק</b>: ראה שם ספל\"א."],["1334","8","<b>פרים ואלים וכבשי'</b>: קרבנות דחה\"ס — פינחס כט, יג ואילך."],["1335","9","<b>ריח ניחוח לה'</b>: פינחס שם ואילך. ויקרא א, ט. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301490060\" data-slug=\"likkutei-sichot\" data-id=\"1301490060\">לקו\"ש ויקרא כרך לב ע' 1</a> ואילך."],["1336","*10","<b>מהו\"ע שע\"י הקרבת הבהמה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמוכים לעד ובהערה 7."],["1337","10","<b>שאם</b>: כ\"ה בכ\"מ — ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["1338","11","<b>הוי' ל' מהוה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים שער ד, ספ\"י. שער היחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ת\"ש ע' 40. וראה ג\"כ לעיל ח\"א (בחלק המאמרים) המשך מצה זו פמ\"ז."],["1339","13","<b>כה\"פ </b>[ כח הפועל]<b> בנפעל. . ש' אלקי'</b>: ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה ושאבתם מים ובהערות 29-30."],["1340","14","<b>בראשית ברא אלקי'</b>: בראשית א, א."],["1341","15","<b>ול\"ב פעמים אלקי' נא' במע\"ב</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["1342","16","<b>יהללו. . צוה ונבראו ולא ברא</b>: תהלים קמח, ה. ראה סה\"מ תרל\"ג ח\"ב ע' תלא. וש\"נ. לעיל הערה 12."],["1343","12","<b>הוי'. . מהוה. . בדרך ממילא ומאליו. . בלק\"ת שה\"ש ד\"ה קול דודי</b>: יד, ג. ראה גם לקמן מאמר ד\"ה והנה כובע על יד הערה 16. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אשריכם זורעי על כל מים על יד הערה 98. (בחלק ההנחות) בהנחה כאן על יד הערה 14. סה\"מ תרל\"ח ע' יב. וש\"נ."],["1344","17","<b>הקרבנות. . להוי' ולש' אלקי' אינו מועיל הקרבן</b>: ראה זהר משפטים קח א. ויקרא ה, א. אגה\"ת פ\"ז<sup data-n=\"e136\">א</sup> ובמ\"מ הגהות והע\"ק לשם. אוה\"ת (יהל אור) תהלים ע' קצט ואילך. פינחס ע' א'ק. סה\"מ תרכ\"ז ע' שסא. ע' שעו<sup data-n=\"e137\">ב</sup>. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי בסופה. ד\"ה ויאמר כו' לך בתחלתה. (בחלק ההנחות) בהנחה כאן בתחילתה. מאמר ד\"ה איתא בסוף מנחות בא וראה מה כתיב ו' תשרי תש\"ל. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011220\" data-slug=\"likkutei-sichot\" data-id=\"1300011220\">לקו\"ש ויקרא ח\"א<sup data-n=\"e138\">ג</sup> ע' 206</a> ובהערה לשם. שערי זהר למנחות קי, א."],["1345","18","<b>קרבן. . לשון קירוב</b>: ראה זהר ויקרא ה, רע\"א. לעיל מאמר ד\"ה להבין שרש ענין מקיפים דבינה פ\"ה הערה 70."],["1346","19","<b>קרבן. . שהוא. . קירוב הכחות והשמות</b>: ראה בחיי ויקרא א, ט (ע' תא). (וראה גם שם) במדבר ז, י. פינחס כט, יג. דברים א, א. אוה\"ת פינחס ע' א'פז. סה\"מ תרכ\"ז ע' עה. וש\"נ. ע' שנא.\n\n<b>א</b>  ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301870150\" data-slug=\"likkutei-sichot\" data-id=\"1301870150\">לקו\"ש</a> לקולו\"י — אגה\"ת כרך טל ע' 83 ובהערה 86.\n\n<b>ב</b>  סה\"מ תרל\"ב ח\"א ס\"ע קסד ואילך וע' שיז.\n\n<b>ג</b>  לקו\"ש אגה\"ת כרך טל ע' 228."]]],[2000480192,"עולמות ומחריבן, דין אהני' לי'<sup data-n=\"1347\">20</sup> ודין לא אהני' לי'<sup data-n=\"1348\">21</sup>, וכמ\"ש דבר צוה לאלף דור<sup data-n=\"1349\">22</sup> שקאי על המילה או על התו' שלדיעה הא' תתק\"פ דורות נקמטו, ולהב' תתקע\"ד דורות נקמטו<sup data-n=\"1350\">23</sup> שזהו דורות מעולם התהו שדין לא אהני' לי' כו', וכנודע מענין שבה\"כ שהי' בעה\"ת<sup data-n=\"1351\">24</sup> שנפלו ונשברו והאורות נסתלקו<sup data-n=\"1352\">25</sup>, וממה שנפל בשבה\"כ נתהוו בתיקון כל דברים<sup data-n=\"1353\">26</sup> הגשמי' דומם ודצומח וחי ומדבר כו', בכדי שע\"י העבודה יתבררו כו', וזהו שרש יסוד ענין הקרבנות שהאדם מביא בהמה ומקריבה ע\"ג המזבח ונכללת באש שלמעלה בחי' ארי' דאכיל קרבנין<sup data-n=\"1354\">28</sup>, שכמו שלמטה הי' כהן המקריב קרבנות שלהיות הכהן הוא מבחי' החסד<sup data-n=\"1355\">29</sup> לכן הוא מקריב הקרבן שע\"י בחי' החסד שלו הוא מקרב אותו שיתעלה לריח ניחוח להוי', וכ\"ה למעלה בשרשו שנמשך מבחי' חסד לקרב הניצוץ שיש בבהמה הנקרבת שז\"ע שהי' האש בדמות ארי'<sup data-n=\"1356\">30</sup> ע\"ש פני ארי' אל הימין<sup data-n=\"1357\">31</sup> שהוא מבחי' ימין מקרבת<sup data-n=\"1358\">32</sup> המקרב את ניצוץ דתהו שנפל בשבירה ונפרד מאחדותו מאז הי' עולם התהו ועי\"ז נעשה שמחה גדולה<sup data-n=\"1359\">27</sup> מאד למעלה, כמו עד\"מ ב' אוהבים נאמנים שלא ראו זא\"ז זמן מרובה כשמתראים יחד שניהם הם בשמחה רבה ועצומה אשר לא יבא זר ביניהם כלל להפריע שמחתם, וזהו שרש ענין שמחת נשואין שמה' אשה לאיש ומ\"מ מאז נולדו ה\"ה רחוקי' זמ\"ז שזה מתגדל אצל או\"א, וזאת מתגדלת אצל או\"א שע\"פ רוב הם רחוקי' זמ\"ז במרחק רב עד שאינם נודעים כלל וכלל זל\"ז כו', עד שמגיע זמן קישור הנשואין אז בא אחד או כותב לו במכתב איך שבעיר פ' אשר גם היא אינה נודעת לו ואין לו מכירים בשם יש אחד שרוצה להשתדך עמו, והאיש הבינים משתדל בכל כחו לקרב המרוחקי' שהיו קרובים תחלה וכמ\"ש לזאת יקרא אשה<sup data-n=\"1360\">34</sup> כי מאיש לוקחה זאת, וכשם שחוה",[["1347","20","<b>מלמד. . דין אהניא לי'</b>: נסמן בהערה הבאה."],["1348","21","<b>דין. . לא אהניא לי'</b>: ראה ב\"ר פ\"ג, ז. פ\"ט, ב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם הערה 100."],["1349","22","<b>דבר צוה לאלף דור</b>: תהלים קה, ח."],["1350","23","<b>המילה. . התו'. . תתק\"פ. . תתקע\"ד דורות נקמטו</b>: ראה ב\"ר פכ\"ח, ד. תנחומא לך יא. יתרו ט. ראה גם אוה\"ת מטות ע' א'שכב."],["1351","24","<b>שבה\"כ שהי' בעוה\"ת </b>[ בעולם התהו]: ראה ע\"ח שער הכללים פ\"א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ג. וש\"נ."],["1352","25","<b>שבה\"כ. . ונשברו והאורות נסתלקו</b>: ראה גם ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"א. סה\"מ תרל\"ח ע' שנג ואילך. וש\"נ."],["1353","26","<b>נתהוו בתיקון כל דברים</b>: ראה ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש ג. לקמן פיסקא ואמנם."],["1354","28","<b>ארי' דאכיל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ה."],["1355","29","<b>הכהן. . החסד</b>: ראה זהר נשא קמה, ב. צו כז, א. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["1356","30","<b>האש בדמות ארי'</b>: יומא כא, ב."],["1357","31","<b>פני ארי' אל הימין</b>: יחזקאל א, י [ושם: ופני]."],["1358","32","<b>ימין מקרבת</b>: סוטה מז, א."],["1359","27","<b>הקרבנות. . המקרב את ניצוץ דתהו. . נעשה שמחה גדולה</b>: ראה גם הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית כרך ו ע' 2116. סה\"מ תרכ\"ט ע' קיא."],["1360","34","<b>לזאת יקרא אשה</b>: בראשית ב, כג."]]],[2000480193,"היתה מצלעותיו של אדה\"ר<sup data-n=\"1361\">35</sup>, שזה הי' בתחילת הבריאה שגם גופה היתה אחת מצלעותיו דאדה\"ר מפני שעדיין לא הי' גוף זולת גוף אדה\"ר, אבל אח\"כ עם היות &lt;47&gt;\nּ שנתרבו הגופות מ\"מ שרש שרשן הם מאחד דהיינו מאדה\"ר שהוא וחוה מגוף אחד, וא\"כ לפ\"ז עם איזה אשה אשר יזדווג האדם הנה הוא מגוף אחד<sup data-n=\"1362\">33</sup>, וכן בענין הנשמות הנה כל נשמה ונשמה היתה כלולה באדה\"ר שהי' נשמה כלליות<sup data-n=\"1363\">36</sup>, וא\"כ מ\"ע הזיווגי' שהקב\"ה יושב ומזווג זווגים<sup data-n=\"1364\">37</sup> מאז גמר מע\"ב כמארז\"ל, אלא בכדי לזווג שתהי' עזר כנגדו<sup data-n=\"1365\">38</sup> צ\"ל שיהי' שניהם משרש אחד שהגם שכולם היו כלולים באדה\"ר מ\"מ באדה\"ר עצמו הי' בו פרטים רבים, וכמ\"ש בכתהאריז\"ל שיש שהיו מחוטמו<sup data-n=\"1366\">39</sup> ויש מפאותיו<sup data-n=\"1367\">40</sup> ע\"ש, וזהו שרש ענין הזיווגים, אמנם כאשר ע\"פ אמת כולם היו כלולים באדה\"ר שהיו בתכלית הקירוב שקירוב זה אין לך קירוב יותר גדול מזה, ומ\"מ נפרדו משך זמן מאז הוולדם עד שמזווגים אותם שארז\"ל בן שמונה עשרה לחופה<sup data-n=\"1368\">41</sup>, שח\"י שנה היו נפרדי' זמ\"ז בתכלית, ולכן כשמתקרבים להוליד הולדה בדומה להם וכנודע שאיש ואשה שם י\"ה ביניהם וכשמולידים בן ובת נשלם ש' הוי' שבן ובת הם ו\"ה<sup data-n=\"1369\">42</sup>, וזה יהי' בדומה להם שהרי לע\"ל יהי' ו\"ה במדריגת י\"ה, וזהו ביום ההוא יהיה פי' שש' הוי' יהי' ב\"פ י\"ה<sup data-n=\"1370\">43</sup> כו', וזהו בדומה לו, שממילא נעשה השמחה גדולה מאד ששני אוהבים נאמנים שהיו בתכלית הקירוב מאד כנ\"ל ונתרחקו בריחוק מקום עד שלא ידעו זמ\"ז כלל, כשמתקרבי' נעשה השמחה גדולה למאד מאד, ועד\"ז יובן בענין הקרבת הקרבן שמקריבין הניצוץ שהי' מרוחק משרשו ומקורו מאז הי' שבה\"כ שנעשה שמחה גדולה מאד נעלה, ונודע כי שמחה ממתיק דינים<sup data-n=\"1371\">44</sup>, ולכן ע\"י בחי' שמחה זו מתבסמי' הגבורות דש' אלקי' שעם היות שלגבי בחי' הגבו' דש' אלקי' אינו מועיל הקרבן מ\"מ ע\"י בחי' השמחה הנפלאה נמתקים הגבורות דש' אלקי' וממילא אין מדה\"ד מקטרג כו'.",[["1361","35","<b>שחוה היתה מצלעותיו של אדה\"ר</b>: שם ב, כא-כב."],["1362","33","<b>נשואין. . אשה. . האדם. . מגוף אחד</b>: ראה זהר בהקדמה יג, ב. בראשית מז, א. נה, ב. לך צא, ב. מאמרי אדה\"ז אתהלך לאזניא ע' א. המשך וככה תרל\"ז פצ\"ז (ע' קנו). תרל\"ח ע' תפ. (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 46."],["1363","36","<b>באדה\"ר שהי' נשמה כלליות</b>: ראה תנחומא תשא יב<sup data-n=\"e139\">ד</sup>. שמו\"ר פ\"מ, ג. פרדס שער מהות והנהגה ש\"ח, פכ\"ב. ספר הגלגולים פ\"א. פ\"ג ואילך. שער הגלגולים הקדמה ו ואילך<sup data-n=\"e140\">ה</sup>. ל. לא. שער מאמרי רז\"ל סוכה. אגה\"ק ס\"ז. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצא ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540990\" data-slug=\"torat-chaim\" data-id=\"2300540990\">תו\"ח שמות ח\"א יז, א</a> הערה 705. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600683\" data-slug=\"or-hatorah-hb\" data-id=\"8316600683\">אוה\"ת איוב כרך א ע' תרפג</a>."],["1364","37","<b>שהקב\"ה יושב ומזווג זווגים</b>: ראה ב\"ר פס\"ח, ד."],["1365","38","<b>עזר כנגדו</b>: בראשית ב, יח."],["1366","39","<b>בכתהאריז\"ל שיש שהיו מחוטמו</b>: ראה גם מדרשים שבהערה 36."],["1367","40","<b>ויש מפאותיו</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 52: בשערותיו בפאותיו. במדרשים שם: בשערות."],["1368","41","<b>בן שמונה עשרה לחופה</b>: אבות פ\"ה, מכ\"א (ולגי' אדה\"ז בסידורו מכ\"ב)."],["1369","42","<b>שאיש ואשה. . י\"ה. . בן ובת. . ו\"ה</b>: ראה זהר ויקרא יא, ב. רע\"מ צו לד, א. ת\"ז תנ\"ה פח, א. תנ\"ו פט, ב. ביאוה\"ז ח\"ש קל, א."],["1370","43","<b>ביום ההוא יהיה. . ב\"פ י\"ה</b>: זכרי' יד, ט ובלקו\"ת מהאריז\"ל שם. ראה הנסמן במאמרי אדה\"א נ\"ך ע' קנב. סה\"מ תרכ\"ט ע' קכג. וש\"נ."],["1371","44","<b>שמחה ממתיק דינים</b>: ראה גם תו\"א ח\"ש טו, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540168\" data-slug=\"torat-chaim\" data-id=\"2300540168\">וארא נז, ד</a>. תו\"ח וארא ח\"א סט, ג ואילך. וש\"נ.\n\n<b>ד</b>  בעמק המלך שער עולם התהו (ש\"ו, פע\"ב מא, ג)־ שער קרית ארבע (שי\"ד, פנ\"ה צד, א) מציין: שארז\"ל במסכת סנהדרין פרק חלק. בשל\"ה מאמר השני מד, א מציין: המדרש רבה דפ' משפטי'.\n\n<b>ה</b>  וכן צ\"ל במאמרי אדה\"ז שבפנים ההערה."]]],[2000480194,"<b></b>קיצור. בכדי להבין ענין האפר מאיל שנעשה מזבה\"פ צ\"ל ענין הקרבנות שמתקרב הניצוץ דתהו שנפרד מאז הי' שבה\"כ, ועי\"ז נעשה שמחה גדולה כשמחת נשואין ויותר ועי\"ז<sup data-n=\"1372\">45</sup> מתבסמין הגבו' דש' אלקי' שיומתקו כו'.\nואמנם בחי' ריח ניחוח להוי' שנעשה ע\"י העלאת הקרבן צ\"ל שזהו לבד בחי' השמחה הנפלאה שהשמחה הוא מצד הגילוי וגם שמחה גורמת גילוי<sup data-n=\"1373\">46</sup> כמ\"ש במ\"א, שהרי לגבי בחי' ש' הוי' מועיל קרבן ואינו כמו ש' אלקי' שהוא מתבסם כנ\"ל<sup data-n=\"1374\">47</sup>, וגם ש' הוי' הוא רחמים<sup data-n=\"1375\">48</sup> שא\"צ להתבסם כלל כו'. אך הענין הוא עפמשנת\"ל<sup data-n=\"1376\">49</sup> ששרש דצח\"ם הוא מעולם התהו שקדם לבחי' התיקון<sup data-n=\"1377\">50</sup> שענין קדימה זו הוא קדימה במעלה<sup data-n=\"1378\">51</sup> כמשנ\"ת מזה במ\"א באריכות, ושרש הענין הוא שבתהו הי' ריבוי האורות ומיעוט הכלים ובתיקון הוא להיפך שהכלים מרובים והאורות מועטים<sup data-n=\"1379\">52</sup>, ולזאת כאשר הכלים לא הי' באפשרם לסבול האור נשברו, שזהו כמשל תיבת ברוך פירושו גיבענצט<sup data-n=\"1380\">54</sup>, אבל כשמתפרדי' האותיות<sup data-n=\"1381\">53</sup> ב' בפ\"ע רי\"ש בפ\"ע, &lt;48&gt;\nּ וכן ו' ך' בפ\"ע לא נמצא בהם פי' כלל, שעד\"ז יובן שנסתלקו האורות והכלים נפלו ששבירתם זהו נפילתן שאינם נושאי' בתוכם פירוש התיבה, ועי\"ז שנשברו נפלו למטה עד שמבחי' האותיות נעשו כל בחי' דצח\"ם שלמטה כו', ולכן יש בהם כח יותר הרבה שהרי הבהמה והסוס מוליכים את האדם למקום שהוא בעצמו א\"י להגיע לשם שזהו מפני כי הצומח והחי הוא למטה מהאדם לכן זהו ממה שנפל למטה בשבה\"כ שזהו ממה<sup data-n=\"1382\">55</sup> שהי' במעלה יותר בהיותו בבחי' התהו כו', וכמשל החומה<sup data-n=\"1383\">56</sup> שנופל שהאבנים שבראש החומה נופלים למרחוק הרבה יותר מכמו האבנים שבאמצע או בתחתיות החומה כו', ולכן כאשר מתעלים לשרשם הקדום מתעורר",[["1372","45","<b>ועי\"ז</b>: בהמשך יונתי הנדפס: וע\"י."],["1373","46","<b>שמחה גורמת גילוי</b>: ראה מאמרי אדה\"ז תקס\"ו ע' קמח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680298\" data-slug=\"torat-chaim\" data-id=\"2300680298\">תו\"ח ויצא קעג, ב</a> ובהערה 12. בשלח ח\"א קנז, ב ואילך. קסב, ג ואילך."],["1374","47","<b>כנ\"ל</b>: בסוף פיסקא שלפנ\"ז."],["1375","48","<b>הוי' רחמים</b>: ראה ספרי ואתחנן ג, כד. לקח טוב שם. רש\"י ר\"פ בראשית. זהר ויקרא יא, א. אחרי סה, א."],["1376","49","<b>עפמשנת\"ל</b>: בפיסקא שלפנ\"ז."],["1377","50","<b>התהו שקדם לבחי' התיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. וש\"נ."],["1378","51","<b>התהו שקדם לבחי' התיקון. . קדימה במעלה</b>: ראה גם לעיל המשך יונתי ספ\"ז הערה 176. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 71. (ובחלק ההנחות) בהנחה שם על יד הערה 68. בהנחה כאן על יד הערה 63. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמוכים לעד על יד הערה 41. סה\"מ תר\"ל ע' קנ."],["1379","52","<b>שבתהו הי' ריבוי האורות. . ובתיקון. . מועטים</b>: ראה ע\"ח שער הכללים פ\"א ואילך. שער התיקון ש\"י, פ\"ה. שער המלכים שי\"א, פ\"א ופ\"ב. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 81."],["1380","54","<b>ברוך פירושו גיבענצט</b>: ראה גם מאמרי אדה\"ז תק\"ע ע' נא. סה\"מ תרל\"ד ע' קעה. וראה גם (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 67. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מצה זו על יד הערה 36. ד\"ה אז ישיר על יד הערה 55."],["1381","53","<b>הכלים. . נשברו. . כשמתפרדי' האותיות</b>: ראה גם כנפי יונה ח\"ג, סנ\"ו. סקמ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370129\" data-slug=\"torah-or\" data-id=\"3901370129\">תו\"א וישב כז, ג</a>. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 221."],["1382","55","<b>ממה</b>: בהמשך יונתי הנדפס ליתא."],["1383","56","<b>וכמשל החומה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה פ\"א. וש\"נ."]]],[2000480195,"להאיר בהם בחי' אורות דתהו שהי' מאיר בהם תחלה הוא בחי' ריבוי האור דתהו כו'.\n<b>וענין</b> בחי' ריבוי האור<sup data-n=\"1384\">57</sup> הנה לא כמו שמובן לכאו' שבחי' ריבוי האור הוא שבחי' האור הוא בריבוי מאד יותר מכמו בתיקון אבל בחי' האור הוא שוה במעלה לבחי' האור דתיקון רק שהוא בריבוי הרבה מאד, אמנם באמת לא כן הוא שהרי כשם שפי' וענין ריבוי הוא להוסיף שהוא הרבה יותר מכמו מיעוט האור כו' כן בחי' הריבוי מורה גם על עצם מעלת האור ג\"כ שהוא בתוס' מרובה לאין שיעור כלל, וכמו השמש שהוא ריבוי האור נגד אור הלבנה שמלבד הריבוי ה\"ה אור יותר נפלא לאין שיעור כלל, או אור השמש נגד אור היום בעצם שהוא ג\"כ אור שמלבד הריבוי הנה הוא אור נוסף שלא בערך כלל<sup data-n=\"1385\">58</sup> נגד בחי' אור היום. ויובן זה ממה שמצינו בדרז\"ל על אור שנברא ביום ראשון שהי' האדם מביט מסוף העולם ועד סופו<sup data-n=\"1386\">59</sup>, שנת' מזה במ\"א פי' וביאור לשון מסוף העולם ועד סופו שלכאורה הי' צ\"ל מתחלת העולם ועד סופו, אלא שבכלל נחלק כלליות כל העולמות שארז\"ל ע\"פ ועלמות אין מספר<sup data-n=\"1387\">60</sup> ועולמות אין מספר על שני בחי' עלמא דאתכסי' ועדאת\"ג<sup data-n=\"1388\">61</sup>, והכוונה בפי' מסוף העולם דעלמא דאתגלי' מלמעלמ\"ט עד סופו דעלמא דאתכסי' מלמטלמ\"ע, שנמצא הי' האדם מביט באור זה בב' עולמות כללי' אלו שכוללים כלליות השתלשלות העולמות כולם, וכאשר מיעטו הרי יכולת האדם לראות רק ערך פרסא לבד או מיל<sup data-n=\"1389\">62</sup>, שנמצא ריבוי זה ומיעוט אינו בערך כלל, וכ\"ז הוא בתיקון עצמו שהרי אור שנברא ביום ראשון הי' ג\"כ מבחי' התיקון שכלליות בחי' התיקון הוא בחי' מיעוט האור כו', וא\"כ דעת לנבון נקל<sup data-n=\"1390\">63</sup> ענין בחי' ריבוי האור שהי' בבחי' התהו שמלבד בחי' הריבוי הי' אור נבדל בערך לגמרי מבחי' אור דתיקון עד שהי' הכלים דתהו מוכרחי' להשבר ולהתבטל כו', ועם היות שהי' מיעוט הכלים בתהו הרי מצינו",[["1384","57","<b>וענין בחי' ריבוי האור</b>: ראה סה\"מ תר\"ל ע' קנ. תרכ\"ז ע' קיט. וש\"נ. ע' שעד. תרל\"ב ח\"א ע' קסג. תרל\"ד ע' קעד-ה. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת נח כרך ו ע' 2136. סה\"מ תרמ\"ג ע' נג. לעיל המשך יונתי ספ\"ז. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' על יד הערה 82. ד\"ה לכל תכלה ראיתי קץ על יד הערה 72. (ובחלק ההנחות) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 69. בהנחה כאן על יד הערה 71."],["1385","58","<b>או אור. . כלל</b>: בהמשך יונתי הנדפס ליתא. ואולי נשמט מפני תיבות הדומות: כלל. . כלל."],["1386","59","<b>אור שנברא. . האדם. . סופו</b>: ראה חגיגה יב, א. ב\"ר פי\"ב, ו. פי\"א, ב. רמ\"ז לזהר ר\"פ במדבר. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת נח כרך ו ע' 2136. סה\"מ תרכ\"ט ע' ס. וש\"נ. לקמן (בחלק ההנחות) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 70. בהנחה כאן על יד הערה 75. פלח הרמון ויקרא (פסח) ע' עח."],["1387","60","<b>ועלמות אין מספר</b>: שה\"ש ו, ח. ת\"ז בהקדמה (יד, ב). ראה זהר אחרי עא, ב. ע\"ז לה, ב. סה\"מ תרל\"ה ח\"א ע' נג. תרל\"ח ע' ב ואילך. לעיל ח\"א (בחלק המאמרים) המשך מצה זו רפנ\"ב."],["1388","61","<b>עלמא דאתכסי'. . ועדאת\"ג</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."],["1389","62","<b>יכולת האדם לראות. . פרסה. . מיל</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 84."],["1390","63","<b>דעת לנבון נקל</b>: ע\"פ משלי יד, ו."]]],[2000480196,"שהראש הוא מעט הכמות נגד הרגלים עד\"מ מ\"מ הרי בהראש מאירים כל החושים היקרים והיותר חשובים כמו בחי' ג' מוחין דחב\"ד וראי' ושמיעה וריח וטעם ודבור ומחשבה שהם החושי' היותר נעלים שבאדם, ועכ\"ז הוא קטן מהידים והרגלים שהם בעוצם גדלם אין בהם רק כח אחד כח המעשה בידים וכח ההילוך ברגלים, נמצא בחי' קטן<sup data-n=\"1391\">64</sup> &lt;49&gt;\nּ הכלי אינו מונע להיות נמשך בו ריבוי האור כו', וכמ\"כ נבין שגם בתהו עם היות שהי' מיעוט הכלים מ\"מ לא מטעם זה הי' ענין בחי' השבירה כ\"א מצד עצם בחי' ריבוי האור שהי' בריבוי מאד וגם הי' אור נבדל שלא בערך כלל לגבי בחי' התיקון כו', ונמצא כאשר מאיר בחי' אור הזה בתיקון ה\"ז תוס' מרובה על בחי' העיקר שהרי עיקר בחי' התיקון הנה הוא מיעוט האור ותוס' זה שנעשה ע\"י הקרבת הבהמה ע\"ג המזבח מתקרב ניצוץ דתהו שהוא מבחי' ריבוי אור דתהו שמלבד ריבוי האור הנה הוא אור נבדל בערך לגמרי מאורות דתהו<sup data-n=\"1392\">65</sup> אשר עי\"ז נמשך תוס' אור בש' הוי' שז\"ע נחוח להוי' ע\"י בחי' ריח שהוא בחי' ההעלאה<sup data-n=\"1393\">66</sup> שמתעלה הניצוץ שמזה נעשה בחי' ריח, ויובן זה למה נמשל לריח הוא מב' טעמים הא' כמו הריח הוא מקיף את האדם שנתעלף ונסתלק כרגע חיותו שהאיר להחיות גופו שב ופרח מאפיו ע\"י שנחלש או סיבה אחרת, הנה כשנותנים לו להריח ריח חזק חוזר הנפש להתפשט<sup data-n=\"1394\">67</sup> בגוף האדם להחיותו כמקדם קדמיתא, ולכאו' מי הוא אשר עוררו לשוב לבוא ולהתפשט בגוף האדם אלא שזהו מפני שהריח מעורר בשרש שרשו אשר משם לא נסתלק שהרי להמת לגמרי לא יוחזר נשמתו להחיותו ע\"י הריח שזה מפני שנסתלקה לגמרי, משא\"כ המתעלף עם היות שנפשו פסקה להחיותו בהתפשטות חיותה להיות העין רואה והאזן שומע ושארי איבריו פועלים פעולתם כמו בכל בנ\"א הבריאי', מ\"מ הנה היא בגידי ההרגש והלב חי רק שנתבטל פעולתה ברצו\"ש אמנם הי' חי עדיין חיות שלם כו', ולכן הריח שמגיע לעצם בחי' חיבור הגוף והנפש מעורר את הנפש ומחזק ההרגשה שישוב וירגיש חיותו כמו שהוא מקדם שנמצא מובן שהעלאת הריח הוא בעצם חיבור נפשו איך שהיא מקושרת בגוף בכלליותה שלמעלה מבחי'<sup data-n=\"1395\">68</sup> התפשטות בפרטי הכחות כו', והב' ממה שאמרו ריח הוא דבר שהנשמה נהנית<sup data-n=\"1396\">69</sup> ממנה ולא הגוף, שענין זה מורה על רוממות בחי' הריח שמתייחס להחיות בחי' רוחניות כמו נפש האדם, וא\"כ מובן שכאשר מבהמה גשמיות מתעלה להיות כלי לבחי' אורות מרובים דתהו א\"א לקרוא זה כ\"א בשם ריח לבד לרמז על שזהו מחי' הנפש שהוא בחי' רוחניות ועולה מעלה מעלה, וגם י\"ל שכמו הריח הוא מעורר הנפש לבוא להתפשט באברי הגוף, כן בחי' העלאה זו מעוררת אורות דתהו",[["1391","64","<b>קטן</b>: בהמשך יונתי הנדפס: קוטן."],["1392","65","<b>אור נבדל. . דתהו</b>: ראה גם לקמן בהקיצור כאן."],["1393","66","<b>נחוח. . ריח. . ההעלאה</b>: ראה סידור שחרית לג, ג. לו, ג. סה\"מ תרל\"ח ס\"ע לו. וש\"נ."],["1394","67","<b>ריח חזק חוזר הנפש להתפשט</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה עשה צדקה ומשפט על יד הערה 43. (בחלק ההנחות) בהנחה כאן על יד הערה 84. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370096\" data-slug=\"torah-or\" data-id=\"3901370096\">תו\"א תולדות כ, רע\"ד</a>. מג\"א קיז, ב. סה\"מ מלוקט ב' ע' רטז הערה 52."],["1395","68","<b>מבחי'</b>: בהמשך יונתי הנדפס: בחי'."],["1396","69","<b>ריח. . שהנשמה נהנית</b>: ראה ברכות מג, ב. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ח ובהערה 134."]]],[2000480197,"שנסתלקו שזהו עד\"מ כמו בשעת העילוף אשר מתעלף האדם שכחותיו משתנים להיות בבחי' עלי' ולא בבחי' ירידה, וכשם שפועל להשיב הנפש באדם שנתעלף כן פועלת להחזיר בחי' אור התהו שהי' בבחי' העלאה שישוב ויתפשט להתלבש להיות בבחי' אור וכלי, וכל העשייה הזאת הוא בתיקון שממילא מובן שכאשר נמשך המשכה רבה ועצומה כזו בבחי' התיקון ה\"ז תוס' אור שמרובה על העיקר, כי האור הוא בעצם מבחי' היותר גבוה, ולכן נק' נחוח לשון נחות דרגא<sup data-n=\"1397\">70</sup> שהרי הוא הגבה מאד נעלה מבחי' התיקון עד שהמשכתו בתיקון הוא ירידה והשפלה כו', ועפ\"ז יובן שרש ענין איך ע\"י הקרבת הבהמה &lt;50&gt;\nּ מתכפר נפש אדם החוטא, בהיות ידוע כי שרש ענין המחילה והסליחה נמשך מבחי' יגמה\"ר שארז\"ל ברית כרותה ליגמה\"ר<sup data-n=\"1398\">71</sup> שאינם חוזרות<sup data-n=\"1399\">72</sup> ריקם כו' שע\"י בחי' יגמה\"ר נמשך להיות נושא עון ועובר על פשע<sup data-n=\"1400\">73</sup> כו', ונודע כי יגמה\"ר הם ג\"כ מבחי' התיקון כו' שבכלל בתיקון הוא מיעוט האור, ועכ\"ז מחמת בחי' יגמה\"ר שם אם חטאת<sup data-n=\"1401\">74</sup> כו' ואם צדקת<sup data-n=\"1402\">75</sup> כו' ולכן נמשך סליחת עוונות, וכ\"ש כאשר נמשך ריבוי האור דתהו יומשך הסליחה כששב בכל לבו<sup data-n=\"1403\">76</sup> כו', ועכ\"ז אינו מועיל קרבן כ\"א על השוגג<sup data-n=\"1404\">77</sup> לבד, משא\"כ למזיד אינו מועיל קרבן כלל<sup data-n=\"1405\">78</sup> כ\"א דמב\"ד מועיל על המזיד<sup data-n=\"1406\">79</sup> ג\"כ כמשי\"ת לקמן ענינם<sup data-n=\"1407\">80</sup> כו', אבל עכ\"פ מובן איך על השוגג מועיל קרבן כו'.\n<b></b>קיצור. ריח ניחוח להוי' זהו מלבד בחי' השמחה הנפלאה הנ\"ל אלא שעי\"ז נעשה נחוח לשון נחות דרגא שנמשך מבחי' אורות דתהו שהם בריבוי, וגם אור נבדל בערך מבחי' אורות דתהו<sup data-n=\"1408\">81</sup>, וזהו ע\"י ההעלאה שלכן נק' ריח ונת' ג' טעמים ע\"ז, גם מה שמועיל קרבן זה מובן במכש\"כ מיגמה\"ר.",[["1397","70","<b>נחוח לשון נחות דרגא</b>: ראה יבמות סג, א. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פמ\"ב ובהערה 1312."],["1398","71","<b>ברית כרותה ליגמה\"ר</b>: ראה ר\"ה יז, ב. (לקמן בחלק ההנחות) הנחה ד\"ה הנה אנכי כורת עמך ברית הערה 63."],["1399","72","<b>חוזרות</b>: בהמשך יונתי הנדפס: חוזרי'."],["1400","73","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["1401","74","<b>אם חטאת</b>: איוב לה, ו."],["1402","75","<b>ואם צדקת</b>: איוב שם, ז [ושם: אם — ראה גם מאמרי אדה\"א נ\"ך ע' תמז. פלח הרמון בחוקותי ע' תעו. וש\"נ]."],["1403","76","<b>כששב בכל לבו</b>: ראה רמב\"ם הל' תשובה רפ\"א ואילך. פ\"ב, ה\"ב ואילך."],["1404","77","<b>קרבן כ\"א על השוגג</b>: ראה רמב\"ם הל' שגגות רפ\"א ואילך. אגה\"ק סוסכ\"ח."],["1405","78","<b>למזיד אינו מועיל קרבן כלל</b>: ראה רמב\"ם שם רפ\"ט. סה\"מ תרל\"ג ח\"א ע' קמט בשולי היריעה ובהנסמן שם. ע' קפג בשולי היריעה. ע' קצג<sup data-n=\"e141\">ו</sup> ובהערה 5. תרכ\"ט ע' שסא."],["1406","79","<b>דמב\"ד </b>[ ד' מיתות ב\"ד]<b> מועיל על המזיד</b>: ראה רמב\"ם הל' תשובה פ\"א, סה\"א."],["1407","80","<b>כמשי\"ת לקמן ענינם</b>: לפנינו ליתא."],["1408","81","<b>אור נבדל. . דתהו</b>: ראה גם לעיל על יד הערה 65.\n\n<b>ו</b>  נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200017\" data-slug=\"or-hatorah-hb\" data-id=\"8159200017\">אוה\"ת ויקרא כרך ג ס\"ע תשכט</a> ואילך (כמצויין בסה\"מ תרל\"ג בריש המאמר שם)."]]],[2000480198,"המשך ציוני העמודים להמשך הנדפס, נמצא להלן ע' תריב]",[]],[2000480199,"<h3>וכל שיח השדה כו'</h3>\n<b></b><b>בס\"ד ש\"פ בראשית מ\"א לפ\"ק</b>\n<b></b>בריחא דלבושייכי כו' השפעה חצונית, פנימית כו' נשמות ומלאכים מעלתם זע\"ז כו' אליהו\nבראשית\n<b>וכל</b> שיח השדה<sup data-n=\"1409\">1</sup> טרם יצמח<sup data-n=\"1410\">2</sup> וגו', ואדם אין לעבוד את האדמה, ובמד\"ר במקומו<sup data-n=\"1411\">3</sup> מובן שמפרש שיח לשון תפלה ע\"ד מ\"ש ויצא יצחק<sup data-n=\"1412\">4</sup> לשוח<sup data-n=\"1413\">5</sup> כו' ושדה מפרש על בהמ\"ק כמ\"ש ציון שדה<sup data-n=\"1414\">6</sup> תחרש<sup data-n=\"1415\">7</sup>, שכל שיחה דברייתא<sup data-n=\"1416\">8</sup> מרי מתי יתבני בית מקדשא, ואדם אין פי' שם<sup data-n=\"1417\">9</sup> ואדם אין כאליהו וחוני<sup data-n=\"1418\">10</sup> המעגל לעבוד את האדמה להעביד את הבריות להקב\"ה, וצ\"ל למה אלי' וחוני המעגל הלא היו כו\"כ צדיקים מופלגים כמו האבות ומרע\"ה, אך הענין דבאלי' כתי' הנה אנכי שולח לכם<sup data-n=\"1419\">11</sup> את אלי' כו' והשיב לב אבות על בנים<sup data-n=\"1420\">12</sup> ולב בנים על אבותם, אשר לכאורה יפלא למה",[["1409","1","<b>וכל שיח השדה</b>: בנידון מאמר זה כותב כ\"ק אדמו\"ר בס' התולדות של כ\"ק אדמו\"ר מהר\"ש (קה\"ת תש\"ז ע' 54): בריחא דלבושייכי כו' השפעה חצונית, פנימית כו' נשמות ומלאכים מעלתם זע\"ז כו' אליהו.\nמאמר זה כנראה מיוסד על מאמר ד\"ה זה מכ\"ק אדמו\"ר הצ\"צ שנמצא בבוך 1063 בתחלתו<sup data-n=\"e142\">א</sup> (וחסר סיום).\nהנחת<sup data-n=\"e143\">ב</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה<sup data-n=\"e144\">ג</sup> נדפסה לקמן (בחלק הנחותיו).\nבס' התולדות שם וכן בבוך זה 2208 בא מאמר זה בין הדרוש והוא כחתן להדרוש רני ושמחי. אמנם ע\"פ הכותרת שבהנחת כ\"ק אדמו\"ר מהורש\"ב סודר מאמר זה כאן.\nמאמר זה הודפס מכאן במאמרי אדמו\"ר מהר\"ש דרושי חתונה בתחלתו<sup data-n=\"e145\">ד</sup>."],["1410","2","<b>וכל שיח השדה טרם יצמח</b>: בראשית ב, ה [בדילוג]."],["1411","3","<b>ובמד\"ר במקומו</b>: ראה ב\"ר פי\"ג, ב."],["1412","4","<b>שיח לשון תפלה. . ויצא יצחק לשוח</b>: ראה מתנות כהונה לב\"ר שם."],["1413","5","<b>ויצא יצחק לשוח</b>: ח\"ש כד, סג. ראה גם מכילתא בשלח יד, י<sup data-n=\"e146\">ה</sup>. ברכות כו, ב. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541005\" data-slug=\"torat-chaim\" data-id=\"2300541005\">תו\"ח שמות ח\"א יז, ד</a>."],["1414","6","<b>ושדה. . בהמ\"ק. . ציון שדה תחרש</b>: ראה רש\"י ומת\"כ לב\"ר שם."],["1415","7","<b>ציון שדה תחרש</b>: ירמי' כו, יח."],["1416","8","<b>שכל שיחה דברייתא</b>: ועד\"ז מובא לקמן בההנחה כאן. ראה ב\"ר שם: כל תפלתן של ישראל."],["1417","9","<b>ואדם אין פי' שם</b>: ראה ב\"ר שם ס\"ז<sup data-n=\"e147\">ו</sup>."],["1418","10","<b>וחוני</b>: וכ\"ה בדרושי כ\"ק אדמו\"ר מהר\"ש דלעיל בשולי היריעה ו<sup data-n=\"e148\">ז</sup>. בב\"ר שם<sup data-n=\"e149\">ח</sup>: וכחוני."],["1419","11","<b>הנה אנכי שולח לכם</b>: מלאכי ג, כג."],["1420","12","<b>והשיב לב אבות על בנים</b>: מלאכי שם, כד.\n\n<b>א</b>  בוך זה הוא הנחות של ר' דוב [בעריל] קאליסקער ממאמרי כ\"ק אדמו\"ר הצ\"צ ונק' בשם ”בוך בש\"ו\" [בראשית שמות ויקרא]־ ולפעמים בשם ”ס' וכל שיח\" ע\"ש פתיחתו במאמר ד\"ה וכל שיח השדה. ראה עוד ע\"ד הנ\"ל ב”ספריית ליובאוויטש\" ע' ל ואילך. ע' לז ואילך.\n\n<b>ב</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>ג</b>  ומשם נעתקה הכותרת המופיעה בריש המאמר כאן פרט לתיבת בס\"ד.\n\n<b>ד</b>  ושם בהערה 1 נדפס: ונמצא. . בסה\"מ תרמ\"א. וצ\"ל: בסה\"מ תר\"ם.\n\n<b>ה</b>  וכן צ\"ל בתו\"ח שבפנים ההערה.\n\n<b>ו</b>  מובא גם באוה\"ת בראשית כרך ג ס\"ע 1034 ואילך. מלכים-א ע' עח. ירמי' ע' שנה. סה\"מ תרל\"ב ח\"א ע' קיא ואילך. ח\"ב ע' תקע. ע' תקעד. תרל\"ג ח\"א ע' קפה בשולי היריעה. המשך מים רבים תרל\"ו פק\"י. וככה תרל\"ז פס\"ה. תער\"ב ח\"ב ע' א'סז. ע' א'רג.\n\n<b>ז</b>  פרט להנחה בסה\"מ תרל\"ב ח\"ב ע' תקע.\n\n<b>ח</b>  וכ\"ה לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן (נדפסה בחלק ההנחותיו).\nושם נדפס: פי\"ו (וכנשצ\"ל פי\"ג). . כאליהו הנביא].\nושם: כאליהו הנביא.\nושם נדפס: פי\"ז — וכנשצ\"ל: פי\"ג."]]],[2000480200,"צריכים אלי' שישיב לב אבות כו' ולב בנים הלא אינם מרוחקים כ\"כ, שיצטרך אלי' לישר לבותם כו', ומשמע אשר בלעדו א\"ז ביכולת להשוות, וג\"ז לפני בא יום ה' הגדול והנורא<sup data-n=\"1421\">13</sup> כו'<sup data-n=\"1422\">14</sup> אשר כ\"ז א\"מ כלל, הנה בזהר פ' בלק<sup data-n=\"1423\">15</sup> הבין הינוקא כשראה את רי\"ה ור' יוסי<sup data-n=\"1424\">16</sup> א\"ל חמינא בריחא דלבושייכו דלא קריתון ק\"ש, והשיבו לו שעסקו במצות חו\"כ והעוסק במצוה פטור מן המצוה<sup data-n=\"1425\">17</sup>, וא\"כ צ\"ל שכשעוסק במצוה זו פטור מן מצוה אחרת לפי שע\"י עשיית מצוה זו נמשך גם מה שהי' נמשך ע\"י מצוה האחרת שהי' עושה כו', וא\"כ מאין הבין הינוקא שלא קראו ק\"ש הלא באמת היו פטורים מק\"ש כו', ויובן בהקדם מארז\"ל ביום חתונתו זו מ\"ת<sup data-n=\"1426\">18</sup>, שלכאורה א\"מ למה אמרו רז\"ל ודימו מ\"ת למשל גשמי כ\"כ, וגם מ\"ת הי' בקולות וברקים כו' וקול שופר<sup data-n=\"1427\">19</sup> חזק מאד, וירד ה' על ה\"ס<sup data-n=\"1428\">20</sup> שהי' גילוי עצמותו, ועכ\"ז א' דברים פשוטים לא תרצח לא תנאף לא תגנוב<sup data-n=\"1429\">21</sup>, שגם אלמלא לא ניתנה תורה<sup data-n=\"1430\">22</sup> מהראוי ע\"פ השכל שלא לעשותם, ולצורך ציווי דברים פשוטים כאלו ירד ה' עה\"ס<sup data-n=\"1431\">23</sup> כו', והענין הוא דהנה נודע שיש ב' בחי' השפעות<sup data-n=\"1432\">24</sup> הא' הוא הנק' השפעה חיצוני', והב' הוא בחי' השפעה פנימיות, וענין בחי' השפעה חיצוני' זהו ע\"ד כמו השפעת הרב לתלמידו שעם היות שמשפיע לו דבר שכל, עכ\"ז הוא רק בחי' השפעה חיצוני' לבד, והמופת לזה שהרי אם המקבל ההשפעה איננו בר שכל כלל לא יבין השפעת הרב כלל, ואם השפעת הרב הי' בחי' השפעה פנימיות שהי' משפיע לתלמידו בחי' שפע פנימי מעצמיות בחי' המוחין, הנה גם אם המקבל אין לו מוחין בעצם ה\"צ<sup data-n=\"1433\">*25</sup> ג\"כ שידע דבר ההלכה מאחר שהרב השפיע לו מעצמיות בחי' המוחין שלו, אלא מפני שהשפעת הרב היא רק השפעה חיצוני' לבד, ולכן אם המקבל יש לו מוחין אזי מבין בכח שכלו העצמי שפע הרב עד שבמשך ארבעים שנה קאים אדעתי' דרבי'<sup data-n=\"1434\">25</sup>, אם אין לו שכל אינו מבין כלל השפעת הרב מאחר שהיא רק השפעה חיצוני' לבד,",[["1421","13","<b>לפני בא. . והנורא</b>: המשך הכתוב הנה אנכי שולח [ושם: בוא] — מלאכי ג, כג."],["1422","14","<b>כו'</b>: סיום הכתוב הוא בתיבת והנורא."],["1423","15","<b>בזהר פ' בלק</b>: ראה שם קפו, א. לקמן פ\"ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540057\" data-slug=\"torat-chaim\" data-id=\"2300540057\">תו\"ח וארא ח\"א נט, ד</a>."],["1424","16","<b>רי\"ה ור' יוסי</b>: בזהר: ר' יצחק ור' יהודה. ראה גם לעיל מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 115."],["1425","17","<b>והעוסק במצוה פטור מן המצוה</b>: סוכה כה, א. ראה גם הנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261237\" data-slug=\"likkutei-sichot\" data-id=\"1300261237\">לקו\"ש תשא כרך כו ע' 237</a> הערה 64."],["1426","18","<b>ביום חתונתו זו מתן תורה</b>: תענית כו, ב (במשנה). ראה מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' לד. מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["1427","19","<b>מ\"ת הי' בקולות. . וקול שופר</b>: יתרו יט, טז."],["1428","20","<b>וירד ה' על ה\"ס</b>: יתרו שם, כ."],["1429","21","<b>לא תרצח לא תנאף לא תגנוב</b>: יתרו כ, יג."],["1430","22","<b>אלמלא לא ניתנה תורה</b>: ערובין ק, ב. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע הערה 13."],["1431","23","<b>ולצורך ציווי דברים פשוטים כאלו ירד ה' עה\"ס</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380358\" data-slug=\"likkutei-torah\" data-id=\"4001380358\">לקו\"ת במדבר יב, ג</a>. סה\"מ תרכ\"ט ס\"ע ריז ואילך. וש\"נ."],["1432","24","<b>ב' בחינות השפעות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381287\" data-slug=\"likkutei-torah\" data-id=\"4001381287\">לקו\"ת שה\"ש לט, ד</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' נז. מאמרי אדה\"א דרושי חתונה ח\"א ע' קה ואילך. וש\"נ. סהמ\"צ להצ\"צ ע' ג. בחלק מהנסמן בסמוך הערה 26."],["1433","*25","<b>ה\"צ</b>: הי' צריך."],["1434","25","<b>שבמשך ארבעים שנה קאים אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540728\" data-slug=\"torat-chaim\" data-id=\"2300540728\">תו\"ח בשלח ח\"א ריז, ג</a> הערה 418. המשך וככה תרל\"ז ספל\"ה. סה\"מ תרנ\"ב ע' צה."]]],[2000480201,"וכלשון המורגל „ ק פ קען מען ניט „רוף שטעלין<sup data-n=\"1435\">26</sup>, משא\"כ ביחוד דו\"נ שהטפה הנמשכת ממוח האב הוא בחי' שפע העצמי ולכן מוליד בדומה לו עם מוחין עד שיכול להיות שיהי' גם יפה כח הבן מכח האב<sup data-n=\"1436\">27</sup> כו' כמשנ\"ת מזה במ\"א, והוא מפני שהשפעה זו הוא בחי' השפעה פנימיות כו'.\n<b></b>קיצור. השפעת הרב לתלמידו הוא רק השפעה חיצוני', משא\"כ בחי' יחוד דו\"נ זהו השפעה פנימיות ולכן מוליד בדומה לו כו'.\nב) <b>ואמנם</b> עדיין אינו מובן מדוע השפעה חיצוני' שנשפע מרב לתלמידו שעם היות שהיא רק השפעה חיצוני' לבד עכ\"ז הנה היא נשפעת ברוחניות שז\"ע הבנת דבר שכל, ובחי' השפעה פנימיות שנמשך מבחי' עצמיות המוחין יומשך להיות כ\"כ בגשמיות עד שיתגשם בטפה גשמיות, ואז דוקא יוליד בדומה לו, ולכאורה הי' מהראוי הי'<sup data-n=\"1437\">28</sup> שיהי' בהיפך שהשפעת הרב מאחר שהוא רק השפעה חיצוני' ה\"צ להיות נמשך בבחי' גשמיות, ושפע העצמי הצ\"ל<sup data-n=\"1438\">29</sup> בחי' רוחני' לבד, ולא שיומשך בהגשמה כ\"כ, אלא שהיא הנותנת שלהיות בחי' המשכה פנימיות היא מבחי' עצמיות א\"א לבוא כ\"א בלבוש גשם דוקא, שכל מה שהוא במעלה יותר כשיורד לבוא למטה מוכרח להתלבש בלבוש יותר גשמי<sup data-n=\"1439\">30</sup> דוקא, ויובן זה מבחי' ארי' ושור שבמרכבה העליונה שהארי' הוא בבחי' היותר גבוה במעלה מבחי' שור<sup data-n=\"1440\">32</sup> שלכן פני ארי' הוא אל הימין<sup data-n=\"1441\">31</sup> ועכ\"ז בהתלבשותם למטה הנה ארי' הוא חי' טמאה הטורף ודורס<sup data-n=\"1442\">33</sup>, ושור הוא בהמה טהורה שמקריבין ממנה קרבן לה' שנעשה ריח ניחוח להוי'<sup data-n=\"1443\">34</sup>, וכמבואר בד\"ה ביום השמע\"צ<sup data-n=\"1444\">35</sup> שבד\"ה יונתי בחגוי הסלע, ולכאו' הי' ראוי להיות להיפך שהבהמה טהורה העולה לריח ניחוח להוי' תהי' שרשה מפני ארי', והטורף והדורס הטמא ישתלשל מפני שור, אלא דהיא הנותנת שלהיות הארי' גבוה במעלה א\"א שיבוא אפי' ע\"י ריבוי רבבות השתלשלות לבוא שיהי' ממנו בהמה",[["1435","26","<b>וכלשון המורגל א קאפ. . שטעלין</b>: מובא בכ\"מ ומהם — ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 23. סהמ\"צ להצ\"צ שם. ביאוה\"ז — להצ\"צ — ח\"ב ע' תריג. מאמר ד\"ה זה שבהערה 1. סה\"מ תרל\"ו ח\"ב ריש ע' רצד. תרנ\"ז ע' רסז. הגהות לד\"ה פתח אלי' תרנ\"ח ע' ל. סה\"מ תרנ\"ט ע' ג. המשך תרס\"ו ע' קעג. סה\"מ עת\"ר קפה. תרע\"ח ע' סד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301550234\" data-slug=\"likkutei-sichot\" data-id=\"1301550234\">לקו\"ש תבוא כרך לד ע' 163</a>."],["1436","27","<b>יפה כח הבן מכח האב</b>: ראה שבועות מח, סע\"א. מאמרי אדה\"ז תקס\"ט ע' קסח. סה\"מ תרל\"ב ח\"ב ע' תצה. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' ס. סה\"מ תרנ\"ז ע' רסט ואילך."],["1437","28","<b>הי'. . הי'</b>: כן הוא בהכת\"י."],["1438","29","<b>הצ\"ל</b>: הי' צריך להיות."],["1439","30","<b>שכל. . במעלה יותר כשיורד. . יותר גשמי</b>: ראה ש\"א שער הפורים נח, א. סה, א. סה\"מ תרל\"ח ע' תב. וש\"נ."],["1440","32","<b>שהארי'. . גבוה. . מבחי' שור</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה פ\"א."],["1441","31","<b>ארי' ושור שבמרכבה. . פני ארי'. . הימין</b>: יחזקאל א, י."],["1442","33","<b>ארי'. . ודורס</b>: ראה חולין מב, א (במשנה). שו\"ע יו\"ד סנ\"ז, ס\"א."],["1443","34","<b>ריח ניחוח להוי'</b>: ויקרא א, ט. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301490060\" data-slug=\"likkutei-sichot\" data-id=\"1301490060\">לקו\"ש ויקרא כרך לב ע' 1</a> ואילך."],["1444","35","<b>בד\"ה ביום השמע\"צ</b>: נדפס לעיל — ראה שם על יד הערה 9 ואילך."]]],[2000480202,"טהורה, כ\"א דוקא חי' טמאה<sup data-n=\"1445\">36</sup> הטורף ודורס וג\"ז ע\"י בחי' נפילה ושבירה כו', ועד\"ז יובן בענין בחי' השפעה עצמי' שלהיותה במעלה היותר גדולה א\"א שתבוא למטה כ\"א בבחי' הגשמה יותר כו'.\n<b>ויובן</b> זה עוד מענין מה שהמלאכים ביקשו התורה<sup data-n=\"1446\">37</sup> ולא ניתנה להם, והשיב להם כלום יצה\"ר יש ביניכם<sup data-n=\"1447\">38</sup>, ולכאו' א\"מ הלא המלאכים ביקשו התורה כמו שהיא למעלה שמצינו בדרז\"ל שגם למעלה לומדי' תורה כמארז\"ל קמיפלגי במתיבתא דרקיע<sup data-n=\"1448\">39</sup> אם בהרת כו' ספק כו' שלמעלה אינו שייך בהרת גשמי ושער לבן גשמי אלא שהלימוד הוא בבחי' רוחניות ההלכה<sup data-n=\"1449\">40</sup>, וא\"כ צ\"ל מהו שהשיבם כלום יצה\"ר יש ביניכם הלא לא בקשו התורה בגשמיות שיצטרכו לבוא בעוה\"ז הגשמי כ\"א כמו שהיא ברוחניות למעלה, ומ\"ע ליצה\"ר כו'. אך הענין בהיות כי שרש התו' בשרשה גבוה מאד נעלה ולזאת א\"א שתבוא בהתלבשות למטה כ\"א בדברים גשמי' ופשוטים כמו לא תרצח לא תנאף לא תגנוב וכדומה, ולכן השיב להמלאכים כלום יצה\"ר יש ביניכם שבאפשר לצוות אתכם על ציוויי' כנ\"ל, ועל כוונתם שינתן להם התו' כמו שהיא למעלה כו' א\"צ להשיב להם מפני שמובן ממילא שאור היותר נעלה א\"א לבא למטה בלבוש רוחני לבד, כ\"א כאשר ירדה להתלבש בלבוש גשמי וניתנה למטה לנשמות בגופים דוקא, ואז גם בצאת הנפש מן הגוף יכולה היא ללמוד בג\"ע רוחניות דבר ההלכה, וכמ\"ש במ\"א מענין זיו תורתן ועבודתן<sup data-n=\"1450\">41</sup> שמאיר בג\"ע, משא\"כ המלאכים מפני שהם רוחני' ולא ירדו להתלבש בגוף מד\"י<sup data-n=\"1451\">43</sup> כמו הנשמה (שזהו ג\"כ מפני שבשרשן נמשכים מזיווג רוחני לכן די להם ההלבשה דגוף רוחני שהוא רק מב\"י דאש רוח<sup data-n=\"1452\">44</sup> כמ\"ש עושה מלאכיו רוחות<sup data-n=\"1453\">45</sup> משרתיו אש לוהט כמ\"ש מזה במ\"א) ולכן א\"י לקבל התורה כ\"א שמקבלים מלימוד הנשמות כמ\"ש חבירים מקשיבים לקולך<sup data-n=\"1454\">46</sup> שקאי על המלאכים כמ\"ש מזה במ\"א. ולפ\"ז מובן מה שלצורך נתינת ציווי",[["1445","36","<b>הארי' גבוה במעלה. . חי' טמאה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה פ\"א. וש\"נ."],["1446","37","<b>שהמלאכים בקשו התורה</b>: שבת פח, ב."],["1447","38","<b>כלום יצה\"ר יש ביניכם</b>: ראה שם פט, א. מאמרי אדה\"א ויקרא ח\"ב ע' תסט בהערה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560193\" data-slug=\"or-hatorah-hb\" data-id=\"8316560193\">אוה\"ת בראשית כרך ג ע' תקסג</a>."],["1448","39","<b>קמיפלגי במתיבתא דרקיע</b>: ראה ב\"מ פו, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121064\" data-slug=\"likkutei-sichot\" data-id=\"1300121064\">לקו\"ש תזריע כרך יב ע' 64</a> ואילך ובהנסמן שם."],["1449","40","<b>שלמעלה. . שהלימוד. . רוחניות ההלכה</b>: ראה גם לקו\"ת ואתחנן ו, ב ואילך. סהמ\"צ להצ\"צ ע' 334. סה\"מ תרל\"ח ע' קמו ובהערה 840."],["1450","41","<b>זיו תורתן ועבודתן</b>: ראה גם בענין זיו תורתן ועבודתן <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380317\" data-slug=\"likkutei-torah\" data-id=\"4001380317\">לקו\"ת במדבר ב, ב</a>. סה\"מ תרל\"ח ע' קמו ואילך. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 41."],["1451","43","<b>בגוף מד\"י</b>: רמב\"ם הל' יסוה\"ת רפ\"ד."],["1452","44","<b>מב\"י אש רוח</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370015\" data-slug=\"torah-or\" data-id=\"3901370015\">תו\"א בראשית ד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380253\" data-slug=\"likkutei-torah\" data-id=\"4001380253\">לקו\"ת בהר מא, ב</a>. מאמרי אדה\"א בראשית ע' קיב. וש\"נ. קונטרסים ע' רצב (ושם: אמ\"ר). וש\"נ. שע\"ת ו, ב. סה\"מ תרל\"ח ע' סד. וש\"נ. לעיל בח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 18."],["1453","45","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד."],["1454","46","<b>חבירים מקשיבים לקולך</b>: שה\"ש ח, יג. ראה שהש\"ר שם. זהר ויקרא כב, א. סה\"מ תרל\"ח ע' קמו ואלך. ע' ריט."]]],[2000480203,"דברים פשוטים כאלו ירד ה' באש בקולות וברקים, שהיא הנותנת שלהיות המשכה זו דמ\"ת היא בחי' השפעה עצמיות דוקא לכן א\"א שיתלבש כ\"א בדברים פשוטים כאלו כו'. ומטעם זה עצמו המשילו רז\"ל מ\"ת לחתונה שאמרו ביום חתונתו זו מ\"ת שעם היותו משל גשמי מאד עכ\"ז זהו משל אמיתי שהמשכת הטפה היא בחי' המשכה עצמיות כו', והתו' ניתנה לנשמות דוקא להיות כי שרש נשמות הוא מיחוד גופני<sup data-n=\"1455\">42</sup> דזו\"נ לכן יכולים לבוא בהתלבשות גוף גשמי ודוקא בגוף גשמי כו' לעוצם רוממותם שהם בחי' המשכה עצמי', ולהם ניתנה תור' שהיא ג\"כ בחי' המשכה עצמיות כו'.\n<b></b>קיצור. מדוע השפעה חיצוני' היא ברוחניות, ועצמיות בגשמיות לפי שכ\"ד היותר גבוה א\"א לבוא בהלבשה כ\"א בדבר היותר נמוך בהשתלשלות כו'. ע\"ד ארי' שנתלבש בחי' טמאה בדרך נפילה ושבירה, וכן התו' שהיא השפעה עצמיות ניתנה למטה דוקא ולא למלאכים שהם רוחני' כו'.\nג) <b>ולפ\"ז</b> מעלת הנשמות גדלה יותר על המלאכים, ועכ\"ז יש במלאכים ג\"כ בחי' יותר גבוה מנשמות, והוא שעם היות שרשן רק מזיווג חיצוני עכ\"ז הוא זיווג חיצוני דחו\"ב, ונת' במ\"א שבחי' חיצוני' שבאו\"מ הוא גבוה יותר מבחי' פנימיות שבאו\"פ<sup data-n=\"1456\">47</sup> כו', ועד\"ז יובן שבחי' זיווג חיצוני דחו\"ב יש בו ג\"כ יתרון מעלה על בחי' זיווג פנימי דזו\"נ כו'. ויש להביא ראיה לזה ממה שארז\"ל במשנה ספ\"ב דב\"מ אבידת אביו<sup data-n=\"1457\">48</sup> ואבידת רבו של רבו קודמת שאביו הביאו לחיי העוה\"ז, ורבו שלמדו חכ' הביאו לחיי העוה\"ב, ונת\"ל שהטיפה הנמשכת ממוח האב זהו בחי' שפע הפנימי בחי' שפע העצמי כו', והשפעת הרב לתלמידו זהו בחי' השפעה חיצוני', ומ\"מ אבידת רבו קודמת לפי שהשפעה חיצוני' מבחי' היותר נעלה גדול יותר מבחי' שפע הפנימי שלמטה הימנו כו', ועד\"ז המלאכים ששרשן מזיווג חיצוני' דחו\"ב יש בהם מעלה יתירה על הנשמות ששרשם מיחוד פנימי דזו\"נ כו'.\n<b>ויובן</b> זה עוד ממארז\"ל במד\"ר יפה שיחתן<sup data-n=\"1458\">49</sup> של עבדי בתי אבות מתורתן של בנים, ולכאו' הלא בנים זהו מ\"ש בנים אתם להוי' אלקיכם הוא בחי' יחוד פנימי דזו\"נ<sup data-n=\"1459\">50</sup>, ותורה היא ג\"כ המשכה פנימיות כנ\"ל בענין ביום חתונתו, ועכ\"ז יפה שיחתן שהוא בחי' הארה חיצוני' כמו שיחת חולין, ועם היות ששיחת חולין",[["1455","42","<b>המלאכים. . מזיווג רוחני. . נשמות הוא מיחוד גופני</b>: ראה ע\"ח שער מ\"ן ומ\"ד של\"ח, דרוש ד. שער פנימיות וחיצוניות ש\"מ, דרוש י."],["1456","47","<b>חיצוני' שבאו\"מ. . פנימיות שבאו\"פ</b>: ראה גם ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ד (קרוב לסופו). ראה גם מאמרי אדה\"ז תקס\"ד ע' קכו<sup data-n=\"e150\">ט</sup>. סה\"מ תרל\"ג ח\"א ע' רסד בשולי היריעהט. לקמן הערה 56."],["1457","48","<b>במשנה ספ\"ב דב\"מ אבידת אביו</b>: ראה שם לג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380098\" data-slug=\"likkutei-torah\" data-id=\"4001380098\">לקו\"ת ויקרא ו, רע\"א</a>. המשך מים רבים תרל\"ו פקפ\"ט. וראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 58. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי הענן והחשך על יד הערה 28."],["1458","49","<b>במד\"ר יפה שיחתן</b>: ב\"ר פ\"ס, ח."],["1459","50","<b>בנים אתם להוי' אלקיכם. . דזו\"נ</b>: פ' ראה יד, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380154\" data-slug=\"likkutei-torah\" data-id=\"4001380154\">לקו\"ת שמיני יט, א</a>. סה\"מ תרל\"ג ח\"ב ע' תעא.\n\n<b>ט</b>  בשם הבעש\"ט והמגיד."]]],[2000480204,"של ת\"ח צריכין לימוד<sup data-n=\"1460\">51</sup> שיש בהם ג\"כ חכ' עכ\"ז השיחת חולין זהו הארה חיצוני' ולא יותר מהשפעת הרב לתלמידו, ועכ\"ז יפה שיחתן כו' אלא מפני שהם עבדי בתי אבות, אבות זהו כמו שא\"א<sup data-n=\"1461\">52</sup> אלקינו ואלקי אבותינו חו\"ב<sup data-n=\"1462\">53</sup>, או כמ\"ש בעבר הנהר ישבו אבותיכם שהם בחי' חג\"ת דא\"א<sup data-n=\"1463\">54</sup>, ומפני שזהו מדריגה היותר גבוה לכן גם השיחה מבחי' זו הוא יותר נעלה מפנימיות השפע דזו\"נ, ועד\"ז יובן ג\"כ במלאכים ונשמות כו'. ובכ\"ז יובן מה שהבין הינוקא שא' חמינא בריחא דלבושייכו דלא קריתון ק\"ש, שעם היות שהעוסק במצוה פטור מן המצוה והם עסקו בשמחת חו\"כ שהוא זיווג גופני להוליד בדומה לו שהוא בחי' השפעה עצמיות, ולכן היו פטורים מק\"ש שהוא יחוד חיצוני דחו\"ב, עכ\"ז אמר חמינא בריחא דלבושייכו היינו בהעלאת הריח מן לבושי המצות<sup data-n=\"1464\">55</sup>, דלא קריתון ק\"ש שעם היות שע\"י הק\"ש נמשך רק בחי' יחוד חיצוני לבד עכ\"ז הוא יחוד חיצוני דחו\"ב כו', ובחי' חיצוניות שבעליון גבוה מבחי' הפנימיות שבתחתון<sup data-n=\"1465\">56</sup> כו'. ובזה יובן ג\"כ שרש ההבדל בין מלאכים לנשמות שהנשמות הם מבחי' זיווג גופני דזו\"נ, והמלאכים מזיווג רוחני דחו\"ב, ולכן עם היות שיש יתרון לנשמות על המלאכים במה שהם מבחי' הפנימיות ועצמיות יותר, עכ\"ז יש יתרון גם למלאכים שהם מבחי' היותר גבוה רק שהוא בחי' הארה חיצוניות לבד, והיא הנותנת שהנשמות נתלבשו בגופים מד\"י וירדו לברר הנה\"ב והגוף מפני שבשרשם הם מבחי' העצמיות כו', והמלאכים מפני כי שרשם הוא רק מבחי' חיצוני' לבד לכן הגם כי נתלבשו ג\"כ בגופים מב\"י אש ורוח כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט עכ\"ז נשארו בבחי' הרוחניות לבד, ונמצא כי יש מעלה בנשמות שהם מבחי' הפנימיות, ויש מעלה במלאכים שהם בבחי' הרוחניות רק ששרשם הוא מבחי' החיצוני' לבד, ועכ\"ז חיצוני' שבעליון גבוה מבחי' הפנימיות שבתחתון, וע\"ד שמצינו שחיצוני' שבמקיף גבוה מבחי' הפנימיות שבאו\"פ.\n<b></b>קיצור. שיש מעלה בנשמות שהם מבחי' הפנימיות, ויש מעלה במלאכים שהם חיצוני' מבחי' הגבוה יותר, וע\"ד יפה שיחתן כו' מתורתן כו' ואבידת רבו קודמת לאבידת אביו כו'.",[["1460","51","<b>ששיחת חולין. . לימוד</b>: סוכה כא, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380863\" data-slug=\"likkutei-torah\" data-id=\"4001380863\">לקו\"ת תצא לו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380866\" data-slug=\"likkutei-torah\" data-id=\"4001380866\">לז, ב</a>. מאמרי אדה\"א דברים ח\"א ע' ריז. וש\"נ. ח\"ד ע' א'ריט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670071\" data-slug=\"torat-chaim\" data-id=\"2300670071\">תו\"ח בראשית א, ד</a> ובהערה 54."],["1461","52","<b>שא\"א</b>: שאנו אומרים — בברכות ותפלת השחר וכו'. באוה\"ת ואתחנן שבהערה הבאה בשמ\"ע."],["1462","53","<b>אלקינו ואלקי אבותינו חו\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370082\" data-slug=\"torah-or\" data-id=\"3901370082\">תו\"א תולדות יז, סע\"ב</a>. מאמרי אדה\"ז תקס\"ח ח\"א ע' תקטז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680041\" data-slug=\"torat-chaim\" data-id=\"2300680041\">תו\"ח תולדות קמב, ב</a>. אוה\"ת תולדות כרך ד ע' 1612 ואילך. וש\"נ. ע' 1626. וש\"נ. ואתחנן כרך ו ע' ב'רסד. וש\"נ. וראה גם פלח הרמון תולדות עו, ב."],["1463","54","<b>בעבר הנהר. . חג\"ת דא\"א</b>: יהושע כד, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380278\" data-slug=\"likkutei-torah\" data-id=\"4001380278\">לקו\"ת בחוקותי מז, א</a>."],["1464","55","<b>הריח מן לבושי המצות</b>: ראה גם לעיל מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 110 ואילך."],["1465","56","<b>חיצוניות שבעליון גבוה מבחי' הפנימיות שבתחתון</b>: ראה גם לעיל הערה 47. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה משה קבל תורה מסיני ובהערה 13."]]],[2000480205,"ד) <b>ובכ\"ז</b> יובן מ\"ש באליהו והשיב לב אבות על בנים כו', שלכאורה מהו השבח בזה כ\"כ, אלא שאב הוא בחי' חכ', ובן הוא ז\"א, ויש יתרון המעלה ביחוד זו\"נ שהוא בחי' שפע העצמי בבחי' הפנימי' כו', ויש יתרון המעלה גם ביחוד חיצוני' דחו\"ב שהגם שהוא בחי' חיצוני' עכ\"ז היא נעלה יותר מבחי' הפנימיות דזו\"נ שלמטה מהם כו', וביאת אלי' יהי' להשיב לב אבות על בנים שגם בבנים יחוד זו\"נ יהי' גם מעלת יחוד חיצוני דאו\"א, ולב בנים על אבותם שגם בחו\"ב יהי' נמשך בחי' שפע העצמי ויחוד פנימי דחו\"ב, ואז יהי' רוחנים כמלאכים ועכ\"ז יומשך למטה כו', ובחי' זו שייך לאליהו דוקא מפני שהוא הי' תחלה נשמה בגוף, ונזדכך גופו<sup data-n=\"1466\">57</sup> לעלות למעלה להיות מלאך, וכמארז\"ל אלי' בארבע<sup data-n=\"1467\">58</sup>, לכן ביכולתו להשיב לב אבות על בנים ולב בנים על אבותם, וזהו ואדם אין כאלי' כו', והענין כי באלי' סופו מוכיח על תחילתו שכאשר נזדכך ועלה בסערה השמים להיות מלאך מוכרח לומר שגם בהיותו נשמה מלובש בגוף הי' ג\"כ מזוכך יותר (וכנודע שהי' בעיבור יב\"ח<sup data-n=\"1468\">59</sup> ), וזהו ואדם אין כאלי' שאלי' גם בהיותו ע\"פ האדמה הי' ג\"כ אדם מבחי' אין<sup data-n=\"1469\">60</sup>, וכן חוני המעגל כל מה שביקש פעל כמארז\"ל במשנה דתענית<sup data-n=\"1470\">61</sup>, ושניהם פעלו בענין המטר<sup data-n=\"1471\">62</sup> כרצונם כו'. וזהו וכל שיח השדה כל שיחה דברייתא מרי מתי יתבני כו', והוא מפני שאדם אין כאלי' וחוני כו' לעבוד את הבריות להקב\"ה שאם הי' אדם כאלי' כו' הי' כבר נבנה, ומפני שאדם אין לכן שיחה דברייתא מתי יתבני כו' וכמו שא\"א עכשיו יהי רצון כו' שיבנה בהמ\"ק בב\"א<sup data-n=\"1472\">63</sup>.\n<b></b>קיצור. להיות לב אבות כו' ולב בנים כו' ב' המעלות יחד זה יהי' ע\"י אלי' שהי' נשמה בגוף ונזדכך להיות מלאך, ולכן מוכרח לומר שגם קודם הי' בבחי' הביטול יותר וזהו ואדם אין שהי' אדם מבחי' אין כו', ומפני שאדם אין לכן וכל שיח הוא בבחי' שדה יהי רצון כו' שיבנה בהמ\"ק בב\"א.",[["1466","57","<b>לאליהו. . ונזדכך גופו. . בסערה השמים</b>: ראה מלכים-ב ב, יא. פרדס שער היכלות שכ\"ד, פי\"ג. פי\"ד. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 157."],["1467","58","<b>אלי' בארבע</b>: ברכות ד, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370023\" data-slug=\"torah-or\" data-id=\"3901370023\">תו\"א בראשית ו, ב</a>. סה\"מ תרל\"ח ע' צב. וש\"נ."],["1468","59","<b>באלי'. . בעיבור יב\"ח</b>: ראה גם לעיל מאמר ד\"ה כנשר יעיר ובהערה 16."],["1469","60","<b>שאלי'. . מבחי' אין</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 68."],["1470","61","<b>חוני המעגל. . במשנה דתענית</b>: יט, א."],["1471","62","<b>ושניהם פעלו בענין המטר</b>: אליהו — מלכים-א יז, א. פי\"ח. חוני — תענית שם."],["1472","63","<b>שא\"א עכשיו יהי רצון. . בב\"א</b>: ראה שינויי נוסחאות לאבות פ\"ה, מ\"כ שכ\"ה במחזור וויטרי. ראה גם סידור אדה\"ז שם. סיום איזהו מקומן־ תפלת העמידה. ותיבת אמן הוא כנראה הוספת כ\"ק אדמו\"ר מהר\"ש."]]],[2000480206,"<h3>והוא כחתן כו'</h3>\n<b></b><b>בס\"ד אור ליום ד' פ' נח על חתונת רמ\"מ תרמ\"א לפ\"ק</b>\nישיש ב' פעמים יש\nאור ליום ד' פ' נח\n<b>והוא</b> כחתן<sup data-n=\"1473\">1</sup> כו'<sup data-n=\"1474\">2</sup> ישיש<sup data-n=\"1475\">4</sup>, ב\"פ יש, תר\"ך<sup data-n=\"1476\">*4</sup> כתר<sup data-n=\"1477\">3</sup><sup data-n=\"1478\">5</sup> וצ\"ל מ\"ע ישיש לחתן שמשמע ששש בעצמו ומשיש לאחרים<sup data-n=\"1479\">6</sup> ג\"כ, ולכאורה מצינו בדרז\"ל ואם משמחו מה שכרו זוכה לתורה שניתנה בה' קולות<sup data-n=\"1480\">8</sup>, שצריך לשמח את החתן וכל הנהנה<sup data-n=\"1481\">7</sup> כו' ואינו משמחו כו', וכן מברכי' שוש תשיש כו'<sup data-n=\"1482\">9</sup> משמח חו\"כ.\n<b>הנה</b> כתיב קנה חכ' ובכל קניניך<sup data-n=\"1483\">10</sup> קנה בינה, ב\"פ קנה גימ' יש<sup data-n=\"1484\">11</sup>, ובחי' חו\"ב זהו\"ע תושב\"כ ותושבע\"פ<sup data-n=\"1485\">12</sup>, והם בחי' חו\"כ<sup data-n=\"1486\">13</sup>, וע\"י תושב\"כ ותושבע\"פ ממשיכים",[["1473","1","<b>והוא כחתן</b>: אודות מאמר זה רשם כ\"ק אדמו\"ר בס' התולדות של כ\"ק אדמו\"ר מהר\"ש (קה\"ת תש\"ז ע' 54): והוא כחתן כו' ישיש ב\"פ יש. התחלת דרוש ולנ\"ג [ ולא נגמר].\nלמאמר זה ראה גם מאמר ד\"ה זה בסה\"מ תרל\"ד ע' כז ואילך וש\"נ. בשינויים והוספות וכו'.\nהנחת<sup data-n=\"e151\">א</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה<sup data-n=\"e152\">ב</sup> נדפסה לקמן בחלק הנחותיו.\nבס' התולדות שם וכן בבוך מס. 2208 נרשם מאמר זה בין הדרושים עטרת תפארת שיבה וכל שיח השדה. אמנם ע\"פ הכותרת שבהנחת כ\"ק אדמו\"ר מהורש\"ב סודר מאמר זה כאן.\nלע\"ע לא נתברר מיהו הרמ\"מ.\nמאמר זה הודפס מכאן במאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' כה."],["1474","2","<b>והוא כחתן כו'</b>: תהלים יט, ו."],["1475","4","<b>ישיש ב\"פ יש</b>: ראה גם אוה\"ת בהעלותך ע' שמח. לעיל ח\"א (בהנחת כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 76."],["1476","*4","<b>ישיש. . תר\"ך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450580\" data-slug=\"or-hatorah-hb\" data-id=\"8316450580\">אוה\"ת חנוכה כרך ב' ע' 580</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650128\" data-slug=\"or-hatorah-hb\" data-id=\"8316650128\">כרך ה' ע' תתקלד<sup data-n=\"e153\">ג</a></sup>. ישעי' כרך ב' ע' תתנז. ע' תתסח."],["1477","3","<b>ישיש. . כתר</b>: ראה מאו\"א מערכת ישיש סל\"ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640065\" data-slug=\"or-hatorah-hb\" data-id=\"8316640065\">אוה\"ת</a> (יהל אור) תהלים ע' סה (ס\"ד). שה\"ש ח\"א ע' כו. סה\"מ תרל\"ג ח\"א ע' רסא. תרל\"ד ע' כו. תרנ\"ז ע' רצז. המשך תער\"ב ח\"א ע' רכ. סה\"מ תש\"ז ע' 152."],["1478","5","<b>תר\"ך כתר</b>: ראה ע\"ח שער ז\"א שי\"ז, ספ\"א. מאמרי אדה\"א דברים ח\"ד ע' א'רצט. וש\"נ."],["1479","6","<b>ישיש. . בעצמו ומשיש לאחרים</b>: ראה של\"ה לוחות הברית רסו, ב. הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670139\" data-slug=\"or-hatorah-hb\" data-id=\"8158670139\">אוה\"ת</a> ישעי' רצא, סע\"א."],["1480","8","<b>לתורה שניתנה בה' קולות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370330\" data-slug=\"torah-or\" data-id=\"3901370330\">תו\"א יתרו עד, ג</a>. מאמרי אדה\"ז על מארז\"ל ע' א. מאמרי אדה\"א דברים ח\"ב ע' תב. וש\"נ. לקו\"ש שם ואילך. וש\"נ."],["1481","7","<b>ואם משמחו. . וכל הנהנה</b>: ראה ברכות ו, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061118\" data-slug=\"likkutei-sichot\" data-id=\"1300061118\">לקוטי שיחות כרך ו' ע' 107</a> ואילך."],["1482","9","<b>שוש תשיש כו'</b>: ברכת נשואין. כנראה הכוונה בתיבת כו' לברכת שמח תשמח ששם הסיום (המובא כאן בפנים) משמח חו\"כ."],["1483","10","<b>קנה חכ' ובכל קניניך</b>: משלי ד, ז [ושם: קנינך. אבל כ\"ה גם בסה\"מ תרל\"ד כאן]."],["1484","11","<b>ב\"פ קנה גימ' יש</b>: ראה פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ג [ירושלים תש\"מ תקעא, סע\"א]. שער יוה\"כ שכ\"ז, פ\"ה. שער הפסוקים משלי ס\"ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרס. תקע\"א ע' עה. מאמרי אדה\"א דברים ח\"א ע' טז. וש\"נ. אוה\"ת בהעלותך ע' תטז."],["1485","12","<b>חו\"ב זהו\"ע תושב\"כ ותושבע\"פ</b>: ראה זח\"ב תוספות רעו, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670202\" data-slug=\"torat-chaim\" data-id=\"2300670202\">תו\"ח בראשית לו, ג</a> ובהערה 37. בא ח\"א צד, ד. וש\"נ."],["1486","13","<b>תושב\"כ ותושבע\"פ. . חו\"כ</b>: ראה גם ערכי הכנויים לבעל סדה\"ד מערכת חתן. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 570.\n\n<b>א</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>ב</b>  ומשם נעתקה הכותרת המופיעה בריש המאמר פרט לתיבת בס\"ד.\n\n<b>ג</b>  ראה ספר הליקוטים דא\"ח ”צמח צדק\" מערכת זקנה ע' רמח בהערה."]]],[2000480207,"להנחיל אוהבי יש<sup data-n=\"1487\">14</sup>. והענין כי אל דיעות ד\"ת וד\"ע<sup data-n=\"1488\">15</sup>, ד\"ת שלמטה היש, וד\"ע שלמעלה היש וכשנמשך בחי' ד\"ע בד\"ת שגם למטה יושג בחי' יש האמיתי ז\"ע להנחיל אוהבי יש, וזהו עדיין מחצה התחתון מתר\"ך מכתר, אך ישיש זהו ב\"פ יש כל התר\"ך. ויובן בהקדם מארז\"ל נש\"ב נבראו<sup data-n=\"1489\">16</sup>, ומשה ג\"כ לא השיג כ\"א מ\"ט<sup data-n=\"1490\">17</sup>, מעט מאלקים<sup data-n=\"1491\">18</sup> דבינה<sup data-n=\"1492\">19</sup>, שהנ' א\"א להשיג, נפלאות נ' פלאות<sup data-n=\"1493\">20</sup>, והראי' מספה\"ע מ\"ט יום ואז יאיר שעה\"נ<sup data-n=\"1494\">21</sup> ממילא, וכן בתו' כתיב מזוקק שבעתים<sup data-n=\"1495\">22</sup> זפ\"ז מ\"ט לבד שז\"ע מט\"פ טהור ומט\"פ טמא<sup data-n=\"1496\">23</sup>, אבל שעה\"נ א\"א לבוא בהשגה, ורק משה שזכה לבינה<sup data-n=\"1497\">24</sup> בעת הסתלקותו זכה לשעה\"נ<sup data-n=\"1498\">25</sup>, ולכן לעליונים נדמה למטה<sup data-n=\"1499\">26</sup> ולתחתונים למעלה כו' כמ\"ש במ\"א, ע' ביאור שבתותי<sup data-n=\"1500\">27</sup> ובד\"ה ויכל אלקים ביום השביעי<sup data-n=\"1501\">28</sup>, וכמו שבבינה יש שעה\"נ שאינו מושג כן בחכ'<sup data-n=\"1502\">29</sup> יש נתיב שא\"א לבוא לידי גילוי, וכמ\"ש ויקרא לו אל אלקי ישראל<sup data-n=\"1503\">30</sup> ל\"א נתי'<sup data-n=\"1504\">31</sup> וכ\"א כלול מיו\"ד ש\"י<sup data-n=\"1505\">32</sup> בחי' מה שעתיד להנחיל כו'",[["1487","14","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1488","15","<b>כי אל דיעות</b>: שמואל-א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a> ובהערה 11. סה\"מ תרל\"ד כאן ע' כח."],["1489","16","<b>נש\"ב נבראו</b>: ר\"ה כא, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם פ\"ב ובהערה 17."],["1490","17","<b>ומשה. . השיג. . מ\"ט</b>: ראה ר\"ה שם."],["1491","18","<b>מעט מאלקים</b>: תהלים ח, ו. ראה מאמרי אדה\"א במדבר ח\"ב ע' תלד."],["1492","19","<b>מאלקים דבינה</b>: ראה זהר בהקדמה ב, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670104\" data-slug=\"torat-chaim\" data-id=\"2300670104\">תו\"ח בראשית ח, ב</a> ובהערה 35."],["1493","20","<b>נפלאות נ' פלאות</b>: זח\"א בהשמטות רסא, ב. ז\"ח ס\"ת בראשית א, ב."],["1494","21","<b>מספה\"ע מ\"ט יום ואז יאיר שעה\"נ</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380348\" data-slug=\"likkutei-torah\" data-id=\"4001380348\">לקו\"ת במדבר י, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380356\" data-slug=\"likkutei-torah\" data-id=\"4001380356\">ד. יב, א</a> ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתקיט ואילך. מאמרי אדה\"א במדבר ח\"ב ע' שכ ואילך. ע' שצו ואילך. וש\"נ. ע' תכה. סה\"מ תרל\"ד כאן ע' כח. (לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 21."],["1495","22","<b>בתו' כתיב מזוקק שבעתים</b>: תהלים יב, ז. ירושלמי סנהדרין פ\"ד, ה\"ב."],["1496","23","<b>מט\"פ טהור ומט\"פ טמא</b>: ראה ירושלמי סנהדרין שם. פס\"ר פ' דעשה\"ד פכ\"א, ו. מאמרי אדה\"א במדבר ח\"א ע' רנ. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670426\" data-slug=\"torat-chaim\" data-id=\"2300670426\">תו\"ח בראשית יד, ג</a> ובהערה 40."],["1497","24","<b>משה שזכה לבינה</b>: ראה ר\"ה כא, ב. מאמרי אדה\"ז תקס\"ח ח\"א ע' קפה. שעה\"י קי, א."],["1498","25","<b>משה. . הסתלקותו זכה לשעה\"נ</b>: ראה לקו\"ת וס' הליקוטים להאריז\"ל ואתחנן ג, כו. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 350."],["1499","26","<b>לעליונים נדמה למטה</b>: ראה סוטה יד, רע\"א. מאמרי אדה\"ז תקס\"ה ח\"א ע' קפד־ <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380356\" data-slug=\"likkutei-torah\" data-id=\"4001380356\">לקו\"ת במדבר יב, א</a> ואילך (בשם המגיד)."],["1500","27","<b>ביאור שבתותי</b>: השווה גם לעיל מאמר ד\"ה וזהו שרש ענין יונתי ובהערה 95<sup data-n=\"e154\">ד</sup>. סה\"מ תרל\"ב ח\"ב ע' תקנב<sup data-n=\"e155\">ה</sup>."],["1501","28","<b>ובד\"ה ויכל אלקים ביום השביעי</b>: השווה גם לעיל מאמר ד\"ה וזהו שרש ענין יונתי על יד הערה 94<sup data-n=\"e156\">ו</sup>."],["1502","29","<b>וכמו שבבינה. . כן בחכ'</b>: ראה גם לעיל שם ובהערה 88."],["1503","30","<b>ויקרא לו אל אלקי ישראל</b>: וישלח לג, כ."],["1504","31","<b>אל. . ל\"א נתי'</b>: ראה גם לעיל מאמר ד\"ה וזהו שרש ענין יונתי ובהערה 91."],["1505","32","<b>ל\"א נתי' וכ\"א כלול מיו\"ד ש\"י</b>: ראה גם אוה\"ת בהעלותך ס\"ע תיט. סה\"מ תרל\"ח ע' קצד. וש\"נ. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' סג. (לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 33.\n\n<b>ד</b>  ושם: ובד\"ה את שבתותי תשמרו שלא נדפס ובהגהות לשם.\n\n<b>ה</b>  ושם: בד\"ה את שבתותי דתפילין.\n\n<b>ו</b>  ושם: בד\"ה ויכל אלקים רכ\"ב."]]],[2000480208,"ש\"י עולמות<sup data-n=\"1506\">33</sup>, אבל נתיב הל\"ב הוא פלא לגמרי, ועז\"נ נתיב לא ידעו עיט<sup data-n=\"1507\">34</sup> ולא שזפתו עין אי', שגם המלאכים שאומרים אי' מקום כבודו<sup data-n=\"1508\">35</sup> אינם יודעים נתיב הל\"ב, ועל בחי' נתיב זה הוא שאמרו שפנימיות אבא<sup data-n=\"1509\">36</sup> הוא פנימיות ע\"י<sup data-n=\"1510\">37</sup>, וכן מה שאמרו שהתגלות עתיק הוא בבינה<sup data-n=\"1511\">38</sup> הוא בבחי' שעה\"נ, וזהו שרש ענין ישיש ב\"פ יש היינו גם מחצה העליון דכתר.\n<b>והנה</b> כשהחתן יוצא מחופתו יוכל לבוא לבחי' ישיש, ב\"פ יש. והענין יובן בב' דרכים הא' ע\"פ מארז\"ל הנ\"ל ואם משמחו כו', שצריכים לשמח החתן שלכאורה א\"מ למה צריכים לשמחו, אך הענין דכתיב ע\"כ יעזב<sup data-n=\"1512\">39</sup> כו' ועל עזיבה זו צריכים לשמחו, חתן הוא בחי' תושב\"כ, וחתן חות דרגא<sup data-n=\"1513\">40</sup> ע\"ש שעוזב או\"א חו\"ב<sup data-n=\"1514\">41</sup> היינו בחי' הבן בחכ'<sup data-n=\"1515\">42</sup>, ויורד להשפיע בתושבע\"פ מל'<sup data-n=\"1516\">43</sup>, וגם על הבינה יש לפרש כן, ולכן צריכים לשמחו על ירידתו, ובמה משמחים אותו שירידה זו היא צורך עלי'<sup data-n=\"1517\">44</sup> גדולה דכתיב חכ' בחוץ תרונה<sup data-n=\"1518\">45</sup>, דוקא ע\"י בחי' חוץ דוקא יבוא החכ' לבחי' תרונה הוא בחי' כתר, שע\"י התלבשות תושב\"כ בחוץ בח\"ת תושבע\"פ עי\"ז תרונה שיתגלה בחי' הרצון עליון דכתר כו', וזהו ישיש ב\"פ, ועוי\"ל<sup data-n=\"1519\">46</sup>",[["1506","33","<b>שעתיד. . ש\"י עולמות</b>: עוקצי' בסופה. ראה גם אוה\"ת בהעלותך ע' תטז."],["1507","34","<b>נתי' לא ידעו עיט</b>: איוב כח, ז. ראה ת\"ז ת\"ל עג, ב. לעיל מאמר ד\"ה וזהו שרש ענין יונתי ובהערה 92."],["1508","35","<b>אי' מקום כבודו</b>: נוסח קדושת כתר."],["1509","36","<b>נתיב זה. . שפנימיות אבא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380456\" data-slug=\"likkutei-torah\" data-id=\"4001380456\">לקו\"ת בהעלותך לו, ג</a>. לעיל מאמר ד\"ה וזהו שרש ענין יונתי ובהערה 96."],["1510","37","<b>שפנימיות אבא הוא פנימיות ע\"י</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541072\" data-slug=\"torat-chaim\" data-id=\"2300541072\">תו\"ח שמות ח\"א כג, א</a> הערה 951."],["1511","38","<b>שהתגלות עתיק הוא בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a>. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["1512","39","<b>ע\"כ יעזב</b>: בראשית ב, כד. ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך על יד הערה 50."],["1513","40","<b>וחתן חות דרגא</b>: ראה יבמות סג, א."],["1514","41","<b>או\"א חו\"ב</b>: ראה ע\"ח שער עתיק שי\"ב, פ\"א."],["1515","42","<b>הבן בחכ'</b>: ס\"י פ\"א, מ\"ד."],["1516","43","<b>בתושבע\"פ מל'</b>: ראה ת\"ז בהקדמה יז, א."],["1517","44","<b>שירידה זו היא צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["1518","45","<b>חכ' בחוץ תרונה</b>: משלי א, כ. ראה זהר תולדות קמא, ב."],["1519","46","<b>ועוי\"ל</b>: ע\"כ נרשם. ראה גם (לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן."]]],[2000480209,"<h3>ויאמר כו' לך לך כו'</h3>\n<b>בס\"ד, פ' לך</b>\n<b></b>להקדיש בפה כו' הזיית הדם ממכ\"ע, אפר סוכ\"ע כו' תרומת הדשן, תיקון חצות כו' ד' שליבות - ב' קיצורים\nלך\n<b>ויאמר</b> ה' אל אברם לך לך<sup data-n=\"1520\">1</sup> כו' אל הארץ אשר אראך<sup data-n=\"1521\">2</sup>, ובבואו לארץ כנען אז בנה מזבחות, ובמד\"ר לך ספל\"ט ג' מזבחות בנה אברהם ע\"ש. והא' בנה בבואו עד מקום שכם, ואח\"כ כשהעתיק משם ההרה בנה עוד מזבח הב' רק שבבנין מזבח הא' נא' לה' הנראה אליו<sup data-n=\"1522\">3</sup>, וכשהעתיק ההרה נא' ויבן מזבח לה'<sup data-n=\"1523\">4</sup>, ולא א' לה' הנראה כ\"א לה' סתם, ובבנין המזבח כשהעקיד את יצחק בנו, לא אמר כלל לש' הוי' כ\"א ויבן שם אברהם את המזבח<sup data-n=\"1524\">5</sup> בה' הידיעה, ובכלל בכל פרשת העקדה לא נז' ש' הוי' עד לאחר שהעקיד את יצחק בנו ע\"ג המזבח כו', ואז ויקרא אליו מלאך ה'<sup data-n=\"1525\">6</sup> ומנע אותו וא\"ל אל תשלח ידך אל הנער<sup data-n=\"1526\">7</sup> ואל תעש לו מאומה כו', ואילו של יצחק<sup data-n=\"1527\">8</sup> לא ראה עד לאחר שהעקיד את יצחק<sup data-n=\"1528\">9</sup> להקריבו קרבן, וכמארז\"ל בפדר\"א שפשט האיל את ידו<sup data-n=\"1529\">10</sup> בטליתו של אברהם וכמשנ\"ת מזה בד\"ה שובה ישראל<sup data-n=\"1530\">11</sup>, ואז מאפר של אילו של יצחק נעשה יסוד על מזבח הפנימי<sup data-n=\"1531\">12</sup> שאחר מ\"ת יקטירו קטרת עליו. והנה נת\"ל<sup data-n=\"1532\">13</sup> בענין הקרבנות שע\"י הקרבת הקרבנות נעשה ריח ניחוח לה'<sup data-n=\"1533\">14</sup>, ואמנם לבחי' שם אלקי' אינו מועיל הקרבן<sup data-n=\"1534\">15</sup> כמ\"ש בזהר, כ\"א זבחי אלקים רוח נשברה<sup data-n=\"1535\">16</sup>, לב נשבר ונדכה<sup data-n=\"1536\">17</sup> זה גם ש' אלקי' לא תבזה כו'.",[["1520","1","<b>ויאמר ה' אל אברם לך לך</b>: אודות מאמר זה רשם כ\"ק אדמו\"ר בספר התולדות של כ\"ק אדמו\"ר מהר\"ש (קה\"ת תש\"ז ע' 53): להקדיש בפה כו' הזיית הדם ממכ\"ע, אפר סוכ\"ע כו' תרומת הדשן, תיקון חצות כו' ד' שליבות — ב' קיצורים.\nלהתחלת המאמר ראה זהר לך פ, א. ראה גם לקמן מאמר ד\"ה ויבן מזבח לה' הנראה אליו. אוה\"ת לך כרך ד ע' 1368. ע' 1376 ואילך. סה\"מ תרל\"ג ח\"א ע' רצג ואילך. וש\"נ. ראה גם בענין המזבחות <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410100\" data-slug=\"likkutei-sichot\" data-id=\"1301410100\">לקו\"ש לך כרך ל ע' 36</a> ואילך.\nחלק הפתיחא עד פיסקא ועפ\"ז יובן — ראה לקמן הערה 18 — לא נמצא בהמשך יונתי הנדפס.\nמאמר זה כנראה הובא בסה\"מ תרמ\"ד ע' רמט ושם: בד\"ה ביום השמיני עצרת (מ\"א) ממאמר ד\"ה יונתי (מ\"ם) בענין הודו לה' — וכנראה כוונתו למאמר דידן ראה לקמן הערה *64.\nהנחת* כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לקמן (בחלק הנחותיו)."],["1521","2","<b>ויאמר.. לך לך. . אראך</b>: לך יב, א."],["1522","3","<b>והא' בנה. . שכם. . לה' הנראה אליו</b>: שם יב, ו-ז."],["1523","4","<b>ההרה בנה. . ויבן מזבח לה'</b>: לך שם ח [ושם: ויבן שם מזבח]. [ועד\"ז במזבח הג' שבב\"ר שם — לך יג, יח]."],["1524","5","<b>ויבן שם אברהם את המזבח</b>: וירא כב, ט."],["1525","6","<b>ויקרא אליו מלאך ה'</b>: שם כב, יא."],["1526","7","<b>אל תשלח ידך אל הנער</b>: וירא שם יב."],["1527","8","<b>ואילו של יצחק</b>: ראה פדר\"א רפי\"ט. תויו\"ט אבות פ\"ה, מ\"ו."],["1528","9","<b>ואילו של יצחק. . שהעקיד את יצחק</b>: וירא שם, יג."],["1529","10","<b>בפדר\"א שפשט האיל את ידו</b>: ספל\"א. ראה בהערה שלאח\"ז."],["1530","11","<b>בד\"ה שובה ישראל</b>: נדפס לעיל — ראה שם על יד ובהערות 24 ואילך."],["1531","12","<b>מאפר. . יסוד על מזבח הפנימי</b>: ראה שם ובהערות 12-14."],["1532","13","<b>נת\"ל</b>: במאמר ד\"ה ביום השמיני עצרת."],["1533","14","<b>ריח ניחוח לה'</b>: ויקרא א, ט. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301490060\" data-slug=\"likkutei-sichot\" data-id=\"1301490060\">לקו\"ש ויקרא כרך לב ע' 1</a> ואילך."],["1534","15","<b>שם אלקי' אינו מועיל הקרבן</b>: ראה זהר משפטים דק\"ח ע\"א. ויקרא ה, א. לעיל מאמר ד\"ה ביום השמיני עצרת ובהערה 17."],["1535","16","<b>זבחי אלקים רוח נשברה</b>: תהלים נא, יט. ראה גם אגה\"ת פ\"ז. תניא פי\"ז."],["1536","17","<b>ונדכה</b>: ראה גם לעיל המשך יונתי ובהערה 553."]]],[2000480210,"<b>ולהבין</b> כ\"ז צריך להקדים תחלה<sup data-n=\"1537\">18</sup> סדר ֶ העלאת הקרבן שהאיש המקריב אותו צריך להקדישו בפה<sup data-n=\"1538\">19</sup> דוקא, ואח\"כ שוחטין אותו כו' ומעלה אותו הכהן ע\"ג המזבח, והענין הוא בהיות ידוע שבהמה בגימ' ב\"ן<sup data-n=\"1539\">20</sup> שהוא בחי' ש' ב\"ן המתברר והמברר הוא האדם שאדם בגימ' מ\"ה<sup data-n=\"1540\">21</sup> שזהו בדוגמא כמו שהוא למעלה שמ\"ה מברר ב\"ן<sup data-n=\"1541\">22</sup>, ולכן צריך האדם להקדישו בפה ולומר ה\"ז עולה וה\"ז קרבן, והיינו כי עם היות שרש הבהמה גבוה מאד נעלה בבחי' התהו שקדם במעלה על בחי' התיקון<sup data-n=\"1542\">23</sup> כו' כנ\"ל, עכ\"ז עצם בחי' הבהמה בנפילתה למטה ה\"ה גשמיות ונפלה וירדה כ\"כ עד שנעשית בהמה בחי' בע\"ח שהוא פחות במעלה נגד מין המדבר עד שלצורך אכילת מין המדבר הותר שחיטת<sup data-n=\"1543\">24</sup> ונחירת בע\"ח<sup data-n=\"1544\">25</sup> כו', ולכן בכדי להעלותה מגשמיותה צריך האדם שהוא בחיר הנבראי'<sup data-n=\"1545\">26</sup> והוא בגימ' מ\"ה להמשיך עליו אור מקיף בכדי שהמקיף יעלה אותה שתוכל להתעלות ע\"י הכהן לשרש שרשה ושתוכלל באש שלמעלה בבחי' ארי' דאכיל קרבנן<sup data-n=\"1546\">27</sup> שהוא בחי' ימין מקרבת<sup data-n=\"1547\">28</sup> ואגב ז\"ע לאכללא שמאלא בימינא<sup data-n=\"1548\">29</sup> כו', וע' במ\"א בענין ואם האכל יאכל<sup data-n=\"1549\">30</sup> בשתי אכילות הכתוב מדבר שהוא אכילת מזבח ואכילת כהנים שכהנים אוכלים ובעלים מתכפרים<sup data-n=\"1550\">31</sup> שאכילת כהנים ז\"ע אכילת אדם שמעורר אכילת אדם העליון שגבוה יותר מאכילת מזבח כמש\"ש באריכות, ע' בהג\"ה לד\"ה מזמור לתודה, וקרבנות שהם נשרפי' כמו",[["1537","18","<b>ולהבין כ\"ז צריך להקדים תחלה</b>: מכאן נמצא גם בהמשך יונתי הנדפס ושם הפתיחה: ועפ\"ז יובן."],["1538","19","<b>הקרבן. . להקדישו בפה</b>: ראה רש\"י ותוס' מעילה ח, א (במשנה). (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 23 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380655\" data-slug=\"likkutei-torah\" data-id=\"4001380655\">לקו\"ת מטות פג, ב</a>. מאמרי אדה\"ז תקס\"ד ע' קצה. תקס\"ז ע' רפט. ע' רצא ואילך. ע' רצט. סה\"מ תרכ\"ט ע' שסא. מאמר ד\"ה להבין מ\"ש בר\"ה זה היום תחלת מעשיך נצו\"י תשי\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191545\" data-slug=\"likkutei-sichot\" data-id=\"1300191545\">לקו\"ש נצבים כרך יט ע' 532</a>. לקולו\"י אגרות ע' שא וע' דש ואילך."],["1539","20","<b>שבהמה בגימ' ב\"ן</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא ספמ\"ו</a>. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["1540","21","<b>שאדם בגימ' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> הערה 14."],["1541","22","<b>שמ\"ה מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["1542","23","<b>התהו שקדם במעלה על בחי' התיקון</b>: ראה לעיל מאמר ד\"ה ביום השמיני עצרת ובהערה 51."],["1543","24","<b>שלצורך אכילת. . הותר שחיטת. . בע\"ח</b>: פ' ראה יב, כא. סהמ\"צ להרמב\"ם מ\"ע קמו. רמב\"ם הל' שחיטה רפ\"א."],["1544","25","<b>הותר. . ונחירת בע\"ח</b>: נח ט, ג-ד. חולין יז, א. לג, א."],["1545","26","<b>האדם שהוא בחיר הנבראי'</b>: ראה גם עבודת הקודש חלק התכלית פ\"ב — פ\"ו. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פט\"ו. וש\"נ."],["1546","27","<b>ארי' דאכיל קרבנן</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ה."],["1547","28","<b>ימין מקרבת</b>: סוטה מז, א."],["1548","29","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["1549","30","<b>ואם האכל יאכל</b>: צו ז, יח. זבחים יג, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380107\" data-slug=\"likkutei-torah\" data-id=\"4001380107\">לקו\"ת צו ז, ד</a> ואילך. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ז. וש\"נ."],["1550","31","<b>שכהנים אוכלים ובעלים מתכפרים</b>: פסחים נט, ב. רמב\"ם הל' מעשה הקרבנות פ\"י, ה\"א. לעיל שם. וש\"נ.\n32)בהג\"ה לד\"ה מזמור לתורה: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450516\" data-slug=\"or-hatorah-hb\" data-id=\"8316450516\">אוה\"ת</a> תהלים כרך ב ע' תתקפו בשולי היריעה. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 47."]]],[2000480211,"פרים הנשרפי' ושעירי' הנשרפים<sup data-n=\"1551\">33</sup> וכל העולות<sup data-n=\"1552\">34</sup> נכללים הכל באש שלמעלה, וצ\"ל ענין בחי' עלייתם ע\"י האש, והענין הוא ע\"פ מה שנודע ששרש כל הנפשות הוא מבחי' ממכ\"ע אפי' נה\"א שבאדם, וכ\"ש כל נפשות הבע\"ח וכן נפשות הצומח ודומם שכולם יש להם חיות המחי' אותם, ואמנם גוף הבע\"ח וכן גוף הדומם וצומח זה א\"א שיתהוה מבחי' ממכ\"ע בדרך עו\"ע<sup data-n=\"1553\">36</sup> שאם הי' &lt;51&gt;\nּ רבבות מדרגות השתלשלות לא הי' מתהוה בחי' התהוות הגשמיות מהרוחני' עד שגם החוקרי' כתבו שהתהוות הגשמיות מהרוחניות<sup data-n=\"1554\">37</sup> אין לך בריאה יש מאין גדול מזה אלא שהם מדמים רק שנברא יש מאין שמבחי' רוחני' זו עצמה המחי' נברא זה נעשה בדרך יש מאין גם גופו הגשמי אשר באמת לא כן הוא שאין בכח בחי' אין זה להוות גשם הגוף, אלא שזהו מבחי' אוא\"ס הסוכ\"ע<sup data-n=\"1555\">35</sup> הכל יכול וגשמיות ורוחניות שוין ממש לפניו כו', וע\"כ בכחו הא\"ס ברא גשם של כל נברא כו', ולכן סדר עלייתו שמתעלה אחר שהקדיש אותו המקדש באו\"מ שלו ע\"י דבורו כנ\"ל תחילה צריכין לשחוט אותו דהיינו להוציא חיותו שהדם הוא הנפש<sup data-n=\"1556\">38</sup>, ולהיות כי זהו מבחי' ממכ\"ע דהיינו הכלי שבו הי' מלובש כח הנפש מבחי' ממכ\"ע נצטוינו שיזרוק הכהן הזאות ממנו בדרך היקף להעלותו לבחי' סוכ\"ע, וזהו דקדוק לשון חז\"ל עלה בכבש ופנה לסובב<sup data-n=\"1557\">39</sup>, והעיקר בקרבנות הוא בחי' הדם והגוף שהוא מבחי' סוכ\"ע, ואמנם כשנבין בפרטיות בחי' פרטי הגוף שמה שמתגדל ומתרבה בשרו וחלבו וריבוי דמו בזה יש כח בחי' ממכ\"ע ג\"כ שאם לא הי' חי לא הי' מתגדל בשרו, שהרי כשאינו בשלימות בבריאותו מתנונה והולך, שנמצא כל בחי' גידול בשרו יש בזה תערובות חלק חיות נפשו המחי' אותו, ולכן גם לאחר ששחטו אותו ופסקו חיותו עכ\"ז נשאר מה שכבר נתגדל בעודו בחיים, וגם בחי' ציור אבריו והתכללותו בשר גידי' ועצמות ועור החופה אותם זהו כדוגמת בחי' התיקון, אלא שבכלליות ציורו נשתנה הבהמה להיות ראשו וזנבו שוה<sup data-n=\"1558\">40</sup> להורות על שרשו שהוא מבחי' עיגולים דתהו, ואינו כמו האדם שמהלך בקומה זקופה דוגמת בחי' יושר דתיקון אלא כדוגמת בחי' העיגולי' דתהו, אך פרטי",[["1551","33","<b>פרים הנשרפי' ושעירי' הנשרפים</b>: לשון המשנה זבחים מז, סע\"א."],["1552","34","<b>וכל העולות</b>: ויקרא א, ט. רמב\"ם הל' מעשה הקרבנות רפ\"ו."],["1553","36","<b>עו\"ע</b>: ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a> (הנזכר בספרים). שה\"ש א, ב (כמ\"ש בספרים)."],["1554","37","<b>החוקרי' כתבו שהתהוות הגשמיות מהרוחניות</b>: ראה עקרים מ\"א, פכ\"ג. מ\"ד, פ\"ג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370407\" data-slug=\"torah-or\" data-id=\"3901370407\">תו\"א מג\"א צ, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380799\" data-slug=\"likkutei-torah\" data-id=\"4001380799\">לקו\"ת פ' ראה כ, ד</a>. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ד. וש\"נ."],["1555","35","<b>כל הנפשות. . ממכ\"ע. . גוף. . אוא\"ס הסוכ\"ע</b>: ראה לעיל מאמר ד\"ה ולקחתם לכם רפ\"ג. ד\"ה סוכה שחמתה מרובה מצלתה ובהערה 25."],["1556","38","<b>שהדם הוא הנפש</b>: פ' ראה יב, כג."],["1557","39","<b>עלה בכבש ופנה לסובב</b>: זבחים נג, רע\"א במשנה. ראה גם מאמרי אדה\"ז הנחות הר\"פ ס\"ע נד בשם מורי [ הה\"מ<sup data-n=\"e157\">א</sup>]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380635\" data-slug=\"likkutei-torah\" data-id=\"4001380635\">לקו\"ת פינחס עח, סע\"ד</a>. סה\"מ תרכ\"ט ע' קיז. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 60."],["1558","40","<b>הבהמה להיות ראשו וזנבו שוה</b>: ראה גם לעיל המשך יונתי פ\"ד. וש\"נ.\n\n<b>א</b>  מובא גם באוה\"ת יתרו ע' תתסג. ביאוה\"ז להצ\"צ כרך א ע' תסט."]]],[2000480212,"כל הציור שבו זהו כדוגמת בחי' התיקון שהרי בתהו לא הי' התכללות כלל, ולכן צריכים לשרוף אותן שיתבטל צורתה<sup data-n=\"1559\">41</sup> לגמרי ולא ישאר ממנה כ\"א האפר שזהו כמו בתחילת ברייתה שהכל הי' מן העפר<sup data-n=\"1560\">42</sup>, והארץ שרשה מכח הא\"ס הסוכ\"ע, ולכן במח' ארץ קדמה לשמים<sup data-n=\"1561\">43</sup> כו', להיותה מבחי' ומדריגה היותר עליון שבתהו שקדם לבחי' התיקון, ולכן כאשר נתבטל לגמרי מכל וכל ולא נשאר כ\"א בחי' שרשו האמיתי שהוא האפר שזהו מבחי' העפר שממנו נוצר גופו כו' אז יוכל בחי' אפר זה להיות יסוד על בחי' מזבח הפנימי שענין בחי' העבודה בבחי' מזבח הפנימי הוא ענין יותר נעלה שלא בערך נגד בחי' העבודה דזבח והקרבת הקרבנות כמשי\"ת<sup data-n=\"1562\">44</sup>. ועכ\"ז הוא יסוד לבחי' מזבח הפנימי כו', שלבא לבחי' זו א\"א כ\"א ע\"י קדימת זביחת הזבח כו'.\n<b></b>קיצור. וסדר העלאת הקרבן תחלה צריך האדם להמשיך עליו או\"מ ע\"י שמקדישה בפה ואח\"כ הזיית הדם שבו הנפש ממכ\"ע, והאפר עיקר בחי' סוכ\"ע, והוא היסוד לבחי' מזה\"פ כמשי\"ת.\n&lt;52&gt;\nּוהנה אילו ש\"י לא ראה אברהם עד שהעקיד את יצחק בנו ע\"ג המזבח ממעל לעצים אז כאשר א\"ל המלאך בשם ה' אל תשלח ידך אל הנער ואל תעש לו מאומה אז וישא אברהם את עיניו וירא את האיל<sup data-n=\"1563\">45</sup>, וכמשנ\"ת לעיל<sup data-n=\"1564\">46</sup> שהאיל הי' נאחז בסבך עד שפשט ידו בטליתו של אברהם כמשנ\"ת שם, והענין הוא ג\"כ בעבודה שכשהי' האדם<sup data-n=\"1565\">47</sup> מביא עולתו הי' צ\"ל הקרבת נפשו לה' שתעלה לה' ע\"י הקרבת קרבן זה ושיעלה נפשו בעילוי אחר עילוי לבא לדבקה בה' אחד וז\"ע סמיכת ידו על ראש העולה<sup data-n=\"1566\">48</sup> שסומכה ונשען שע\"י קיום מצותו<sup data-n=\"1567\">49</sup> ית' שציונו להקריב עולה וזבח וע\"י שרוצה בכל לבו להתקרב אליו ית' עי\"ז יתעלה נפשו בעילוי אחר עילוי, וכשם שע\"י הקרבן מתקרבי' כל הכחות והשמות<sup data-n=\"1568\">50</sup> למעלה כו' מחמת עוצם הגילוי מבחי' אורות דתהו כנ\"ל כן יתקרב נפשו לבוא לדבקה בו ית' כו', ועכשיו תפלה במקום קרבנות<sup data-n=\"1569\">51</sup> תקנו<sup data-n=\"1570\">52</sup>, ותיקנו לומר תחלה פ' הקרבנות תרה\"ד וקרבן התמיד ושארי קרבנות צבור וקרבן יחיד<sup data-n=\"1571\">53</sup> בכדי שיתעלה נפשו, ובעבודה ענין תרה\"ד הוא בחי'",[["1559","41","<b>צורתה</b>: בהמשך יונתי הנדפס: צורתן."],["1560","42","<b>שהכל הי' מן העפר</b>: קהלת ג, כ."],["1561","43","<b>ארץ קדמה לשמים</b>: חגיגה יב, א."],["1562","44","<b>מזבח הפנימי. . דזבח והקרבת הקרבנות כמשי\"ת</b>: ראה לקמן מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי."],["1563","45","<b>וישא אברהם. . וירא את האיל</b>: וירא כב, יג [ושם: והנה איל]."],["1564","46","<b>וכמשנ\"ת לעיל</b>: ראה מאמר ד\"ה שובה ישראל."],["1565","47","<b>שכשהי' האדם</b>: בהמשך יונתי הנדפס: שכשהאדם הי'."],["1566","48","<b>סמיכת ידו על ראש העולה</b>: ויקרא א, ד. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמוכים לעד פ\"ג."],["1567","49","<b>מצותו</b>: בהמשך יונתי הנדפס: מצותיו."],["1568","50","<b>הקרבן מתקרבי' כל הכחות והשמות</b>: נסמן לעיל מאמר ד\"ה ביום השמיני עצרת הערה 19."],["1569","51","<b>יתקרב. . תקנו</b>: בהמשך יונתי הנדפס: מתקרב. . תקנום."],["1570","52","<b>תפלה במקום קרבנות תקנו</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["1571","53","<b>תחלה פ' הקרבנות. . וקרבן יחיד</b>: ראה גם שו\"ע אדה\"ז מהדו\"ת הלכות השכמת הבוקר ס\"א, ס\"י. (מהדו\"ק) הלכות הנהגות אדם בבקר ס\"א, סי\"א ואילך. הל' ברכות השחר סמ\"ח, ס\"א וס\"ב. ס\"נ, ס\"א. סידור אדה\"ז במקומו."]]],[2000480213,"שפלות והכנעת החומר<sup data-n=\"1572\">54</sup> בתיקון חצות זמן תרומת הדשן<sup data-n=\"1573\">55</sup> ולהיות בבחי' מרירות על עוצם ריחוקו, ומ\"מ יתרחק מן העצבות כ\"א בבחי' מרירות<sup data-n=\"1574\">56</sup> לבד, כי העצבות זהו אסקופה הנדרסת<sup data-n=\"1575\">57</sup> לכל העוונות כו' כ\"א מרירות לבד שעי\"ז נמשך התעוררות רח\"ר על נפשו הנדכאה מחמת ריחוקה כו', ושוב באמרו פ' הקרבנות הנה ארז\"ל כל העוסק בתורת עולה<sup data-n=\"1576\">58</sup> כאלו הקריב עולה שברוחניות מתעלה נפשו עד שמודה לה' ואו' הודו לה' קראו בשמו<sup data-n=\"1577\">59</sup>, ולכאו' גם בקומו משנתו אומר מודה אני<sup data-n=\"1578\">60</sup>, אך הענין הוא שמודה אני צ\"ל גם קודם שנטל ידיו מפני שאין בהם הזכרת השם<sup data-n=\"1579\">61</sup> כלל, אלא שההודאה שאו' מודה אני הוא שאיננו נפרד מאחדותו ויחודו, שענין הודאה זו הוא שמודה שכן הוא הגם שאינו<sup data-n=\"1580\">62</sup> מבין כלל, שהוא הודאה כלליות, והודאה זו פעולתה הוא להורות שאינו נפרד כלל, רק מפני העדר ידיעתו לגמרי הוא מודה שכן הוא ולכן אומר לפניך שכולל כל פרטי פרטיות אבל הוא אינו פורט אותם מפני העדר ידיעתו עדיין שהרי הוא כקטן שנולד דמי<sup data-n=\"1581\">63</sup> ויותר מזה כמו שכעת נברא ונוצר מחדש, ואין שום נברא שיודע עדיין לאמן אותו כו' שהרי זולתו ג\"כ נברא ונוצר מחדש כעת, ולכן התחדשות זו הוא יותר חדש מקטן שנולד שיש מי שיאמן אותו ויגדלו ויעשה לו הצריך לו, משא\"כ בקומו בבקר כשמתחיל להאיר ה\"ז כמו תחילת ברה\"ע וכל מין האנושי נברא ונוצר מחדש, רק מפני שנוצר בדעת אומר מודה אני לפניך בכלל היינו שאינו נפרד כו', אבל מה שאו' אח\"כ הודו להוי' קראו בשמו הנה הוא פורט שבשם הוי' לעוצם קדושתו א\"א להיות בו השגה כ\"א הודאה שמודה על האמת שכן הוא מאחר שההשגה מושלל ממנו לכן מודה הוא וא\"כ הודאה זו קרובה &lt;53&gt;\nּ להשגה שגם מה שא\"א להשיג בו זהו ג\"כ להשגה תחשב<sup data-n=\"1582\">*64</sup> כו', וגם כי ע\"י הודאה",[["1572","54","<b>תרה\"ד. . שפלות והכנעת החומר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381041\" data-slug=\"likkutei-torah\" data-id=\"4001381041\">לקו\"ת סוכות עט, ב</a>. סה\"מ תרכ\"ט ע' קסו. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 75."],["1573","55","<b>בתיקון חצות זמן תרומת הדשן</b>: ועד\"ז בסה\"ש תש\"ג ע' 126. לקמן בהנחה כאן על יד הערה 74.\nחצות זמן תרומת הדשן — ראה יומא כ, א. כב, א. כז, ב תוד\"ה איכא. לג, א תוד\"ה אביי. שו\"ע אדה\"ז (מהדו\"ק) שם סי\"ג בסופו. ראה גם לקמן בהנחה כאן על יד הערה 73 [בחצות לילה]. סה\"מ תרל\"ב ח\"ב ע' תרו<sup data-n=\"e158\">ב</sup> [אחר חצות]. סה\"מ תרל\"ג ח\"ב ע' תקעג [בחצות לילה]. תרכ\"ט שם [בחצות לילה]."],["1574","56","<b>העצבות. . מרירות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א</a>."],["1575","57","<b>אסקופה הנדרסת</b>: ערובין צח, א. ראה גם מאמרי אדה\"א נ\"ך ע' לא ואילך. וש\"נ."],["1576","58","<b>כל העוסק בתורת עולה</b>: ראה מנחות קי, א. לקו\"ש מסעי כרך יח ע' 413. וש\"נ. ערב פסח כרך לב ע' 37. וש\"נ."],["1577","59","<b>הודו לה' קראו בשמו</b>: דהי\"א טז, ח. ראה גם המשך תער\"ב ח\"א ע' תריט. מאמר ד\"ה אני לדודי תשט\"ו."],["1578","60","<b>בקומו משנתו אומר מודה אני</b>: ראה שו\"ע אדה\"ז חאו\"ח מהדו\"ק ס\"א, ס\"ה. מהדו\"ת ס\"א, ס\"ו. סידור אדה\"ז במקומו (נדפס גם בהוספות למהדורת שו\"ע קה\"ת). ראה גם המשך תער\"ב שם. ד\"ה אני לדודי שם."],["1579","61","<b>שמודה אני. . קודם שנטל ידיו. . הזכרת השם</b>: ראה שו\"ע וסידור שם. מכתב כ\"ח תשרי תשט\"ו (אג\"ק כ\"ק אדמו\"ר ח\"י ע' כג). ראה גם המשך תער\"ב ח\"ב ע' תתד."],["1580","62","<b>שאינו</b>: בהמשך יונתי הנדפס: שאיננו."],["1581","63","<b>כקטן שנולד דמי</b>: ע\"פ יבמות כב, א."],["1582","*64","<b>מה שא\"א להשיג. . להשגה תחשב</b>: מ\"ש במ\"א דבינה עד הוד אתפשטית א\"כ צ\"ל דגם בבחי' הוד שבהוד מאיר בחי' בינה, י\"ל דזה שמשיג שהדבר מופלא ואינו מושג אצלו ה\"ז ג\"כ קצת השגה כמ\"ש במ\"א בד\"ה ביום השמיני עצרת<sup data-n=\"e159\">ג</sup> (מ\"א) ממאמר ד\"ה יונתי (מ\"ם) בענין הודו לה' באופן הא' נר\"ל שכן כוונתו יעו\"ש — סה\"מ תרמ\"ד ע' רמט.\n\n<b>ב</b>  נדפס גם בסה\"מ תרל\"ג ח\"ב ע' תקעג.\n\n<b>ג</b>  כנראה כוונתו למאמר דידן."]]],[2000480214,"זו ממשיך ש' הוי', קראו בשמו פי' שבבחי' ש' דהוי'<sup data-n=\"1583\">65</sup> הוא בחי' מל'<sup data-n=\"1584\">64</sup> שהש' הוא אד'<sup data-n=\"1585\">66</sup> או<sup data-n=\"1586\">68</sup> אלקי'<sup data-n=\"1587\">67</sup> זה יכולים לקרות כו', ונמצא כי זהו השגה כמו שהוא באמת לאמיתו, והיינו אחר שכבר בירך ח\"י ברכות דברכת השחר<sup data-n=\"1588\">69</sup> ועל כל פרטי החיות ודברים הנצרכים לו בירך את השם הגם שאינו מבין פרטיות ש' הוי' כו', אמנם זה יודע שפי' הוי' הוא ל' מהוה<sup data-n=\"1589\">70</sup>, וע\"כ על מה שהוא מחי' אותו מחדש וא\"ת מחי' אלא מהוה<sup data-n=\"1590\">71</sup> ע\"ש מברך<sup data-n=\"1591\">72</sup> את הוי' המהוהו כו', ואח\"כ אומר פ' הקרבנות ונשלמה פרים שפתינו<sup data-n=\"1592\">73</sup> וכל העוסק בתורת עולה כאלו הקריב עולה שנעשה קרוב מעט עכ\"פ בל\"א<sup data-n=\"1593\">74</sup> נענטער, ואז יוכל לומר שבש' הוי' לא שייך רק בחי' הודאה לבד, ובשמו יפעול הקריאה מפני שזהו בחי' כח הפועל בנפעל<sup data-n=\"1594\">75</sup>, ואז מתחיל לעלות בסולם, וכמ\"ש סולם מוצב ארצה וראשו מגיע השמימה<sup data-n=\"1595\">76</sup>, פי' השמימה כי בשמים וארץ יש ב' בחי' כמ\"ש האזינו השמים ותשמע הארץ<sup data-n=\"1596\">77</sup>, וישעי' אמר שמעו שמים<sup data-n=\"1597\">78</sup> והאזיני ארץ, שנת' במ\"א שנבואת ישעי' הי' בבריאה<sup data-n=\"1598\">79</sup>, אך כל נבואה שרשה מאצי'<sup data-n=\"1599\">80</sup> א\"כ",[["1583","65","<b>דהוי'</b>: בהמשך יונתי הנדפס: הוי'."],["1584","64","<b>קראו בשמו. . בחי' מל'</b>: ראה מאמרי אדה\"ז הקצרים ע' רצז. אוה\"ת סידור ע' ט וע' יב. ראה גם ד\"ה אני לדודי שם."],["1585","66","<b>מל'. . אד'</b>: ראה זהר ויקרא יא, א. מאמרי אדה\"א בראשית ע' קצז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 44."],["1586","68","<b>אד' או אלקי'</b>: ראה לקו\"ת ש\"ש סה, ד (ומציין למ\"ח). סה\"מ תרכ\"ז ע' מב. וש\"נ. המשך תער\"ב ח\"א ע' תריט."],["1587","67","<b>מל'. . או אלקי'</b>: ראה זהר בראשית כב, א. אחרי סה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540393\" data-slug=\"torat-chaim\" data-id=\"2300540393\">תו\"ח וארא ח\"א עה, ב</a> הערה 202."],["1588","69","<b>ח\"י ברכות דברכת השחר</b>: ראה גם לעיל המשך יונתי הערה 595."],["1589","70","<b>הוי' הוא ל' מהוה</b>: ראה גם לעיל מאמר ד\"ה ביום השמיני עצרת ובהערה 11."],["1590","71","<b>וא\"ת מחי' אלא מהוה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["1591","72","<b>ע\"ש מברך</b>: כ\"ה גם בהמשך יונתי הנדפס."],["1592","73","<b>ונשלמה פרים שפתינו</b>: הושע יד, ג."],["1593","74","<b>בל\"א</b>: בלשון אידיש. ראה שיחת ליל הושע\"ר תשנ\"ב אות ג (שיחות קודש ע' 165 ואילך). ליל שמח\"ת קודם הקפות תשנ\"ב — סה\"ש תשנ\"ב ח\"א ע' 38 בשולי הגליון להערה 20. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211457\" data-slug=\"likkutei-sichot\" data-id=\"1300211457\">לקו\"ש משפטים כרך כא ע' 448</a> הערה 15."],["1594","75","<b>כח הפועל בנפעל</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף ש\"ג."],["1595","76","<b>סולם מוצב ארצה. . השמימה</b>: ויצא כח, יב."],["1596","77","<b>האזינו השמים ותשמע הארץ</b>: האזינו לב, א. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 102. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גדולה מילה על יד הערה 6 ואילך."],["1597","78","<b>וישעי' אמר שמעו שמים</b>: ישעי' א, ב."],["1598","79","<b>שנבואת ישעי' הי' בבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. לקוטי הש\"ס להנ\"ל יבמות מט, ב ד\"ה מנשה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540375\" data-slug=\"torat-chaim\" data-id=\"2300540375\">תו\"ח בא ח\"א קיד, סע\"ג</a>. וש\"נ. סה\"מ תרמ\"ז ע' קלו. ע' קמב. סה\"מ ליקוט ח\"ג (מאמר ד\"ה בגמ' יבמות. . ע\"פ ואראה תרמ\"ט) ע' ו."],["1599","80","<b>כל נבואה שרשה מאצי'</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה משה קבל תורה מסיני בסופה. וש\"נ."]]],[2000480215,"שו\"א שא' ישעי' זהו זו\"נ דאצי'<sup data-n=\"1600\">81</sup> שהמדות מקיפי' את הדבור<sup data-n=\"1601\">*82</sup> כמו שמים שמקיפי' את הארץ כו', אבל משה א' השמים והארץ בה' הידיעה להיות ששמים וארץ שא' זהו חו\"ב<sup data-n=\"1602\">82</sup> שכמו המדה מקפת הדבור כן הבינה נק' ארץ<sup data-n=\"1603\">83</sup>, רק שהיא ארץ עילאה, והחכ' הוא שמים<sup data-n=\"1604\">84</sup>, שמים הוא אש ומים, מים הוא בחי' חכ'<sup data-n=\"1605\">86</sup> והחכ' יש בה קצת דין כמ\"ש החייט<sup data-n=\"1606\">87</sup> זהו אות א' מתיבת אש<sup data-n=\"1607\">88</sup> כו', וגם שמים הוא שם מים<sup data-n=\"1608\">85</sup> שקאי על מי החכ' כו', ויש עוד בחי' הגבוה מב' בחי' שמים אלו והוא בחי' שמי השמים שזהו בחי' הכתר<sup data-n=\"1609\">89</sup> שכולל כלליות הכל כו', וכאן בסולם הנ\"ל דתפלה אמר וראשו מגיע השמימה שכולל כל בחי' שמים אפי' בחי' שמי השמים ג\"כ וכמ\"ש במ\"א בענין מי יעלה לנו השמימה<sup data-n=\"1610\">90</sup> בד\"ה בעצם היום הזה<sup data-n=\"1611\">91</sup>, רק תחילתו הוא מוצב ארצה שמתחיל מדברים תחתונים שבברכת השחר מברך שלא עשני כו' עבד ואשה כו', וכנודע מענין ד' שליבות שבסולם שהוא עד ב\"ש, וב\"ש עד בק\"ש<sup data-n=\"1612\">93</sup> ובק\"ש וק\"ש, ותפלה<sup data-n=\"1613\">92</sup>, שכאשר מבין שבש' הוי' שייך רק הודאה לבד ושעי\"ז ממשיכי' אז<sup data-n=\"1614\">94</sup> מתחיל לזמר עריצים<sup data-n=\"1615\">95</sup> ולהכרית כל החוחים והקוצים המונעי' ומעכבי' כמו שכורתים בגן את",[["1600","81","<b>שו\"א. . זו\"נ דאצי'</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' יב. אוה\"ת לך כרך ד ס\"ע תשכה ואילך<sup data-n=\"e160\">ד</sup>. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ג. סה\"מ תרכ\"ו ע' כז. תרל\"ח ע' קעז. וש\"נ. (ע' שפד. הנחות שבהערה 77)."],["1601","*82","<b>שהמדות מקיפי' את הדיבור</b>: ראה גם מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ג. סה\"מ תרכ\"ו ס\"ע כו ואילך. תרל\"ח ע' שפד."],["1602","82","<b>ששמים וארץ. . חו\"ב</b>: ראה מאמרי אדה\"ז תקס\"ג שם ע' יג ואילך. אוה\"ת לך־ מאמרי אדמו\"ר הצ\"צ־ סה\"מ תרכ\"ו הנ\"ל. סה\"מ תרל\"ח ע' שפד. הנחות שבהערה 77. המשך תער\"ב ח\"א ע' רסד."],["1603","83","<b>הבינה נק' ארץ</b>: ראה (בנוסף להערה שלפנ\"ז) לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 291."],["1604","84","<b>והחכ' הוא שמים</b>: ראה (בנוסף להערה 82) אוה\"ת לך הנ\"ל ע' 1450 ואילך."],["1605","86","<b>מים הוא בחי' חכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a> ובמ\"מ הגהות והע\"ק שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540308\" data-slug=\"torat-chaim\" data-id=\"2300540308\">תו\"ח בשלח ח\"א קמג, ב</a> ובהערה 91."],["1606","87","<b>והחכ'. . דין כמ\"ש החייט</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, ד</a>. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 37."],["1607","88","<b>אות א' מתיבת אש</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1038."],["1608","85","<b>שמים הוא אש ומים. . שם מים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח."],["1609","89","<b>שמי השמים. . הכתר</b>: ראה מאמרי אדה\"ז תקס\"ג שם ע' יד. אוה\"ת לך שם ס\"ע תשכו. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ד<sup data-n=\"e161\">ה</sup>. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 116. סה\"מ תרכ\"ו שם. ראה גם הגהת ר' הלל בפלח הרמון תזריע ריש ע' קנו."],["1610","90","<b>מי יעלה לנו השמימה</b>: נצבים ל, יב."],["1611","91","<b>בד\"ה בעצם היום הזה</b>: ראה אוה\"ת שם. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 100. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גדולה מילה על יד הערה 22."],["1612","93","<b>בק\"ש</b>: ברכות ק\"ש."],["1613","92","<b>ד' שליבות שבסולם. . ותפלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380047\" data-slug=\"likkutei-torah\" data-id=\"4001380047\">לקו\"ת בשלח ב, ב</a>. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערות 117-118."],["1614","94","<b>ממשיכי' אז</b>: כ\"ה גם בהמשך יונתי הנדפס."],["1615","95","<b>לזמר עריצים</b>: ע\"פ ישעי' כה, ה. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 33.\n\n<b>ד</b>  אלא ששם מפרש זה על מה שאמר משה (האזינו השמים ותשמע הארץ) ומציין לזח\"ג ואתחנן דרס\"ג ע\"א.\n\n<b>ה</b>  ושם: הן לה' אלוקינו השמי' ושמי השמי' — עקב י, יד [ושם: אלקיך]."]]],[2000480216,"הזמורות שנתקלקלו בכדי שהעצים החיים יצמחו בטוב יותר, וכן הוא באדם שנמשל לעץ כמ\"ש כי האדם עץ השדה<sup data-n=\"1616\">96</sup> צריך להכרית כל החוחים והקוצים המונעים ומעכבים את גידול וצמיחת האילן שאינו יכול לעלות הגבה למעלה כו', ושוב מתבונן בבק\"ש בבחי' ביטול המלאכים איך שהם בטלים בתכלית השרפי' אומרים קדוש ג\"פ<sup data-n=\"1617\">97</sup> עד שמזכירים את הוי' כו' והאופנים מתנשאי' לעומתם ואו' ברוך<sup data-n=\"1618\">98</sup> וכמשנ\"ת במ\"א ההפרש שביניהם שהשרפים רוצים להתעלות והאופנים רוצים שיומשך להם<sup data-n=\"1619\">99</sup> המשכת אלקות, וע\"י הרעש שלהם ממשיכי' ממקומו ממקורו &lt;54&gt;\nּ ושרשו<sup data-n=\"1620\">100</sup> ע\"י הרעש ותי' ברוך כבוד ה' ממקומו ר\"ת בכי\"ם<sup data-n=\"1621\">101</sup> שהוא הבכי' על העדר ההשגה, וכ\"ז מפני כי בכאו\"א מישראל יש ב' נפשות<sup data-n=\"1622\">102</sup> נה\"א ונה\"ב, הנה\"א היא חלק אלק' ממעל<sup data-n=\"1623\">103</sup>, והנה\"ב היא משמרי האופנים<sup data-n=\"1624\">104</sup>, ועיקר ירידת הנשמה בגוף הוא בשביל בירור נה\"ב<sup data-n=\"1625\">105</sup> שגם הוא יבא לדבקה בו, והוא מהתהו שקדם לתיקון כמו הבהמה הגשמי' רק שנה\"ב שבאדם הוא מפני שור שבפני אדם<sup data-n=\"1626\">106</sup> או מפני אדם שבפני שור<sup data-n=\"1627\">107</sup> ולכן<sup data-n=\"1628\">108</sup> ע\"י ההקרבה שמקריבין הנה\"ב לשרשה ומקורה נמשך בחי' אורות דתהו בכלים דתיקון כו', ולכן כאשר רואה שרשו ומקורו בטל לאלקות עי\"ז פועל בו ג\"כ הביטול כו', ולכן אח\"כ באמרו ק\"ש בא לבחי' מס\"נ באחד<sup data-n=\"1629\">109</sup> ובשכמל\"ו שהם ב' בחי' הביטול דנה\"א ונה\"ב<sup data-n=\"1630\">110</sup> כו', עד שאח\"כ יוכל להמשיך בשמ\"ע בח\"י ברכאן דצלותא<sup data-n=\"1631\">111</sup> המשכת אלקות באמרו בא\"ה שיתברך ויומשך כל צרכי האדם בי\"ב אמצעית שאדם שואל בהם צרכיו כו', ע\"י שמקדים תחלה ג' ברכות ראשוני'<sup data-n=\"1632\">112</sup>,",[["1616","96","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["1617","97","<b>השרפי' אומרים קדוש ג\"פ</b>: ישעי' ו, ג. ברכת יוצר. ראה חולין צא, ב. ובתוד\"ה ברוך (שם צב, רע\"א)."],["1618","98","<b>והאופנים. . ברוך</b>: יחזקאל ג, יב. ברכת יוצר. ראה חולין צב, רע\"א ובתוד\"ה ברוך. ראה גם סה\"מ תרל\"ד ע' רנד."],["1619","99","<b>ההפרש שביניהם שהשרפים. . להתעלות והאופנים. . שיומשך להם</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ג."],["1620","100","<b>ממקומו ממקורו ושרשו</b>: ראה גם לעיל המשך זאת חנוכת המזבח שם ספ\"ז ובהערה 126."],["1621","101","<b>ברוך כבוד ה' ממקומו ר\"ת בכי\"ם</b>: ראה ע\"ח שער הכללים פ\"ב. כנפי יונה ח\"ב ס\"ב. עשרה מאמרות הובא בשל\"ה תורה שבכתב צאן יוסף ש, ב. עמה\"מ שער קרית ארבע שי\"ד, פ\"ה (פב, א)."],["1622","102","<b>ב' נפשות</b>: ראה תניא פ\"א."],["1623","103","<b>הנה\"א היא חלק אלק' ממעל</b>: ראה איוב לא, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 395."],["1624","104","<b>והנה\"ב היא משמרי האופנים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380083\" data-slug=\"likkutei-torah\" data-id=\"4001380083\">לקו\"ת ויקרא ב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381021\" data-slug=\"likkutei-torah\" data-id=\"4001381021\">האזינו עד, ג</a>."],["1625","105","<b>ועיקר ירידת הנשמה. . בירור נה\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370136\" data-slug=\"torah-or\" data-id=\"3901370136\">תו\"א וישב כט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381021\" data-slug=\"likkutei-torah\" data-id=\"4001381021\">לקו\"ת האזינו עד, ג</a>."],["1626","106","<b>שנה\"ב שבאדם. . מפני שור שבפני אדם</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רז. וראה גם סה\"מ תרכ\"ט ע' קכח."],["1627","107","<b>שנה\"ב שבאדם. . מפני אדם שבפני שור</b>: ראה גם שערי אורה ח, א הערה 15. סה\"מ תרל\"ח ע' לט. וש\"נ."],["1628","108","<b>ולכן. . ולכן</b>: בהמשך יונתי הנדפס: לכן. . לכן."],["1629","109","<b>מס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["1630","110","<b>מס\"נ באחד ובשכמל\"ו. . דנה\"א ונה\"ב</b>: ראה סה\"מ תרכ\"ט ע' רז ואילך ובהנסמן בריש המאמר שם."],["1631","111","<b>ח\"י ברכאן דצלותא</b>: זהר בראשית כו, א."],["1632","112","<b>ראשוני'</b>: בהמשך יונתי הנדפס: ראשונות."]]],[2000480217,"ובכלל הוא בחי' היחוד עליון עד שבשים שלום נמשך הטפה<sup data-n=\"1633\">113</sup> כנודע כו', וכלליות ענין התפלה היא במקום תמידין<sup data-n=\"1634\">114</sup> שהוא במקום קרבן צבור שעולה ונכלל כו' כנ\"ל באריכות, כ\"ה עכשיו העבודה שבלב זו תפלה<sup data-n=\"1635\">115</sup> להעלות נפשו הבהמית שתוכלל למעלה מעלה כמו הקרבן, וה\"ז נעשה ג\"כ יסוד על מזבח הפנימי, והיינו שהאפר<sup data-n=\"1636\">116</sup> דנפשו הבהמית פי' מה שמבטל נפשו מכל וכל עד שנעשה בבחי' עפר ואפר ממש, וזהו שאומרים אחר סיום שמ\"ע ונפשי כעפר<sup data-n=\"1637\">117</sup> לכל תהי' שזהו בחי' העפר דוגמת האפר דאיל של יצחק, כך ע\"י שנשרף נפשו בשלהובא דרחימותא<sup data-n=\"1638\">118</sup> נעשה יסוד על מזבח הפנימי כו'.\n<b></b>קיצור. שעכשיו תפלה כנגד תמידין, תרה\"ד ז\"ע תיקון חצות, ובתפלה ד' שליבות לעלות עד השמימה גם בחי' שמי השמים בכלל עד שאו' ונפשי כעפר לכל תהי' שזהו בחי' האפר דאילו ש\"י שהוא יסוד מזה\"פ.",[["1633","113","<b>שבשים שלום נמשך הטפה</b>: ראה פע\"ח שער העמידה ש\"ט, פ\"כ."],["1634","114","<b>התפלה היא במקום תמידין</b>: ראה ברכות כו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380630\" data-slug=\"likkutei-torah\" data-id=\"4001380630\">לקו\"ת פינחס עז, ג</a>."],["1635","115","<b>העבודה שבלב זו תפלה</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א. רמב\"ם ריש הלכות תפלה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450608\" data-slug=\"or-hatorah-hb\" data-id=\"8316450608\">אוה\"ת עקב ע' תרח</a>."],["1636","116","<b>שהאפר</b>: בהמשך יונתי הנדפס: שהעפר."],["1637","117","<b>שאומרים אחר סיום שמו\"ע</b>: ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 135 ואילך."],["1638","118","<b>בשלהובא דרחימותא</b>: זהר קדושים פד, א."]]],[2000480218,"<h3>[ואהבת את ה' אלקיך] ולהבין כו' מזה\"פ כו'</h3>\n<b>בס\"ד פ' וירא</b>\n<b></b>עשר ולא י\"א כו' ענן סוכה כו' מזה\"פ, החיצון כו' קטרת, ריח, צדקה - ב' קיצורים\nוירא\n<b>ולהבין</b> שרש ענין בחי' מזבח הפנימי<sup data-n=\"1639\">1</sup> שכל העבודה בקרבנות זהו רק יסוד לבחי' מזבח זו הפנימי, מהו מעלת מזבח זו שכל העבודה של מזבח החיצון הוא רק יסוד למזבח זו, הענין הוא שעל מזבח הפנימי היו מקטירין קטרת<sup data-n=\"1640\">2</sup>, וצ\"ל שרש ענין בחי' הקטרת שהם י\"א סממני הקטרת<sup data-n=\"1641\">3</sup>, שצ\"ל מהו ענין מספר זה די\"א שבקדושה הוא רק עשר לבד, ודוקא עשר כמ\"ש בס\"י עשר ולא תשע עשר ולא אחד",[["1639","1","<b>ולהבין שרש ענין בחי' מזבח הפנימי</b>: בס' התולדות של כ\"ק אדמו\"ר מהר\"ש (קה\"ת תש\"ז ע' 53) נרשם אודות מאמר זה: עשר ולא י\"א כו' ענן, סוכה כו' מזה\"פ, החיצון כו' קטרת, ריח, צדקה — ב' קיצורים.\nלהתחלת המאמר ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370094\" data-slug=\"torah-or\" data-id=\"3901370094\">תו\"א תולדות כ, סע\"ב</a> ואילך.\nמאמר זה הובא בסה\"מ מלוקט ב' ע' קכא־ ע' קכב־ ע' קכד.\nהנחת<sup data-n=\"e162\">א</sup> כ\"ק אדמו\"ר מהורש\"ב<sup data-n=\"e163\">ב</sup> מדרוש זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחה ואהבת את ה' אלקיך."],["1640","2","<b>מזבח הפנימי היו מקטירין קטרת</b>: ראה תצוה ל, א. ז. ח. סהמ\"צ להרמב\"ם מ\"ע כח. רמב\"ם הל' כלי המקדש פ\"א, הי\"א. הל' תמידין ומוספין רפ\"ג."],["1641","3","<b>י\"א סממני הקטרת</b>: ראה תשא ל, לד. כריתות ו, א.\n\n<b>א</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>ב</b>  רק שורות אחדות."]]],[2000480219,"עשר<sup data-n=\"1642\">4</sup>, ומדוע בקטרת מספר סממני הקטרת הם י\"א דוקא. והענין הוא דבסט\"א הוא י\"א דוקא שז\"ע שבסט\"א הם י\"א כתרין<sup data-n=\"1643\">6</sup> דמסאבותא<sup data-n=\"1644\">5</sup>, שלכאו' מאין ניתוסף אצלם להיות י\"א כתרין מה שבקדושה הוא רק עשר כתרין<sup data-n=\"1645\">7</sup>, אך באמת כל המוסיף גורע<sup data-n=\"1646\">8</sup>, והענין הוא שבקדושה הנה החיות שמחי' הע\"ס הוא בתכלית היחוד עם הספירות<sup data-n=\"1647\">9</sup>, וכמ\"ש בת\"ז במא' פתח אליהו וההוא נביעו איהו כנשמתא לגופא דאיהו חיים לגופא<sup data-n=\"1648\">10</sup> שבחי' נביעו זו<sup data-n=\"1649\">11</sup> לא נחשב בפ\"ע כמו שבנפש האדם שהנשמה מחי' את הגוף, שעם היות שבעצם הנה הנשמה והגוף שני דברים &lt;55&gt;\nּ הם שהם מרוחקי' זמ\"ז בתכלית הריחוק עכ\"ז כל עת וזמן שהנשמה מלובשת בגוף א\"א לחשוב את הנשמה לדבר בפ\"ע והגוף לדבר בפ\"ע כ\"א ששניהם נק' אדם<sup data-n=\"1650\">12</sup>, משא\"כ הגוף בפ\"ע נק' גוף האדם כו', וכן הנשמה בפ\"ע נק' נשמת האדם להורות שכל א' בפ\"ע אינו דבר שלם ובהתכללותם יחד נק' אדם כו', ועד\"ז יובן בבחי' אדם דאצי' שבחי' חסד דרועא ימינא זהו מבחי' גוף האדם וכן גבורה דרועא שמאלא ועד\"ז נו\"ה תרין שוקין<sup data-n=\"1651\">13</sup>, והגם כי באמת אין לו דמות הגוף<sup data-n=\"1652\">14</sup> ולא גוף, אך באמת זהו שנא' ועל דמות הכסא<sup data-n=\"1653\">15</sup> דמות כמראה אדם, שענין כמראה אדם מובן פירושו שהוא כמראה אדם ולא אדם בפו\"מ, וכן ענין אומרו דמות זהו ג\"כ שאינו עצם כו', ובכלל קאי זה על בחי' רמ\"ח פקודין שהן הן רמ\"ח אברים דמלכא<sup data-n=\"1654\">16</sup>, כמו שהאבר הוא כלי לגילוי חיות הנפש כן רמ\"ח מ\"ע הם פרטי כלים להשראת אוא\"ס ב\"ה כו', וזהו עד\"מ בחי' גוף דאדם העליון, אבל החיות זהו ההוא נביעו שאיהו כנשמתא ענין אומרו כנשמתא הוא כדי לשלול שאינה כמו נשמתא ממש אלא שזהו כמו שהנשמה מחי' הגוף כן בחי' זו זהו מה שנמשך מבחי' והחכ' תחי'<sup data-n=\"1655\">17</sup> להחיות הע\"ס דז\"א שנק' בשם אדם<sup data-n=\"1656\">18</sup> כו', ועם היות שזהו אור וזהו כלי עכ\"ז אין לחלק ביניהם כלל, והוא מפני שהכלי ג\"כ בטל לאלקות וכמשנ\"ת",[["1642","4","<b>בס\"י עשר. . ולא אחד עשר</b>: פ\"א, מ\"ד<sup data-n=\"e164\">ג</sup>. זהר רע\"מ תשא קפז, ב. פרדס שער עשר ולא תשע ש\"א, פ\"ו."],["1643","6","<b>כתרין דמסאבותא</b>: ראה זהר סבא משפטים צד, ב. שמיני מא, ב. אחרי ע, א. אד\"ר נשא קמג, סע\"א וריש ע\"ב."],["1644","5","<b>י\"א כתרין דמסאבותא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380399\" data-slug=\"likkutei-torah\" data-id=\"4001380399\">לקו\"ת נשא כב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381170\" data-slug=\"likkutei-torah\" data-id=\"4001381170\">שה\"ש י, ב</a>. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך הערה 125."],["1645","7","<b>שבקדושה הוא רק עשר כתרין</b>: הלשון כתרין על ספירות דקדושה — ראה זהר אחרי ע, א ובהגהות מהרח\"ו אות ב."],["1646","8","<b>כל המוסיף גורע</b>: סנהדרין כט, סע\"א. זהר פקודי רלג, ב."],["1647","9","<b>שבקדושה הנה החיות. . הספירות</b>: ראה תו\"א שבהערה 1."],["1648","10","<b>בת\"ז. . וההוא נביעו. . דאיהו חיים לגופא</b>: בהקדמה יז, א [ושם: דאיהי]."],["1649","11","<b>זו</b>: בהמשך יונתי הנדפס: ליתא."],["1650","12","<b>הנשמה והגוף. . ששניהם נק' אדם</b>: ראה גם סה\"מ תרל\"ח ע' שכב ובהערה 64. סה\"מ תרס\"ח ע' רלד. פלח הרמון אמור ע' שטו."],["1651","13","<b>חסד דרועא ימינא. . שמאלא. . שוקין</b>: ת\"ז בהקדמה שם."],["1652","14","<b>אין לו דמות הגוף</b>: ע\"פ פיוט יגדל. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערה 31."],["1653","15","<b>ועל דמות הכסא</b>: יחזקאל א, כו."],["1654","16","<b>רמ\"ח פקודין שהן הן רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["1655","17","<b>והחכ' תחי'</b>: נסמן לקמן בהערה 149."],["1656","18","<b>דז\"א שנק' בשם אדם</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ה. ראה גם ש\"א לא, ב.\n\n<b>ג</b>  ושם: אחת עשרה. במהדורת מנטובא שכ\"ב [שם, מ\"ג]: אחד עשר."]]],[2000480220,"בד\"ה להבין ענין מקיפים דבינה<sup data-n=\"1657\">19</sup> בענין איהו וגרמוהי<sup data-n=\"1658\">20</sup> שזהו בחי' הגבול שבא\"ס, לכן האור והחיות הנמשך מאתו ית' מתאחד עמהם ביחוד גמור עד שהם ד\"א ממש, והגם כי באמת איהו וחיוהי חד ואיהו וגרמוהי חד נא' ב\"פ חד<sup data-n=\"1659\">21</sup> להורות שהיחוד שבחי' איהו אשר מתייחד עם בחי' חיוהי הוא חד בא\"א ממש מכמו בחי' האיהו שמתייחד עם גרמוהי, וגם בחי' האיהו אינו בחי' ומדריגה זו עצמו דבחי' האיהו שמתייחד עם גרמוהי<sup data-n=\"1660\">22</sup> כו' כמ\"ש מזה במ\"א, עכ\"ז חיוהי וגרמוהי שניהם קרוים שם אחד כמראה אדם כו', שזהו לפי שכלי המדות בטלים בתכלית לאוא\"ס שלכן המשכת אוא\"ס שנמשך בהם מתאחד עמהם בתכלית היחוד כו', ועוי\"ל שענין יחוד חיות הקדושה בע\"ס זהו עד\"מ כמו יחוד הנפש עם עשר בחינותי' שכל ומדות, ולכן עשר ולא אחד עשר, ומשל זה הוא עיקר יותר, ועכ\"ז לענין שלפנינו מובן יותר ממשל הגוף עם הנפש, ובאמת ענינם אחד הוא שהרי בענין ההפרש בין שכל ומדות, וג' לבושי' מחדו\"מ נת' המשל ע\"ז מההפרש בין גופין ללבושי' בד\"ה אוא\"ס למעלה עד אין קץ<sup data-n=\"1661\">23</sup>, שעם היות שהגוף הוא ג\"כ לבוש כו', עכ\"ז בע\"כ אתה חי<sup data-n=\"1662\">24</sup>, וא\"י לפושטו, ולכן אינו דומה ללבושי' הנ\"ל שהם משל על בי\"ע, משא\"כ וכמה גופין תקינת לון<sup data-n=\"1663\">25</sup> זהו באצי' שההיא נביעא איהי כנשמתא לגופא כו', ואמנם בסט\"א שנק' סט\"א ע\"ש בחי' הגסות והגסות<sup data-n=\"1664\">*26</sup> שבהם שהם יש ודבר נפרד לגמרי, וכמו פרעה שא' לי יאורי ואני עשיתני<sup data-n=\"1665\">26</sup> שזהו תכלית ההסתר שעי\"ז הוא הגסות שבהם עד שאמר מי הוי', לא ידעתי את הוי'<sup data-n=\"1666\">27</sup>, והנה גם בחי' זו בהכרח שיומשך להם חיות מאוא\"ס &lt;56&gt;\nּ שאל\"כ לא היו שום מציאות כלל, וכמ\"ש ואתה מחי' את כולם<sup data-n=\"1667\">28</sup> אפי' סט\"א וקלי' מגקה\"ט לגמרי, רק שאם חיותם הי' נמשך להם בקירוב הי' נבלע בהם<sup data-n=\"1668\">29</sup> כמ\"ש נבלע ישראל<sup data-n=\"1669\">30</sup> כו', ולכן בכדי שלא יובלע בהם חיות הקדושה עומד החיות המחי' אותם בבחי' מקיף מלמעלה ע\"ג, וזהו מספר י\"א כתרין שהוא בחי' יו\"ד כתרין והי\"א הוא בחי' מקיף דלבונה זכה שנק' בשם לבונה זכה ע\"ש שהיא עדיין זכה לגמרי<sup data-n=\"1670\">31</sup> אלא שממנה נמשך חיות להיו\"ד כתרין ולכן הם י\"א, וזהו ג\"כ ענין י\"א ארורי'<sup data-n=\"1671\">32</sup> וי\"א יריעות<sup data-n=\"1672\">33</sup>, ושרש",[["1657","19","<b>וכמשנ\"ת בד\"ה להבין ענין מקיפים דבינה</b>: נדפס לעיל — ראה שם פ\"ד."],["1658","20","<b>איהו וגרמוהי</b>: נסמן בהערה הבאה."],["1659","21","<b>איהו וחיוהי. . וגרמוהי. . ב\"פ חד</b>: ראה ת\"ז בהקדמה ג, ב. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 99."],["1660","22","<b>וגם בחי' האיהו. . עם גרמוהי</b>: ראה לעיל המשך יונתי פ\"ט ופ\"י."],["1661","23","<b>בד\"ה אוא\"ס למעלה עד אין קץ</b>: ראה אוה\"ת על ענינים ע' קיג אילך (ובהנסמן בריש המאמר שם). ע' קמג ואילך."],["1662","24","<b>בע\"כ אתה חי</b>: ראה אבות ספ\"ד."],["1663","25","<b>וכמה גופין תקינת לון</b>: ת\"ז בהקדמה שם."],["1664","*26","<b>הגסות והגסות</b>: כ\"ה גם בהמשך יונתי הנדפס."],["1665","26","<b>לי יאורי ואני עשיתני</b>: יחזקאל כט, ג."],["1666","27","<b>מי הוי' לא ידעתי את הוי'</b>: שמות ה, ב [בדילוג]."],["1667","28","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["1668","29","<b>חיותם הי'. . נבלע בהם</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ז. וש\"נ."],["1669","30","<b>נבלע ישראל</b>: הושע ח, ח."],["1670","31","<b>לבונה זכה. . זכה לגמרי</b>: ראה גם לעיל המשך זאת חנוכת המזבח שם ובהנסמן שם."],["1671","32","<b>י\"א ארורי'</b>: תבוא כז, טו ואילך. ראה מאמרי אדה\"ז תקס\"ז ע' שלד. ע\"ח שבהערה הבאה. הנסמן במאמרי אדה\"א קונטרסים ע' שמב."],["1672","33","<b>וי\"א יריעות</b>: ראה מאמרי אדה\"ז שם. ע\"ח שער המלכים שי\"א, פ\"י."]]],[2000480221,"ענין הקטרת הוא בכדי להעלות ולברר י\"א כתרין דמסאבותא כו', והנה עבודת הקטרת הי' שהי' הכהן נוטל גחלים מע\"ג המזבח<sup data-n=\"1673\">34</sup> ונתן את הקטרת ע\"ג הגחלים<sup data-n=\"1674\">35</sup> עד שהי' מתמלא כל הבית כולו עשן<sup data-n=\"1675\">36</sup>, והענין הוא כי הנה כל דבר מורכב מד\"י<sup data-n=\"1676\">37</sup> ארמ\"ע<sup data-n=\"1677\">38</sup>, וע\"י ששורף הדבר המעורב מד\"י הנה ג\"י אמ\"ר יוצאין בעשן<sup data-n=\"1678\">39</sup> ויסוד העפר זהו האפר הנשאר כו' ונמצא מובן שהאפר מאילו ש\"י שנעשה יסוד מזה\"פ זהו מה שנשאר אחר כל בחי' הבירור דקרבנות שאחר שנשרף והג\"י יצאו בעשן נשאר האפר וממנו הוא יסוד מזה\"פ שעליו הקטירו קטרת שצ\"ל שענין העשן מהקטרת זהו בירור היותר נעלה, ובעבודה ענין הקטרת<sup data-n=\"1679\">41</sup> הוא בחי' ההתקשרות כמ\"ש בזהר על רשב\"י בחד קטירא אתקטרנא<sup data-n=\"1680\">42</sup> כו' שהוא התקשרות גדולה וחזקה מאד כו', והתקשרות זו הוא בלתי הרגש כלל כ\"א מעוצם הביטול<sup data-n=\"1681\">40</sup> הוא מקושר ודבוק בה' אחד כו', וע\"י התקשרות כזו יוכל להעלות גם מבחי' י\"א כתרין דמסאבותא ע\"ד ומעין שיהי' לע\"ל דכתי' ומעיין מבית ה' יוצא<sup data-n=\"1682\">43</sup> והשקה את נחל השטים כמשנ\"ת מזה במ\"א, ע' בלק\"ת בד\"ה ששים המה מלכות<sup data-n=\"1683\">44</sup>, רק שזהו מלמטלמ\"ע וזהו מלמעלמ\"ט, ומבחי' ענן הקטרת<sup data-n=\"1684\">45</sup> זו נעשה מקיפי' דסוכה<sup data-n=\"1685\">46</sup> זכר לענני כבוד<sup data-n=\"1686\">47</sup> וכמ\"ש פרש ענן למסך<sup data-n=\"1687\">48</sup>, ופרוש עלינו סוכת שלומך<sup data-n=\"1688\">49</sup>, וזהו אני לדודי ועלי תשוקתו פי' כשאני לדודי בבחי' התקשרות בחד קטירא אתקטרנא בי' אחידא<sup data-n=\"1689\">51</sup> כו' אז מאיר ומתגלה מלמעלה להיות עלי תשוקתו, פי' עלי הוא בבחי' מקיף<sup data-n=\"1690\">50</sup> והיינו מקיפי' דסוכה שנמשך מענן הקטרת הוא בחי' התשובה דיוכ\"פ, וזהו שארז\"ל במד\"ר בד' תשוקות<sup data-n=\"1691\">52</sup>, תשוקת הקב\"ה על",[["1673","34","<b>הכהן נוטל גחלים מע\"ג המזבח</b>: ראה רמב\"ם הל' תמידין ומוספין פ\"ג, ה\"ה."],["1674","35","<b>ונתן את הקטרת ע\"ג הגחלים</b>: ראה שם ה\"ז וה\"ח שצובר את הגחלים ע\"ג המזבח. . ומשליך הקטרת על האש."],["1675","36","<b>ונתן את הקטרת ע\"ג הגחלים. . כולו עשן</b>: ראה רמב\"ם הל' עבודת יוה\"כ פ\"ד, סה\"א."],["1676","37","<b>כל דבר מורכב מד\"י</b>: ראה רמב\"ם רפ\"ד מהל' יסוה\"ת."],["1677","38","<b>מד\"י ארמ\"ע</b>: ראה שה\"א סו, א ובהערה 17. סה\"מ תרכ\"ט ע' קעט. וש\"נ. תרל\"ח ע' תצא."],["1678","39","<b>ג\"י אמ\"ר יוצאין בעשן</b>: ראה גם אגה\"ק סט\"ו. סה\"מ תרל\"ח ע' רצו. וש\"נ."],["1679","41","<b>הקטרת. . ההתקשרות</b>: ראה גם לקמן בפיסקא הבאה ובהערה 86 ואילך."],["1680","42","<b>בחד קטירא אתקטרנא</b>: ראה זהר אד\"ז האזינו רפח, א. סידור ערב שבת קסג, א. שע\"ת נד, ד ובהערה 44. לקמן הערה 51."],["1681","40","<b>הקטרת. . בלתי הרגש. . הביטול</b>: ראה סה\"מ מלוקט ב' ע' קכא וע' קכב."],["1682","43","<b>ומעיין מבית ה' יוצא</b>: יואל ד, יח."],["1683","44","<b>ומעיין. . בלק\"ת בד\"ה ששים המה מלכות</b>: שה\"ש לט, א ואילך."],["1684","45","<b>ענן הקטרת</b>: אחרי טז, יג."],["1685","46","<b>ענן. . מקיפי' דסוכה</b>: ראה גם עט\"ר כח, א. לו, סע\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670572\" data-slug=\"torat-chaim\" data-id=\"2300670572\">תו\"ח נח נח</a>, א ובהערה 16. סה\"מ מלוקט ב' ע' קכא. וש\"נ. לעיל מאמר ד\"ה סוכה שחמתה מרובה מצלתה על יד הערה 34."],["1686","47","<b>דסוכה זכר לענני כבוד</b>: ראה שו\"ע אדה\"ז הל' סוכה סתרכ\"ה. סה\"מ מלוקט שם. וש\"נ."],["1687","48","<b>פרש ענן למסך</b>: תהלים קה, לט. ראה ב\"ר פמ\"ח, י."],["1688","49","<b>ופרוש עלינו סוכת שלומך</b>: נוסח ברכת השכיבנו."],["1689","51","<b>בחד קטירא. . אחידא</b>: ראה זהר אד\"ז האזינו רפח, א. רצב, א. מאמרי אדה\"א שמות ח\"ב ע' שכט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670207\" data-slug=\"torat-chaim\" data-id=\"2300670207\">תו\"ח לך צו, א</a> ובהערה 3. שער האמונה צח, ב. סה\"מ מלוקט ג' ע' קנא ואילך."],["1690","50","<b>אני לדודי ועלי תשוקתו. . מקיף</b>: שה\"ש ז, יא. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380852\" data-slug=\"likkutei-torah\" data-id=\"4001380852\">לקו\"ת פ' ראה לד, ב</a>. לעיל המשך יונתי רפי\"ט ובהערה 435."],["1691","52","<b>במד\"ר בד' תשוקות</b>: ראה ב\"ר פ\"כ, ז (הובא לעיל שם)."]]],[2000480222,"ישראל, דהנה בענן הקטרת נא' כי בענן אראה<sup data-n=\"1692\">53</sup>, ולא אמר מי הוא אשר נראה בענן אלא אראה שקאי על בחי' אוא\"ס ב\"ה עצמותו ומהותו, ומבחי' זו נשתוקק על ישראל להגלות על ישראל בחה\"ס בבחי' מקיף מלמעלה, ולכן מצות סוכה צ\"ל צלתה מרובה מחמתה<sup data-n=\"1693\">54</sup>, שחמתה מרובה מצלתה פסולה<sup data-n=\"1694\">55</sup>, כי חמה זהו מורה על בחי' תוקף החום מבחי' שלהובא דרחימותא<sup data-n=\"1695\">57</sup> שבחי' זו שייך בבחי' העבודה דקרבנות<sup data-n=\"1696\">56</sup>, אבל סוכה זהו מה שמתברר מעשן הקטרת שבבחי'<sup data-n=\"1697\">58</sup> זו אינו שייך ההרגש דחמימות כ\"א התקשרות ודביקות באוא\"ס ב\"ה לדבקה בו בלי שום הרגש כלל וכלל כ\"א בבחי' ביטול לבד כו', ומבחי' מקיף זה שבסוכות מאיר בשמע\"צ בבחי' פנימיות כו'.\n<b></b>קיצור. בקטרת י\"א סממנין נגד י\"א כתרין, שבקדושה יו\"ד שהחיות מחי' אותם בפנימיות, &lt;57&gt;\nּ משא\"כ בסט\"א בפנימיות הי' נבלע, ולכן מחי' בבחי' מקיף, וזהו מקיף דלבונה שהיא זכה עדיין כו', ומהענן של הקטרת נעשה המקיף דסוכה שהוא זכר לענני כבוד, ומה שבענן אראה מאיר בסוכות בבחי' מקיף, ולכן צ\"ל צלתה מרובה בחי' ישת חשך סתרו<sup data-n=\"1698\">59</sup>, ובשמע\"צ מאיר בבחי' פנימיות כו'.\nוהנה בכדי להבין שרש ההפרש בין מזבח הפנימי למזבח החיצון, צ\"ל שרש ההפרש בין קרבנות לעבודת הקטרת הקטורת, דהנה בזח\"ב ס\"פ<sup data-n=\"1699\">60</sup> ויקהל דרי\"ט סע\"א איתא וז\"ל ת\"ח מה בין צלותא לעובדא דקטרת צלותא אתקינו לה באתר דקורבנין<sup data-n=\"1700\">61</sup> דהוו עבדי ישראל, וכל אינון קורבין<sup data-n=\"1701\">62</sup> דהוו עבדין ישראל לאו אינון חשיבין כקטרת<sup data-n=\"1702\">63</sup>, ותו כו'<sup data-n=\"1703\">64</sup> קטרת עביד יתיר מתקן<sup data-n=\"1704\">65</sup> וקשיר קשרין כו' דאעבר זוהמא ואדכי<sup data-n=\"1705\">66</sup> משכנא כו' ד' אתעביד ה'<sup data-n=\"1706\">67</sup> כו' סליק<sup data-n=\"1707\">68</sup> רעותא לאין סוף כו' עכ\"ל. ובזהר\"ק שם האריך בזה, ותוכן<sup data-n=\"1708\">69</sup> הענין כי המל' דעשיי' הוא<sup data-n=\"1709\">70</sup> בעמקי הקלי' כו' ומחי' אותם כו', ואין הבחי' זו יכולה לצאת מבין הקלי' עד שיבא זמן הכתוב בלע המות לנצח<sup data-n=\"1710\">71</sup> כו', והנה כ\"ז שאין בחי' זו עולה למעלה, נראה ח\"ו כמו בחי'",[["1692","53","<b>כי בענן אראה</b>: אחרי טז, ב. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'קלד. עט\"ר ע' כט. מאמר ד\"ה סוכה שחמתה מרובה מצלתה ב' דסוכות תשי\"ד."],["1693","54","<b>צלתה מרובה מחמתה</b>: סוכה כב, א (במשנה). סה\"מ מלוקט ב' ע' קכא. וש\"נ."],["1694","55","<b>שחמתה מרובה מצלתה פסולה</b>: סוכה ב, א (במשנה)."],["1695","57","<b>שלהובא דרחימותא</b>: זהר קדושים פד, א."],["1696","56","<b>חמה. . החום. . העבודה דקרבנות</b>: ראה גם לעיל מאמר ד\"ה סוכה שחמתה מרובה מצלתה סוף פיסקא א. סה\"מ מלוקט ב' ע' קכא וע' קכב."],["1697","58","<b>שבבחי'</b>: בהמשך יונתי הנדפס: שבחי'."],["1698","59","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["1699","60","<b>ס\"פ</b>: מכאן ועד התיבות דלקמן: ”קשר כו'\" הוא לשון הצ\"צ ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316500152\" data-slug=\"or-hatorah-hb\" data-id=\"8316500152\">אוה\"ת תולדות ח\"א ע' קנב</a> ואילך (בשינויים קלים)."],["1700","61","<b>דקורבנין</b>: בזהר ואוה\"ת: דקרבנין."],["1701","62","<b>קורבין</b>: בזהר: קרבנין. באוה\"ת: קורבנין."],["1702","63","<b>כקטרת</b>: באוה\"ת: כקטורת. בזהר: כבפנים."],["1703","64","<b>כו'</b>: וכ\"ה באוה\"ת. בהמשך יונתי הנדפס: כל."],["1704","65","<b>מתקן</b>: בזהר ובאוה\"ת: מתקין."],["1705","66","<b>ואדכי</b>: שם: ואידכי."],["1706","67","<b>ד' אתעביד ה'</b>: זהר שם ע\"ב (בין חצאי עיגול)."],["1707","68","<b>סליק</b>: ב(זהר ו)אוה\"ת: וכ(ו)לא סליק."],["1708","69","<b>ותוכן</b>: באוה\"ת: ותוך."],["1709","70","<b>הוא</b>: באוה\"ת ובהמשך יונתי הנדפס: היא. בזהר\"ק: ליתא."],["1710","71","<b>בלע המות לנצח</b>: ישעי' כה, ח. בזהר\"ק: ובלע."]]],[2000480223,"פירוד ח\"ו בקדושה<sup data-n=\"1711\">72</sup>, וע\"י הקטרת עולה כו', משא\"כ בתפילה לעשות להעביר הזוהמא מבחי' זאת כו', ולכן אחר מעשה הקטרת אנו אומרים הודו כו' הודיעו בעמים כו' ע\"ש. ובפי'<sup data-n=\"1712\">73</sup> קשיר קשרין שא' בזהר י\"ל<sup data-n=\"1713\">74</sup> כי קשר הוא יסוד<sup data-n=\"1714\">75</sup> וה\"ע היחוד עליון וההתחברות עד א\"ס כמו מיסוד א\"ק נמשך במל' דא\"ק שהוא מל' דא\"ס<sup data-n=\"1715\">76</sup> להיות מתחברת באצי' שנעשית עתיק לאצי'<sup data-n=\"1716\">77</sup>, ועד\"ז הוא בזו\"נ דאצי' שבחי' המל' דאצי' נעשית עתיק לבריאה<sup data-n=\"1717\">78</sup>, וכמ\"ש במ\"א ע\"פ הזהר וישב דקפ\"א סע\"א<sup data-n=\"1718\">80</sup> בגין לקשרא קשרין לאנהרא<sup data-n=\"1719\">81</sup> נהורין<sup data-n=\"1720\">79</sup> כו', וע' בפרד\"ס<sup data-n=\"1721\">82</sup> ערך קשר<sup data-n=\"1722\">83</sup>, נמצא מובן איך ע\"י הכנעת החיצוני' ואכפייא<sup data-n=\"1723\">84</sup> סט\"א עי\"ז דוקא אסתלק יקרא דקוב\"ה, ועפ\"ז יובן ג\"כ ענין הנז' בזח\"א פ' חיי שרה דקך\"ב סע\"א ד\"א מלך דא אשה יראת ה'<sup data-n=\"1724\">85</sup> כו' עד דאתדכי ואתחבר לעילא כו', וז\"ע קטרת שהוא לשון קשר<sup data-n=\"1725\">86</sup> כי כל קשר שבפסוק מתורגם בלשון קטר<sup data-n=\"1726\">87</sup> כו' וקשרתם אותם לאות<sup data-n=\"1727\">88</sup>, מתרגמינן<sup data-n=\"1728\">89</sup> ותקטרון יתהון לאת<sup data-n=\"1729\">90</sup>, ותקשור על ידו<sup data-n=\"1730\">91</sup>, וקטירת<sup data-n=\"1731\">92</sup> על ידיה כו', ועם היות שבלשון תורה פי' קטרת היינו עשן כמ\"ש עלה קיטור הארץ<sup data-n=\"1732\">93</sup> כקיטור הכבשן, ותרגומו תננא דארעא כתננא דכבשנא<sup data-n=\"1733\">94</sup> כו' עכ\"ז י\"ל דהא בהא תלי' כי עשן הקטרת ז\"ע קשר והתחברות שעולה אתעדל\"ת והוא העשן להתחבר ולהמשיך אתעדל\"ע<sup data-n=\"1734\">95</sup>,",[["1711","72","<b>ח\"ו כמו בחי'. . ח\"ו בקדושה</b>: בזהר\"ק ובאוה\"ת: ליתא. . בקדושה ח\"ו."],["1712","73","<b>ובפי'</b>: בהמשך יונתי הנדפס מתחיל כאן קטע חדש."],["1713","74","<b>שא' בזהר י\"ל</b>: באוה\"ת: נלע\"ד."],["1714","75","<b>קשר הוא יסוד</b>: ראה זהר לך פט, א. פרדס שבהערה 83. מאו\"א מערכת קשר אות ה. וראה גם אגה\"ק סט\"ז (קכב, ב)."],["1715","76","<b>במל' דא\"ק שהוא מל' דא\"ס</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370245\" data-slug=\"torah-or\" data-id=\"3901370245\">תו\"א שמות נה, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541058\" data-slug=\"torat-chaim\" data-id=\"2300541058\">תו\"ח בשלח ח\"א רה, ב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316500152\" data-slug=\"or-hatorah-hb\" data-id=\"8316500152\">אוה\"ת תולדות ח\"א כאן ע' קנב</a>."],["1716","77","<b>במל' דא\"ק. . שנעשית עתיק לאצי'</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380705\" data-slug=\"likkutei-torah\" data-id=\"4001380705\">לקו\"ת מסעי צה, ב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830276\" data-slug=\"or-hatorah-hb\" data-id=\"8158830276\">אוה\"ת בלק ע' תתקסג</a>."],["1717","78","<b>המל' דאצי' נעשית עתיק לבריאה</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב."],["1718","80","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316500152\" data-slug=\"or-hatorah-hb\" data-id=\"8316500152\">סע\"א</a></b>: וכן צ\"ל באוה\"ת תולדות ח\"א כאן ע' קנב."],["1719","81","<b>לאנהרא</b>: בזהר ובאוה\"ת: ולאנהרא."],["1720","79","<b>וכמ\"ש במ\"א. . נהורין</b>: ראה ביאוה\"ז להצ\"צ כרך א ע' קכ ואילך."],["1721","82","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["1722","83","<b>בפרד\"ס ערך קשר</b>: שער עה\"כ שכ\"ג, פי\"ט."],["1723","84","<b>ואכפייא</b>: בהמשך יונתי הנדפס ובאוה\"ת: ואתכפייא."],["1724","85","<b>אשה יראת ה' </b>: משלי לא, ל."],["1725","86","<b>קטרת שהוא לשון קשר</b>: ראה בחיי שמיני י, א: ולשון קטרת התקשרות. זהר שמיני לז, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380399\" data-slug=\"likkutei-torah\" data-id=\"4001380399\">לקו\"ת נשא כב, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550246\" data-slug=\"torat-chaim\" data-id=\"2300550246\">תו\"ח תרומה ח\"ב שו, א</a> ובהערה 71. סה\"מ תרל\"ח ע' מו. וש\"נ. סה\"מ מלוקט ב' ע' קכב. לעיל מאמר ד\"ה סוכה שחמתה מרובה מצלתה על יד הערה 30."],["1726","87","<b>קטר</b>: בהמשך יונתי הנדפס: קטרת."],["1727","88","<b>וקשרתם אותם לאות</b>: עקב יא, יח."],["1728","89","<b>וקשרתם אותם לאות מתרגמינן</b>: באוה\"ת: וקשרתם לאות על ידיך — ואתחנן ו, ח. וראה הערה הבאה."],["1729","90","<b>ותקטרון יתהון לאת</b>: באוה\"ת: ותקטרינון יתהון לאת — חיבור התרגום דואתחנן ועקב. ראה הערות שלפנ\"ז."],["1730","91","<b>ותקשור על ידו</b>: וישב לח, כח. באוה\"ת: ותקשור שני על ידו [ובוישב שם: ידו שני]. פסוק זה הובא גם בבחיי שבהערה 86."],["1731","92","<b>וקטירת</b>: בתרגום־ בבחיי ובאוה\"ת: וקטרת."],["1732","93","<b>עלה קיטור הארץ</b>: וירא יט, כח. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370422\" data-slug=\"torah-or\" data-id=\"3901370422\">תו\"א מג\"א צד, א</a>."],["1733","94","<b>דכבשנא</b>: באוה\"ת: דכבשונא. בתרגום: דאתונא."],["1734","95","<b>אתעדל\"ת. . אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a> ובהערה 189."]]],[2000480224,"וכמו העשן העולה מהנר שכבה<sup data-n=\"1735\">96</sup> כשיקריב אותו סמוך לנר הדולק יגרום ירידת האש מהנר הדולק להדליק הנר שכבה כו', וע' בזח\"א נח ד\"ע ע\"א גבי דהא לית תננא בלא אשא כמד\"א<sup data-n=\"1736\">97</sup> וה\"ס עשן כולו<sup data-n=\"1737\">98</sup> מפני אשר ירד עליו ה' באש, וזהו שנק' ג\"כ קטרת לשון קשר כו'<sup data-n=\"1738\">99</sup>. והיוצא מזה שבקטרת יש העלא' והמשכה שע\"י העלאת העשן מלמטלמ\"ע, עי\"ז נמשך &lt;58&gt;\nּ מלמעלמ\"ט המשכת אוא\"ס מלמעלה מהאצי' שיומשך באצי' וז\"ע קשיר קשרין כו', ולשון קשרין שהוא ל' רבים י\"ל שזהו ההתקשרות בי\"ע באצי' ואצילות בלמעלה מאצי', ועכשיו בעבודה ענין בחי' הקטרת בכלל זהו בחי' ובכל<sup data-n=\"1739\">100</sup> מאדך<sup data-n=\"1740\">101</sup> שפי' רז\"ל במשנה ספב\"ת דברכות בכל ממונך<sup data-n=\"1741\">102</sup>, והוא בחי' הצדקה שהפליגו רז\"ל במאד מאד במעלת הצדקה ואמרו ששקולה כנגד כל המצות<sup data-n=\"1742\">104</sup> ובכל תלמוד ירושלמי<sup data-n=\"1743\">106</sup> ה\"ה<sup data-n=\"1744\">108</sup> נק' בשם מצוה<sup data-n=\"1745\">107</sup> סתם<sup data-n=\"1746\">105</sup> כי כך הי' הרגל הלשון לקרוא צדקה בשם מצוה סתם מפני שהיא עיקר המצות מעשיות ועולה על כולנה<sup data-n=\"1747\">103</sup>, וכמ\"ש וצדקה תהי' לנו<sup data-n=\"1748\">109</sup> כי נשמור לעשות את כל המצוה, שנמשלו כל המצות במצות צדקה, וכלליות כל המצות ה\"ה נתלבשו בעשיי' הגשמיות שהן הן כמו בחי' הקטרת שנעשית מסממנים שאין בהם טעם, ואינם ממין מאכל, ומהם נעשה בחי' ריח העולה למעלה לחזק את המוח ולהשיב את הנפש שראשית גילוי כלליות הנפש הוא במוחין שבראש ופעולת הריח היא שלא תהי' הנפש בבחי' הסתלקות מן המוחין, רק שתשוב ותתגלה מהעלם אל הגילוי, וכך הו\"ע המצות שע\"י נמשך בחי' ריח, כמ\"ש וירח את ריח בגדיו",[["1735","96","<b>העשן העולה מהנר שכבה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 478."],["1736","97","<b>כמד\"א</b>: באוה\"ת: כמ\"ד. בזהר: כמה דכתיב."],["1737","98","<b>וה\"ס עשן כולו</b>: יתרו יט, יח."],["1738","99","<b>קשר כו'</b>: ע\"כ הוא לשון הצ\"צ ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316500152\" data-slug=\"or-hatorah-hb\" data-id=\"8316500152\">אוה\"ת תולדות ח\"א ע' קנב</a> ואילך (בשינויים קלים). ראה לעיל הערה 60."],["1739","100","<b>ובכל מאדך</b>: ואתחנן ו, ה."],["1740","101","<b>ובכל מאדך. . הו\"ע המצות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370137\" data-slug=\"torah-or\" data-id=\"3901370137\">תו\"א וישב כט, ג</a> בשינויים והוספות."],["1741","102","<b>במשנה ספב\"ת דברכות בכל ממונך</b>: ברכות נד, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a> ואילך<sup data-n=\"e165\">ד</sup>. מאמרי אדה\"ז תק\"ע ע' קכח. סהמ\"צ להצ\"צ קלט, ב. ש\"א יא, א ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450572\" data-slug=\"or-hatorah-hb\" data-id=\"8316450572\">אוה\"ת חנוכה ח\"ב ע' 572</a><sup data-n=\"e166\">ה</sup>. לקמן מאמר ד\"ה עשה צדקה ומשפט על יד הערה 20. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 5. ד\"ה עשה צדקה ומשפט על יד הערה 25. סביבות הערה 128. פלח הרמון בחוקותי ע' תפא."],["1742","104","<b>הצדקה. . ששקולה כנגד כל המצות</b>: ב\"ב ט, א."],["1743","106","<b>ובכל תלמוד ירושלמי</b>: מובא גם בסידור שער התפלה יט, ב."],["1744","108","<b>ה\"ה</b>: בתניא: היא."],["1745","107","<b>ובכל תלמוד ירושלמי. . בשם מצוה סתם</b>: ראה פאה פ\"ח, ה\"ח. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380810\" data-slug=\"likkutei-torah\" data-id=\"4001380810\">לקו\"ת פ' ראה כג, ג</a>. תניא מ\"מ הגהות והע\"ק שם."],["1746","105","<b>הצדקה. . ששקולה כנגד. . מצוה סתם</b>: ראה גם אג\"ק מאת כ\"ק אדמו\"ר ח\"ד ע' תיג."],["1747","103","<b>שהפליגו. . כולנה</b>: לשון אדה\"ז ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז מח, ב</a>."],["1748","109","<b>וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה גם לעיל המשך יונתי הערה 27.\n\n<b>ד</b>  הועתק לקמן בפיסקא וביאור הענין.\n\n<b>ה</b>  הועתק בסוף פיסקא הבאה."]]],[2000480225,"ויברכהו<sup data-n=\"1749\">110</sup>, בגדיו הוא בחי'<sup data-n=\"1750\">111</sup> מעהמ\"צ<sup data-n=\"1751\">112</sup> שנק' בגדיו ע\"ש שמהמצות נעשי' לבושי' להנשמה<sup data-n=\"1752\">113</sup>, וכן א' בזהר חמינא בריחא דלבושייכו<sup data-n=\"1753\">114</sup> דלא קריתון ק\"ש, שהכיר הינוקא בבחי' הריח של הלבושי' דר\"י ורי\"ו<sup data-n=\"1754\">115</sup> שלא קראו ק\"ש וכמשנ\"ת מזה בד\"ה וכל שיח השדה<sup data-n=\"1755\">116</sup> טרם יצמח, ושרש ענין מה שע\"י מעהמ\"צ נעשי' לבושי' להנשמה זהו מפני כי המצות בשרשן הם בחי' מקיפי' שהם בחי' רצה\"ע שלמעלה מהחכ' וההשגה כו', כ\"א בחי' ריח, וזהו דכתי' וריח שלמותיך כריח הלבנון<sup data-n=\"1756\">117</sup> פי' שריח הלבושי' דמעהמ\"צ חשובים כ\"כ כמו בחי' ריח הלבנון שהוא ריח דמס\"נ שבאחד<sup data-n=\"1757\">118</sup>, כמ\"ש בהג\"ה לד\"ה בך\"ה בכסליו שבת\"א<sup data-n=\"1758\">119</sup>, וכמ\"ש בלק\"ת ס\"פ שלח בד\"ה וישלח יהושע פ\"ב בענין יריחו שנק' בחי' זו אריך אנפין כו', וזהו ג\"כ ענין הקרבנות שנא' בהם לריח ניחוח<sup data-n=\"1759\">120</sup> כו'.\n<b></b>קיצור. שבזהר ס\"פ ויקהל ובזהר\"ק שם פי' שע\"י התפלה הוא רק להעביר הזוהמא, וע\"י הקטרת עולה מל' דעשיי' מהקלי', ופי' קשיר קשרין שז\"ע חיבור בי\"ע עם האצי' ואצי' עם בחי' שלמעלה מהאצי' מלמטלמ\"ע ומלמעלמ\"ט, ע\"י העשן, ועכשיו בעבודה זהו בכל מאדך בכל ממונך צדקה ששקולה כו', והמצות הם בעשי' כמו הקטרת שהם מסממנים שאין בהם טעם, שהם מבחי' מקיפי' שלמעלה מהשגה, ונק' ריח שלמותיך כו'.\nוהנה פעולת הריח הגשמי הוא שלא תהי' הנפש בבחי' הסתלקות מן המוחין, רק שתשוב ותתגלה מהעלם אל הגילוי, וכן נת' במ\"א בד\"ה עולת תמיד<sup data-n=\"1760\">121</sup> שז\"ע",[["1749","110","<b>וירח את ריח בגדיו ויברכהו</b>: תולדות כז, כז."],["1750","111","<b>בגדיו הוא בחי' מעהמ\"צ</b>: מכאן עד להלן התיבות: ”תלי' כו'\" (שבסוף פיסקא הבאה על יד הערה 133) — ללא הקיצור — ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450572\" data-slug=\"or-hatorah-hb\" data-id=\"8316450572\">אוה\"ת חנוכה ח\"ב ע' 572</a> בשינויים והוספות."],["1751","112","<b>בגדיו. . מעהמ\"צ</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380681\" data-slug=\"likkutei-torah\" data-id=\"4001380681\">לקו\"ת מסעי פט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381258\" data-slug=\"likkutei-torah\" data-id=\"4001381258\">שה\"ש לב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381262\" data-slug=\"likkutei-torah\" data-id=\"4001381262\">לג, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381174\" data-slug=\"likkutei-torah\" data-id=\"4001381174\">ש\"א יא, ב</a>. סידור שער התפלה כז, ב. כח, ד. מאמרי אדה\"א דרושי חתונה ח\"א ע' קכא. לקמן מאמר ד\"ה עשה צדקה ומשפט על יד הערה 22. ו(בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 27."],["1752","113","<b>שמהמצות נעשי' לבושי' להנשמה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>. אגה\"ק סכ\"ט. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">תו\"א מקץ לב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381195\" data-slug=\"likkutei-torah\" data-id=\"4001381195\">לקו\"ת שה\"ש טז, רע\"ג</a>. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע ובהערה 33."],["1753","114","<b>חמינא בריחא דלבושייכו</b>: ראה זהר בלק קפו, א."],["1754","115","<b>דר\"י ורי\"ו</b>: בזהר: ר' יצחק ור' יהודה. במאמר שבהערה שלאח\"ז על יד הערה 16: רי\"ה ור' יוסי. ראה גם סה\"מ תרכ\"ט ע' רנד. מאמרי אדה\"א שמות ח\"א ע' דש. וש\"נ. דברים ח\"ג ע' תשמט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540451\" data-slug=\"torat-chaim\" data-id=\"2300540451\">תו\"ח שמות ח\"א מו, ג</a>. וש\"נ. סה\"מ עטר\"ת ע' תסג. תרפ\"ח ע' קמד."],["1755","116","<b>וכמשנ\"ת מזה בד\"ה וכל שיח השדה</b>: בראשית ב, ה [בדילוג]. ראה גם לעיל מאמר ד\"ה זה ובהנסמן בריש המאמר שם."],["1756","117","<b>וריח שלמותיך כריח הלבנון</b>: שה\"ש ד, יא [ושם: לבנון]."],["1757","118","<b>דמס\"נ שבאחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["1758","119","<b>בהג\"ה לד\"ה בך\"ה בבסליו שבת\"א</b>: ראה אוה\"ת חנוכה ח\"ב ע' רפא."],["1759","120","<b>לריח ניחוח</b>: ויקרא ד, לא."],["1760","121","<b>פעולת הריח. . בד\"ה עולת תמיד</b>: ראה אוה\"ת פינחס כרך ו ע' א'תתקלא."]]],[2000480226,"ריח דקרבנות שלכן ביטל יוחנן כה\"ג את המעוררי'<sup data-n=\"1761\">122</sup>, שהיו אומרים עורה למה תישן<sup data-n=\"1762\">123</sup>, דפי' וענין השינה הוא ע\"ד מ\"ש בת\"ז וכד אנת תסתלק<sup data-n=\"1763\">124</sup> מנייהו<sup data-n=\"1764\">125</sup> אשתארון<sup data-n=\"1765\">126</sup> כגופא בלא נשמתא, וע\"י &lt;59&gt;\nּ ריח והעלאה דקרבנות הי' נמשך הגילוי, והיינו גילוי המוחין בז\"א, ולכן ביטל המעוררי', וכן בנפש האלקי' ענין בחי' השינה הוא, אשר מחמת הקיטורי' העולים מנה\"ב אין אור הנה\"א מתגלה במוח, וז\"ע טמטום המוח<sup data-n=\"1766\">127</sup> כו' שאין האלקות נתפס בו וכמ\"ש בסש\"ב<sup data-n=\"1767\">128</sup>, וע\"י ריח והעלאה מהתפלה שהיא במקום הקרבנות<sup data-n=\"1768\">129</sup> נמשך גילוי המוחין וכן בנפש כו', (ולפ\"ז צ\"ל שא\"כ קרבנות וקטרת שוין, אמנם באמת אינו כן שיש יתרון גדול לקטרת על בחי' הקרבנות כמשית\"ל<sup data-n=\"1769\">130</sup> ), ועד\"ז בענין המצות שנק' ריח בגדיו, ממשיכי' גילוי אוא\"ס ב\"ה בחכ', וכן בנפש ע\"י המעשה שמתקן מעשיו נעשו מוחו ולבו זכים אלף פעמים ככה כמ\"ש בת\"א ר\"פ בראשית בד\"ה השמים כסאי בפי' והארץ הדום רגלי שז\"ע מ\"ש וצדקה תרומם גוי<sup data-n=\"1770\">132</sup> ע\"ש ובהגהות לשם<sup data-n=\"1771\">131</sup> באריכות, שענין הזכות זהו כמו שהריח משיב את הנפש שיאיר במוח ולב בבחי' גילוי הארת האור כו', ולכן על הצדקה שהיא כוללת כל המצות ונק' מצוה סתם כנ\"ל נא' וצדקה תרומם גוי שמתרוממת ועולה למעלה מעלה, וז\"ע בכל מאדך בכל ממונך, והרי באמת פי' בכל מאדך הוא ג\"כ בחי' האהבה שבלי גבול, אלא שצ\"ל דהא בהא תלי' כו'<sup data-n=\"1772\">133</sup>.\n<b>וביאור</b> הענין יובן מגודל מעלת הצדקה גם בפרט מלבד מה שהיא כוללת כלליות כל המצות, דהנה נת\"ל<sup data-n=\"1773\">134</sup> שענין בחי' ירידת הנשמה בגוף שהירידה היא צורך עלי'<sup data-n=\"1774\">135</sup>, שהוא בכדי להיות והרוח תשוב לבחי' האלקי' אשר נתנה<sup data-n=\"1775\">136</sup>, וכמו לע\"ל שיהי' בנתינה דכתי' ונתתי רוחי בכם וחייתם<sup data-n=\"1776\">137</sup> שיהיו חיים",[["1761","122","<b>ביטל יוחנן כה\"ג את המעוררי'</b>: ראה סוטה מז, סע\"א. מח, א."],["1762","123","<b>עורה למה תישן</b>: תהלים מד, כד."],["1763","124","<b>וכד אנת תסתלק</b>: ראה ת\"ז בהקדמה יז, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370167\" data-slug=\"torah-or\" data-id=\"3901370167\">תו\"א מקץ לו, רע\"ג</a>. סידור ערב שבת קסד, סע\"ב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490145\" data-slug=\"or-hatorah-hb\" data-id=\"8316490145\">אוה\"ת וירא כרך ד ע' תשמב</a> ואילך [והוספות בכרך ז ע' תתשצג ואילך]. שעה\"י קל, סע\"א. לקמן מאמר ד\"ה והנה כובע על יד הערה 103. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה למה קדמה שמע לוהי' אם שמוע על יד הערה 44."],["1764","125","<b>מנייהו</b>: גי' אדה\"ז בסידורו."],["1765","126","<b>אשתארון</b>: בהמשך יונתי הנדפס: אשתארן. בת\"ז ובאוה\"ת: אשתארו."],["1766","127","<b>טמטום המוח</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 343."],["1767","128","<b>טמטום המוח. . בסש\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ\"ט</a> ובשיעורים בספר התניא ע' 330 הערה 3."],["1768","129","<b>מהתפלה שהיא במקום הקרבנות</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["1769","130","<b>כמשית\"ל</b>: בהמשך יונתי הנדפס: כמשנת\"ל."],["1770","132","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם: צדקה<sup data-n=\"e167\">ו</sup> — ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 66]."],["1771","131","<b>נעשו מוחו. . בת\"א. . ובהגהות לשם</b>: בראשית א, ב. סה\"מ תרל\"ח ע' רלב ואילך. וש\"נ."],["1772","133","<b>תלי' כו'</b>: ע\"כ מאוה\"ת חנוכה — ראה לעיל הערה 111."],["1773","134","<b>נת\"ל</b>: ראה לעיל המשך יונתי פט\"ו. רפכ\"ב."],["1774","135","<b>שהירידה היא צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["1775","136","<b>והרוח תשוב. . נתנה</b>: ע\"פ קהלת יב ז."],["1776","137","<b>ונתתי רוחי בכם וחייתם</b>: יחזקאל לז, יד.\n\n<b>ו</b>  וכ\"ה בפיסקא הבאה מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a>."]]],[2000480227,"לעולם, וז\"ע כ\"י בתשובה<sup data-n=\"1777\">138</sup> כו', וענין עלי' זו בד\"כ ז\"ע בחי' לאשתאבא בגופא דמלכא<sup data-n=\"1778\">139</sup> שע\"י התשובה תהי' בחי' השבת הנפש למעלה מבחי' מה שנש\"י עלו במח'<sup data-n=\"1779\">140</sup>, שהרי המח' היא רק מלבושי הנפש<sup data-n=\"1780\">141</sup>, והעלי' לאשתאבא<sup data-n=\"1781\">142</sup> בגופא דמלכא גופא דוקא כו', ושעת הכושר בכל יום לבחי' עלי' זו הוא בק\"ש באמרו אחד ואהבת, וכמבואר בספרים שצריך למס\"נ באחד שאין הכוונה על בחי' ציור<sup data-n=\"1782\">144</sup> קדה\"ש<sup data-n=\"1783\">143</sup> בפו\"מ לבד, אלא הכוונה גם ברוחניות והוא ביטול להתכלל באור ה' אחד והוא בחי' ומדריגת יחידה שבנפש, וע\"ז אמר דהע\"ה וביקש מכפירים יחידתי<sup data-n=\"1784\">145</sup>, כי הנה נודע ממארז\"ל ה' שמות נקראו לה נרנח\"י<sup data-n=\"1785\">146</sup>, שה' שמות אלו הם היו<sup data-n=\"1786\">147</sup> מדריגות חלוקות בעבודת ה', שקריאת שם חיה הוא בחי' חכ'<sup data-n=\"1787\">148</sup> שבנפש וכמ\"ש והחכ' תחי'<sup data-n=\"1788\">149</sup> ונשמה הוא בחי' בינה<sup data-n=\"1789\">150</sup> שהוא בחי' השגה כו', אבל בחי' יחידה שבנפש הוא בחי' הרצון פשוט שלמעלה מן החכ'<sup data-n=\"1790\">151</sup>, ונק' יחידה ל' נקבה שמקבלת מיחיד<sup data-n=\"1791\">152</sup> כי הוא רק רצון פשוט לבחי' אוא\"ס יחידו ש\"ע, וכמ\"ש מי לי בשמים<sup data-n=\"1792\">153</sup> ועמך לא חפצתי, וכמשנ\"ת כמ\"פ ששמים וארץ הם ג\"ע העליון והתחתון<sup data-n=\"1793\">154</sup> ובכולם לא חפצתי כ\"א ליכלל",[["1777","138","<b>כ\"י בתשובה</b>: ראה גם לעיל המשך יונתי פי\"ט. וש\"נ."],["1778","139","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 51."],["1779","140","<b>שנש\"י עלו במח'</b>: ראה ב\"ר פ\"א, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380278\" data-slug=\"likkutei-torah\" data-id=\"4001380278\">לקו\"ת בחוקותי מז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">שה\"ש טז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381206\" data-slug=\"likkutei-torah\" data-id=\"4001381206\">יט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381200\" data-slug=\"likkutei-torah\" data-id=\"4001381200\">יז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381202\" data-slug=\"likkutei-torah\" data-id=\"4001381202\">יח, ב</a>. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["1780","141","<b>המח'. . מלבושי הנפש</b>: תניא פ\"ד."],["1781","142","<b>לאשתאבא</b>: מכאן ועד התיבות מחי' מתים (להלן על יד הערה 186) הוא לשון ה<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a> ואילך בשינויים והוספות."],["1782","144","<b>ציור</b>: בהמשך יונתי הנדפס: ציוי. בלקו\"ת כבפנים."],["1783","143","<b>למס\"נ באחד. . בחי' ציור קדה\"ש</b>: ראה (בנוסף ללקו\"ת<sup data-n=\"e168\">ז</sup>) מאמרי אדה\"ז תק\"ע<sup data-n=\"e169\">ח</sup> ע' קכז ושם: בפ\"מ בלבד לכומר וחרב בידו."],["1784","145","<b>מכפירים יחידתי</b>: תהלים לה, יז."],["1785","146","<b>ה' שמות נקראו לה נרנח\"י</b>: ראה ב\"ר פי\"ד, ט. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."],["1786","147","<b>היו</b>: בהמשך יונתי הנדפס: ה'."],["1787","148","<b>חיה הוא בחי' חכ'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ז. לקו\"ת ומקבילו במאמרי אדה\"ז תק\"ע כאן. מאמרי אדה\"א דברים ח\"ב (כאן) ע' תכח (בשם הזהר). וש\"נ. סה\"מ תרל\"ח ע' רפא. וש\"נ."],["1788","149","<b>והחכ' תחי'</b>: קהלת ז, יב [ושם: החכמה — ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 292]."],["1789","150","<b>ונשמה הוא בחי' בינה</b>: ראה גם לקו\"ת־ מאמרי אדה\"ז תק\"ע־ מאמרי אדה\"א דברים ח\"ב (כאן). וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550463\" data-slug=\"torat-chaim\" data-id=\"2300550463\">תו\"ח תצוה ח\"ב שמט, ג</a>. וש\"נ."],["1790","151","<b>יחידה. . הרצון פשוט שלמעלה מן החכ'</b>: ראה גם לקו\"ת וסה\"מ שבהערה שלפנ\"ז. סה\"מ תרס\"ח ע' רנב (ושם: כדמשמע בשער הקדו' להרח\"ו). מאמר ד\"ה משכני ליל א' דשבועות תשח\"י."],["1791","152","<b>יחידה שמקבלת מיחיד</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. דרושים שבהערה שלפנ\"ז. מאמרי אדה\"א קונטרסים ע' שצא. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי הב' על יד הערה 78. (בחלק ההנחות) הנחה ד\"ה יפה שעה אחת הב' על יד הערה 85."],["1792","153","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לעיל המשך יונתי ובהערה 546."],["1793","154","<b>ששמים וארץ הם ג\"ע העליון והתחתון</b>: ראה גם לקו\"ת ומקבילו במאמרי אדה\"ז תק\"ע כאן. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול קרוב לסופו. (בחלק ההנחות) הנחה ד\"ה וביום הביכורים על יד הערה 93. ד\"ה ויאמר משה על יד הערה 72. סה\"מ תרל\"ח ע' מו. וש\"נ.\n\n<b>ז</b>  הועתק גם באוה\"ת תרומה ע' א'שסח.\n\n<b>ח</b>  מקביל ללקו\"ת הנ\"ל."]]],[2000480228,"בעצמותו ית', ע\"י בחי' ההתבוננות שיתבונן שכולם הם רק עמך בטל וטפל כו', ובחי' זו ישנה בכאו\"א מישראל אפי' בפחותי הערך, כי כאו\"א יש בו בטבעו בחי' מס\"נ ורצון זה שלמעלה מהשכל וכמבואר בספרים שגם מי שאין לו אלא נפש, או נפש דנפש מ\"מ גם בחי' יחידה כלולה בה, וע' בשעה\"ק להרח\"ו ז\"ל ח\"ג שע\"ב<sup data-n=\"1794\">155</sup>, &lt;60&gt;\nּ וע' בסש\"ב פ\"ך<sup data-n=\"1795\">156</sup>, אמנם הנה זלעו\"ז עשה האלקי'<sup data-n=\"1796\">157</sup> שגם בסט\"א יש בחי' יחידה<sup data-n=\"1797\">158</sup> זו שהוא בחי' רצון שלמעלה מהשכל והטעם, וע\"כ יכול להיות באדם רצון חזק גם במילי דעלמא כענין בחי' רצון הנ\"ל שבקדושה שהיא ג\"כ למעלה מטו\"ד אם ממשיך עליו עול ד\"א יותר מדי כו', וע\"ד שנת' בת\"א פ' בשלח בד\"ה לסוסתי<sup data-n=\"1798\">159</sup> וכשנעשה התקשרות לזה העולם כ\"כ בחוזק עד שהוא בלי שכל כלל כו', ומקור בחי' זו נק' כפירים כי כחם רב ועצום ויש בהם תגבורת החיות כו', וע\"ז התפלל דהמע\"ה וביקש מכפירים יחידתי, והיינו להיות בחי' היחידה רק בקדושה לבד לבחי' יחידו של עולם, והוא בחי' ומדריגת אהבת בכל מאדך כי בכל נפשך כולל ד' בחי' נרנ\"ח, ובחי' בכל מאדך הוא בחי' יחידה שבנפש כי מאד הוא בלי גבול כו', וזהו בחי' בכל מאדך שארז\"ל בכל ממונך שלכאו' הוא פלא מהו ענין הממון לבחי' מאד שהוא בחי' ומדריגה היותר גבוה שבנפש בחי' יחידה כנ\"ל, אלא הענין הוא כמ\"ש צדקה תרומם גוי וחסד לאומים חטאת (משלי י\"ד ל\"ד) פי' חטאתם הוא הגורם, כי אין צדיק בארץ<sup data-n=\"1799\">160</sup> אשר יעשה טוב ולא יחטא, ועי\"ז נמשך חסד שהוא השפעה לסט\"א, כי ע\"י כל חטא וחטא נעשה פגם בנפש ובמקור שורשה, לפי שמתלבשת בנה\"ב, והיא שמורידה וממשיכה בעמקי הקליפות והבליות<sup data-n=\"1800\">161</sup> בחי' החיצוני' כו', אך הנה",[["1794","155","<b>שגם. . נפש או נפש דנפש. . יחידה. . בשעה\"ק<sup data-n=\"e170\">ט</sup> להרח\"ו ז\"ל ח\"ג שע\"ב</b>: וכ\"ה בלקו\"ת פ' ראה כאן כה, א [ושם: בש\"ק<sup data-n=\"e171\">י</sup>] ובסה\"מ תרס\"ח הנ\"ל. ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה שובה ישראל הב' קרוב לסופו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541002\" data-slug=\"torat-chaim\" data-id=\"2300541002\">תו\"ח בשלח ח\"א קפ, ד</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550148\" data-slug=\"torat-chaim\" data-id=\"2300550148\">משפטים ח\"ב רצג, ד</a>."],["1795","156","<b>וע' בסש\"ב פ\"ך</b>: כ\"ה גם בהמשך יונתי הנדפס."],["1796","157","<b>זלעו\"ז עשה האלקי'</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["1797","158","<b>שגם בסט\"א יש בחי' יחידה</b>: ראה (בנוסף ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">לקו\"ת</a> ומאמרי אדה\"ז תק\"ע כאן) לקו\"ת תצא לז, ג. שע\"ת נד, ג. סה\"מ תרנ\"ה ע' קעז ואילך. תרס\"ח ע' רנב ואילך. מאמר ד\"ה משכני ליל א' דשבועות תשח\"י."],["1798","159","<b>בת\"א פ' בשלח בד\"ה לסוסתי</b>: סד, א."],["1799","160","<b>כי אין צדיק בארץ</b>: קהלת ז, כ [בדילוג]."],["1800","161","<b>והבליות</b>: בהמשך יונתי הנדפס: והכליות. בלקו\"ת: והיכלות.\n\n<b>ט</b>  יש לפענחו א) בשער הקדושה. </b>\n<b>בשערי הקדושה. </b>\n<b>שער הקדושה — כ\"ה בתניא פ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370270\" data-slug=\"torah-or\" data-id=\"3901370270\">תו\"א בא ס, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380868\" data-slug=\"likkutei-torah\" data-id=\"4001380868\">לקו\"ת תצא לז, ד</a> <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380864\" data-slug=\"likkutei-torah\" data-id=\"4001380864\">[ושם לו, ד</a>: בשער הקדושה והנבואה]. </b>\n<b>ראה הערות ותיקונים לתניא שם: בשערי. תניא מהדו\"ק ע' טז ובהערה 41. תניא מ\"מ הגהות והע\"ק שם הערה 69. ברשימת דפוסי הספר (שמופיע בס' טמירין ח\"ב בסופו ירושלים </b>\n<b>שבספר הכוונות קארעץ תקמ\"ד נדפס הספר בשם שער הקדושה. וכן נדפס הספר בשם: שערי הקדושה [גם לפני הדפסת התניא]. וראה גם קובץ אהלי תורה ש\"פ שמות תשנ\"ח גליון פז ע' 18 הערה 1.\n\n<b>י</b>  וכ\"ה בהקדמת הרח\"ו שם: וקראתיו שערי קדושה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380092\" data-slug=\"likkutei-torah\" data-id=\"4001380092\">לקו\"ת ויקרא ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380111\" data-slug=\"likkutei-torah\" data-id=\"4001380111\">צו ח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380317\" data-slug=\"likkutei-torah\" data-id=\"4001380317\">במדבר ב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380489\" data-slug=\"likkutei-torah\" data-id=\"4001380489\">שלח מד, סע\"ב</a><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380704\" data-slug=\"likkutei-torah\" data-id=\"4001380704\">1. מסעי צה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380705\" data-slug=\"likkutei-torah\" data-id=\"4001380705\">צה, ב</a>. פ' ראה כז, א. שה\"ש יח, ד. כח, ג.\n1)וכנראה שכצ\"ל במפתח שמות ספרים ואנשים בסו\"ס לקו\"ת בערכו."]]],[2000480229,"הצדקה תרומם גוי, להיות בחי' גוי אחד בארץ, והיינו שגם נה\"ב תתעלה ע\"י הצדקה שאדם עושה שעי\"ז היא נפרדת ונבדלת מן הרע הגמור, ומתרוממת גם היא להיות כל מדותי' ולבושיה לה' לבדו, והגם<sup data-n=\"1801\">162</sup> כי כל המצות הם בשביל בירור הנה\"ב כמ\"ש במ\"א בענין לא ניתנו המצות אלא לצרף בהן את הבריות<sup data-n=\"1802\">163</sup> שקאי על נה\"ב<sup data-n=\"1803\">164</sup>, מ\"מ אין<sup data-n=\"1804\">165</sup> לך מצוה שנפש החיונית מתלבשת בה כ\"כ כמו מצות<sup data-n=\"1805\">166</sup> הצדקה, שבכל המצות אין מתלבש בהן רק כח אחד מנפש החיונית בשעת מעשה המצוה לבד, אבל בצדקה שאדם נותן מיגיע כפיו הרי כל כח נפשו החיוני' מלובשת<sup data-n=\"1806\">167</sup> בעשיית מלאכתו או עסק אחר שמשתכר<sup data-n=\"1807\">168</sup> בו מעות אלו, וכשנותנין<sup data-n=\"1808\">169</sup> לצדקה הרי כל נפשו החיונית עולה לה', וגם מי שאינו נהנה מיגיעו מ\"מ הואיל שבמעות<sup data-n=\"1809\">170</sup> אלו הי' יכול<sup data-n=\"1810\">171</sup> לקנות חיי נפשו החיונית ה\"ה<sup data-n=\"1811\">172</sup> נותן חיי נפשו לה', ולכן ארז\"ל שמקרבת את הגאולה<sup data-n=\"1812\">173</sup> לפי שבצדקה אחת מעלה הרבה מנפש החיונית מה שלא הי' יכול להעלות ממנה כ\"כ כחות בכמה<sup data-n=\"1813\">174</sup> מצות אחרות<sup data-n=\"1814\">175</sup>, ועל בחי' השבת הנפש זו הפליגו רז\"ל ואמרו במקום שבע\"ת עומדי'<sup data-n=\"1815\">176</sup> צ\"ג א\"י לעמוד<sup data-n=\"1816\">177</sup> כי כל המדות דנה\"ב בעצם מציאותן הן תקיפין וחזקים יותר מהמדות הקדושות דנה\"א, וכמו בגשמיות הבהמות והחיות הם בעלי כח וגבורה יותר מהאדם<sup data-n=\"1817\">178</sup>, שהטעם הוא לפי שבשרשם הן מבחי' היותר גבוה מאד נעלה בחי' יד החזקה<sup data-n=\"1818\">179</sup>, רק שירדו ונפלו למטה מטה, ואמנם כד אתכפי' ואתהפכא מחשוכא לנהורא<sup data-n=\"1819\">180</sup> הרי נכלל בחי' תוקף זה בקדושה, וזו היא מעלת בע\"ת שהוא בחילא יתיר<sup data-n=\"1820\">181</sup> כמ\"ש במ\"א, וזהו שביקש דהע\"ה שינצל מכפירים יחידתי, שלהיות כי יש בחי' יחידה שהוא בחי' תוקף והתגברות &lt;61&gt;\nּ הרצון שלמעלה מהטעם גם בסט\"א, ונק' כפירים כמ\"ש הכפירים",[["1801","162","<b>והגם. . הנפש זו</b>: בלקו\"ת כאן ליתא."],["1802","163","<b>לא ניתנו המצות. . את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד."],["1803","164","<b>הבריות שקאי על נה\"ב</b>: ראה לעיל המשך יונתי ספ\"ח. וש\"נ."],["1804","165","<b>אין. . אחרות</b>: לשון אדה\"ז ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז</a> (בשינויים קלים)."],["1805","166","<b>כמו מצות</b>: שם: כבמצות."],["1806","167","<b>מלובשת</b>: שם: מלובש"],["1807","168","<b>שמשתכר</b>: שם: שנשתכר."],["1808","169","<b>וכשנותנין</b>: שם ובהמשך יונתי הנדפס: וכשנותנן."],["1809","170","<b>שבמעות</b>: בתניא: ובמעות."],["1810","171","<b>יכול</b>: בהמשך יונתי הנדפס: יכולים. בתניא כבפנים."],["1811","172","<b>ה\"ה</b>: בתניא: הרי"],["1812","173","<b>שמקרבת את הגאולה</b>: ב\"ב י, א."],["1813","174","<b>כחות בכמה</b>: בתניא: כחות ובחי' בכמה."],["1814","175","<b>מצות אחרות</b>: שם: מצות מעשיות אחרות."],["1815","176","<b>במקום שבע\"ת עומדי'</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a>. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח."],["1816","177","<b>לעמוד</b>: בהמשך יונתי הנדפס ניתוסף: כו'. ולהעיר שגם בלקו\"ת כאן נמצאת תיבה זו, אלא ששם לא העתיק התיבות שלפנ\"ז: צ\"ג א\"י לעמוד."],["1817","178","<b>הבהמות. . בעלי כח. . יותר מהאדם</b>: ראה גם (בנוסף <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381269\" data-slug=\"likkutei-torah\" data-id=\"4001381269\">לקו\"ת</a> כאן) לקו\"ת שה\"ש לה, סע\"א ואילך."],["1818","179","<b>יד החזקה</b>: בא יג, ט. ראה גם מאו\"א מערכת יד אות ה."],["1819","180","<b>כד אתכפי' ואתהפכא מחשוכא לנהורא</b>: ראה זהר בהקדמה ד, א. סה\"מ תרכ\"ט ע' פח ואילך. וש\"נ. מאמר ד\"ה זאת חוקת התורה ש\"פ פרה תשכ\"ו."],["1820","181","<b>בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540123\" data-slug=\"torat-chaim\" data-id=\"2300540123\">תו\"ח שמות ח\"א לז, א</a>. וש\"נ."]]],[2000480230,"שואגים לטרף<sup data-n=\"1821\">182</sup> שהוא התגברות החיות גבור כארי<sup data-n=\"1822\">183</sup> כו', ולזה ביקש דוד ואמר מכפירים יחידתי שתהי' יחידתי מקושר בקשר אמיץ וחזק להשי\"ת לבדו, ולא תפול ח\"ו בידי החיצוני' שנק' כפירים שהוא הארי' כמו שהוא בשה\"כ, וזהו וצדקה תרומם גוי שיתהפכו המדות שבנה\"ב לדבקה בו ית', והוא ע\"י הצדקה כי במדה שאדם מודד<sup data-n=\"1823\">184</sup> בה מודדין לו שכמו שהוא מרחם על העני ונותן צדקה להחיות רוח שפלים<sup data-n=\"1824\">185</sup> ממתי רעב, כך למעלה מתגלגלים עליו רחמים רבים ממקור הרחמים האמיתים על נפשו לרוממה משפלותה וטומאתה וכמ\"ש מחי' מתים<sup data-n=\"1825\">186</sup> ברחמים רבים<sup data-n=\"1826\">187</sup>, שמאן דנפיל מדרגי' אקרי מית<sup data-n=\"1827\">188</sup> (וכמו העני שאין עני אלא בדעת<sup data-n=\"1828\">189</sup> חשוב כמת<sup data-n=\"1829\">190</sup> מחמת הנפילה) וע\"י בחי' רחמים רבים נמשך בחי' תחה\"מ כו'<sup data-n=\"1830\">191</sup>.",[["1821","182","<b>הכפירים שואגים לטרף</b>: תהלים קד, כא."],["1822","183","<b>גבור כארי</b>: אבות פ\"ה, מ\"כ."],["1823","184","<b>במדה שאדם מודד</b>: סוטה ח, ב במשנה."],["1824","185","<b>להחיות רוח שפלים</b>: ישעי' נז, טו. ראה גם סה\"מ תרל\"ג ח\"ב ע' תסה ובהנסמן שם."],["1825","186","<b>מחי' מתים</b>: ע\"כ הוא לשון הלקו\"ת — ראה לעיל הערה 142."],["1826","187","<b>מחי' מתים ברחמים רבים</b>: נוסח שמו\"ע."],["1827","188","<b>שמאן דנפיל מדרגי' אקרי מית</b>: ראה זהר אד\"ר נשא קלה, ב. מאמרי אדה\"א דברים ח\"ד ע' תתצד. וש\"נ."],["1828","189","<b>שאין עני אלא בדעת</b>: ראה כתובות סח, א. נדרים מא, א."],["1829","190","<b>עני. . חשוב כמת</b>: נדרים סד, ב. זהר רע\"מ משפטים קיט, א. רש\"י שמות ד, יט."],["1830","191","<b>כו'</b>: בהמשך יונתי הנדפס: כנ\"ל."]]],[2000480231,"<h3>עשה צדקה ומשפט כו'</h3>\n<b>בס\"ד פ' חיי</b>\n<b></b>צדקה תרומם כו' כובע ישועה שריון כו' משפט - ב' קיצורים\nחיי שרה\n<b>עשה</b> צדקה ומשפט<sup data-n=\"1831\">1</sup> נבחר לה' מזבח (משלי ך\"א ג'), וארז\"ל (סוכה דמ\"ט<sup data-n=\"1832\">2</sup> ) אמר ר\"א גדול צדקה ומשפט יותר מקרבנות<sup data-n=\"1833\">3</sup>, שנא' עשה כו' מזבח, ופרש\"י מזבח, חטאת ואשם ועולה ושלמים, ולכאורה אינו מובן איך יהי' הצדקה ומשפט",[["1831","1","<b>עשה צדקה ומשפט</b>: אודות מאמר זה נרשם בס' התולדות של כ\"ק אדמו\"ר מהר\"ש (קה\"ת תש\"ז ע' 53): צדקה תרומם כו' כובע ישועה שריון כו' משפט — ב' קיצורים —\nהמאמר (לאחר הפתיחה עד לקמן על יד הערה 116) הוא לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450574\" data-slug=\"or-hatorah-hb\" data-id=\"8316450574\">אוה\"ת חנוכה ח\"ב ע' 574-572</a> בהוספות ושינויים. ולסיומו ראה אגה\"ק ס\"י.\nמאמר זה הובא לקמן במאמר ד\"ה והנה כובע בסיומו על יד הערה 124. נזכר גם ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301820157\" data-slug=\"likkutei-sichot\" data-id=\"1301820157\">לקו\"ש</a> פינחס כרך לח ע' 113 בהערה.\nכנראה למאמר זה נתכוון בסה\"מ תרמ\"ג ע' מו [ושם: די\"א סממני הקטרת כולם דומם. . מעהמ\"צ. . בדברי' גשמיים שהם דוממים. . ועמ\"ש בהדרושים השייכים לד\"ה יונתי תר\"מ על נייר פערטיל] ראה לקמן על יד הערה 28.\nהנחת<sup data-n=\"e172\">*</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לקמן (בחלק הנחותיו)."],["1832","2","<b>סוכה דמ\"ט</b>: ע\"ב."],["1833","3","<b>גדול צדקה. . מקרבנות</b>: בסוכה שם: גדול העושה צדקה יותר מכל הקרבנות. ובילקוט שמעוני עה\"פ אמר ר\"א גדול העושה צדקה ומשפט ממי שהקריב כל הקרבנות<sup data-n=\"e173\">א</sup>."],["e172","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>א</b>  ראה ג\"כ ירושלמי ברכות פ\"ב, ה\"א: חביב עלי משפט וצדקה שאתה עושה יותר מן הקרבנות."]]],[2000480232,"גדול יותר מקרבנות, ויובן זה בהקדם עוד שייכות ענין מעהמ\"צ לקטרת, שעכשיו בעבודה ענין הקטרת היא מעהמ\"צ שנתלבשו בדברים גשמיים דוקא, ע\"פ המד\"ר בפ' נשא, קטרת הוא תרי\"ג<sup data-n=\"1834\">4</sup> מצות כי הקוף באתב\"ש הוא ד', ונמצא כי ד' עם אותיות טרת מתיבת קטרת הוא תרי\"ג, א\"כ גם המד\"ר מפרש שענין בחי' הקטרת הוא תרי\"ג מצות שנתלבשו בעשיי' דוקא, וכללותם הוא הצדקה כנ\"ל<sup data-n=\"1835\">5</sup>. והענין הוא כמ\"ש בילקוט ר\"פ תשא שע\"י הצדקה בנדבת המשכן, עי\"ז נא' כי תשא את ראש בנ\"י<sup data-n=\"1836\">6</sup>, ושזהו ענין צדקה תרומם גוי<sup data-n=\"1837\">7</sup>, והיינו כי לא כל הנשמה מלובשת בגוף רק ניצוץ והארה ממנה בלבד ועיקרה ושרשה נשאר למעלה בבחי' מקיף, והניצוץ המתפשט למטה נק' רגל לגבי בחי' עליונה שלמעלה שנק' בחי' ראש<sup data-n=\"1838\">8</sup>, וע\"ז אמרו אע\"ג דאיהו לא חזי מזלייהו חזי<sup data-n=\"1839\">9</sup> ששם היא רואה ושומעת הכרוזי' שלמעלה כו', ומזה נופלים הרהורי תשובה<sup data-n=\"1840\">10</sup> לאדם כי שרש הנשמה היא רואה ג\"כ, והיינו גילוי אלקות שבבחי' ראי' אלא שחזי הוא ל' תרגום בחי' אחוריי' דלה\"ק<sup data-n=\"1841\">11</sup> כמ\"ש מזה במ\"א, וב' בחי' אלו ז\"ע יעקב וישראל<sup data-n=\"1842\">12</sup>, כי יעקב הוא בחי' יו\"ד עקב<sup data-n=\"1843\">13</sup>, שבחי' יו\"ד נמשך בבחי' עקב כו', וז\"ע בחי' הנשמה שבגוף, ובחי' ישראל הוא לי ראש<sup data-n=\"1844\">14</sup> שזהו בחי' מקור הנשמה כמ\"ש בלק\"ת גבי עשי\"ת בד\"ה ממעמקי' קראתיך<sup data-n=\"1845\">15</sup>, ולכן ענין כי תשא את ראש ז\"ע הגבהת הנשמה שבגוף להתקשר ולהתחבר לשרשה ומקורה, וע' מזה בד\"ה יונתי שבלק\"ת<sup data-n=\"1846\">16</sup> בפי' קומי לך, ובד\"ה במדבר סיני<sup data-n=\"1847\">17</sup> כו' שאו את &lt;62&gt;\nּ ראש כו' לבחי' לגלגלותם בחי' גלגלתא שלמעלה מהשכל, ובד\"ה כי תצא<sup data-n=\"1848\">18</sup> בענין אשת יפ\"ת כו', ועלייה זה נמשך ע\"י הצדקה וזהו וצדקה תרומם גוי<sup data-n=\"1849\">19</sup> כו', ולכן פי' במשנה בכל מאדך בכל ממונך<sup data-n=\"1850\">20</sup> שע\"י בחי' הצדקה תתרומם הנפש לבוא לבחי' האהבה דבכל",[["1834","4","<b>המד\"ר. . קטרת הוא תרי\"ג</b>: במד\"ר פי\"ג, טו-טז. רש\"י נשא ז, כ."],["1835","5","<b>וכללותם הוא הצדקה כנ\"ל</b>: ראה המאמר שנדפס לפנ\"ז על יד הערה 104 ואילך. וש\"נ."],["1836","6","<b>כי תשא את ראש בנ\"י</b>: תשא ל, יב."],["1837","7","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["1838","8","<b>כי. . ראש</b>: לשון אדה\"ז ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370387\" data-slug=\"torah-or\" data-id=\"3901370387\">תו\"א תשא פו, ב</a> (בשינויים — צויין אליו באוה\"ת כאן). ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פי\"ט. וש\"נ."],["1839","9","<b>אע\"ג דאיהו. . מזלייהו חזי</b>: מגילה ג, א."],["1840","10","<b>הכרוזי'. . הרהורי תשובה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">לקו\"ת תצא לז, ג</a>. המשך תרס\"ו ע' שצט."],["1841","11","<b>תרגום בחי' אחוריי' דלה\"ק</b>: ראה טעהמ\"צ פ' ואתחנן ענין שמו\"ת. שעהמ\"צ שם. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450434\" data-slug=\"or-hatorah-hb\" data-id=\"8316450434\">אוה\"ת</a> צפני' כרך ב ע' תתקד."],["1842","12","<b>וב' בחי' אלו ז\"ע יעקב וישראל</b>: ראה (בנוסף לאוה\"ת כאן) לקו\"ת שבהערה 15. מאמרי אדה\"א בראשית ס\"ע קט ואילך וש\"נ. הנחות תקע\"ז ע' שא. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 16."],["1843","13","<b>יעקב. . יו\"ד עקב</b>: ראה תו\"א ר\"פ ויצא. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 483."],["1844","14","<b>ישראל הוא לי ראש</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה. שע\"ת צד, ד הערה 26. סה\"מ תרל\"ח ע' קז. וש\"נ."],["1845","15","<b>בלק\"ת. . בד\"ה ממעמקי' קראתיך</b>: דרושים לר\"ה סב, ג."],["1846","16","<b>בד\"ה יונתי שבלק\"ת</b>: שה\"ש יז, א."],["1847","17","<b>ובד\"ה במדבר סיני</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380313\" data-slug=\"likkutei-torah\" data-id=\"4001380313\">לקו\"ת במדבר א, ב</a>."],["1848","18","<b>ובד\"ה כי תצא</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380861\" data-slug=\"likkutei-torah\" data-id=\"4001380861\">לקו\"ת תצא לו, סע\"א</a> ואילך."],["1849","19","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם: צדקה<sup data-n=\"e174\">ב</sup> — ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 66]."],["1850","20","<b>במשנה בכל מאדך בכל ממונך</b>: ראה ואתחנן ו, ה. ברכות נד, א. לעיל מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 102.\n\n<b>ב</b>  וכ\"ה באוה\"ת כאן. ראה גם לעיל על יד הערה 7."]]],[2000480233,"מאדך בלי גבול<sup data-n=\"1851\">21</sup>. וז\"ע ריח בגדיו שהם המצות<sup data-n=\"1852\">22</sup> שנק' בגדיו שמעוררי' וממשיכים בחי' זו, וכענין אמשיך רוח ואייתי רוח<sup data-n=\"1853\">23</sup>, כי רוח וריח ענין אחד הוא, והיינו שממשיך גילוי הנשמה במוחו<sup data-n=\"1854\">24</sup>, וע\"ד שא' עד יערה עלינו<sup data-n=\"1855\">25</sup> רוח ממרום כו', וכ\"ה עכשיו כשמאיר גילוי בחי' שרש הנשמה כמו שהיא למעלה בחי' יחידה שבנפש, בבחי' הנשמה המלובשת בגוף, ע\"י בחי' ההעלאה דריח בגדיו דמעהמ\"צ, וזהו ג\"כ ענין בשמים ראש<sup data-n=\"1856\">26</sup>, שהוא גילוי בחי' ראש של הנשמה שז\"ע בחי' בשמים וריח כו', ויתפרש ג\"כ ע\"פ משנ\"ת לעיל שלכן נמשלו מעהמ\"צ בקטרת<sup data-n=\"1857\">27</sup> שכשם שהקטרת הם מסממנים דוממים<sup data-n=\"1858\">28</sup> כן המצות נתלבשו בעשיית דברים הגשמיים דוקא, ונת' במ\"א שענין הקטרת הוא בחי' העלאת האותיות<sup data-n=\"1859\">29</sup> שהם דוממים<sup data-n=\"1860\">30</sup> ועד\"ז הוא ג\"כ במעשה המצות, וע' בת\"א בד\"ה מזוזה מימין וביאורו<sup data-n=\"1861\">31</sup> איך<sup data-n=\"1862\">32</sup> ע\"י העלאת האותיות שע\"י קיום המצות נמשך אור החכ' כו'.\n<b></b>קיצור. שלבוא לבחי' בכל מאדך בלי גבול זהו ע\"י בכל ממונך כי צדקה תרומם גוי, תשא את ראש שיאיר בחי' מקור הנשמה בנשמה המלובשת בגוף, וז\"ע בשמים ראש כו'.\nוזהו<sup data-n=\"1863\">33</sup> שאה\"כ וילבש צדקה כשריון וכובע ישועה בראשו (ישעי' סי' נ\"ט י\"ז), דהנה פי' כובע ישועה היינו בחי' תוספת הארה והמשכה<sup data-n=\"1864\">35</sup> מבחי' אור א\"ס המאציל העליון ב\"ה, ביתר שאת על ההארה וההשפעה<sup data-n=\"1865\">36</sup> שבתחילת האצי'",[["1851","21","<b>דבכל מאדך בלי גבול</b>: ראה אגה\"ק סי\"ז. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 99."],["1852","22","<b>ריח בגדיו שהם המצות</b>: תולדות כז, כז. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380681\" data-slug=\"likkutei-torah\" data-id=\"4001380681\">לקו\"ת מסעי פט, ב</a>. לעיל מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 112."],["1853","23","<b>אמשיך רוח ואייתי רוח</b>: ראה זהר תרומה קסב, ריש ע\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדה\"א בראשית ע' רל. וש\"נ."],["1854","24","<b>במוחו</b>: בהמשך יונתי הנדפס: במוח. באוה\"ת כבפנים."],["1855","25","<b>עד יערה עלינו</b>: ישעי' לב, טו."],["1856","26","<b>בשמים ראש</b>: תשא ל, כג."],["1857","27","<b>משנ\"ת. . נמשלו מעהמ\"צ בקטרת</b>: ראה גם המאמר שנדפס לפנ\"ז סביבות הערה 109."],["1858","28","<b>שהקטרת הם מסממנים דוממים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370136\" data-slug=\"torah-or\" data-id=\"3901370136\">תו\"א וישב כט, ב</a>. ש\"א יא, א ובהערה 28. סה\"מ תרמ\"ג ע' מו. בהערה שלפנ\"ז."],["1859","29","<b>הקטרת. . העלאת האותיות</b>: ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 33: כ\"ה בכהאריז\"ל בכ\"מ. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370135\" data-slug=\"torah-or\" data-id=\"3901370135\">תו\"א וישב כט, א</a> ואילך. ש\"א ע' 10 ואילך. אוה\"ת כאן ע' 562."],["1860","30","<b>האותיות שהם דוממים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו\"א בראשית ד, א</a>. סידור שער התפלה כג, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670215\" data-slug=\"torat-chaim\" data-id=\"2300670215\">תו\"ח בראשית כא, ד</a>."],["1861","31","<b>בת\"א בד\"ה מזוזה מימין וביאורו</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">מג, א</a> ואילך."],["1862","32","<b>איך</b>: בהמשך יונתי הנדפס: ואיך. באוה\"ת כבפנים."],["1863","33","<b>וזהו</b>: לשון אוה\"ת חנוכה כאן ע' רפז ס\"ט."],["1864","35","<b>והמשכה</b>: באגה\"ק ואוה\"ת כאן: והשפעה."],["1865","36","<b>וההשפעה</b>: באוה\"ת כאן ניתוסף: מבחי' אוא\"ס המאציל העליון ב\"ה. ולהעיר שתיבות אלו נמצאים גם בשורה שלפנ\"ז."]]]]});
